#!/usr/bin/env bash
# install.sh — LLM API Proxy installer
# Generated by build-installer.sh — do not edit manually.
#
# Usage: download and externally verify the signed installer bundle, then run:
#        sudo bash install.sh [install|upgrade|reconfigure|uninstall] [OPTIONS]

# Apply strict mode for real execution only. When the installer is sourced for
# unit testing (`source install.sh.template --source-only`), inheriting
# `set -euo pipefail` into the BATS shell breaks BATS' own error handling
# (failing assertions stop emitting TAP results — "Executed 0 instead of N").
# The `--source-only` sentinel is passed as $1 at source time, so we can detect
# the test context here and skip strict mode; real CLI invocations never pass
# `--source-only` as $1, so their behavior is unchanged.
if [[ "${1:-}" != "--source-only" ]]; then
    set -euo pipefail
fi

# ── Full-script parse guarantee ───────────────────────────────────────────────
# Wrapping the entire body in _main() forces bash to parse through the closing
# brace before executing anything. This guarantees that all
# variable definitions—including EMBED_* injected at the bottom by
# build-installer.sh—are parsed and available before main() runs.
# The old tmpfile re-exec pattern is no longer needed.
_main() {

# ── Constants ────────────────────────────────────────────────────────────────
INSTALLER_VERSION="0.0.130"
# Reviewed production trust anchor. A downloaded public key is accepted only
# when its primary fingerprint matches this exact value.
RELEASE_SIGNING_FINGERPRINT="4F2BBCD92F7AEC826BF4C156D6443D2B4B6AB71F"
# shellcheck disable=SC2034  # Used by phase functions appended by build-installer.sh
INSTALL_DIR_LINUX="/opt/llm-api-proxy"
# shellcheck disable=SC2034
INSTALL_DIR_MACOS="/usr/local/lib/llm-api-proxy"
# shellcheck disable=SC2034
METADATA_DIR_LINUX="/etc/llm-api-proxy"
# shellcheck disable=SC2034
METADATA_DIR_MACOS="${HOME}/.config/llm-api-proxy"
# shellcheck disable=SC2034
SERVICE_USER="llm-proxy"
LOG_FILE="/tmp/llm-api-proxy-install-$(date +%Y%m%d-%H%M%S).log"
CLEANUP_FILES=()
REMOTE_CHECKSUMS_FILE=""
REMOTE_SIGNATURE_FILE=""

# Privilege escalation — empty when already root, "sudo" otherwise
if [[ $EUID -eq 0 ]]; then
    SUDO=""
else
    SUDO="sudo"
fi

# ── Security ─────────────────────────────────────────────────────────────────
umask 077

# ── Signal traps ─────────────────────────────────────────────────────────────
cleanup() {
    if declare -F database_abort_rollback >/dev/null 2>&1; then
        database_abort_rollback || true
    fi
    local file
    for file in "${CLEANUP_FILES[@]}"; do
        rm -rf -- "$file" 2>/dev/null || true
    done
    if [[ "${INSTALL_PHASE:-}" != "" ]]; then
        echo ""
        echo "Installation interrupted during: ${INSTALL_PHASE}"
        echo "System state: phases before '${INSTALL_PHASE}' completed successfully."
        echo "Re-run install.sh to resume."
        echo ""
    fi
}
# Register signal traps for real execution only. A leaked EXIT trap interferes
# with BATS' test teardown/reporting (see the strict-mode guard above).
if [[ "${1:-}" != "--source-only" ]]; then
    trap cleanup EXIT
    trap 'cleanup; exit 130' INT
    trap 'cleanup; exit 143' TERM
fi

# ── Colour output ────────────────────────────────────────────────────────────
if [[ -t 1 ]] && command -v tput &>/dev/null; then
    RED=$(tput setaf 1)
    GREEN=$(tput setaf 2)
    YELLOW=$(tput setaf 3)
    # shellcheck disable=SC2034  # BLUE used by phase functions appended by build-installer.sh
    BLUE=$(tput setaf 4)
    BOLD=$(tput bold)
    RESET=$(tput sgr0)
else
    RED="" GREEN="" YELLOW=""
    # shellcheck disable=SC2034
    BLUE="" BOLD="" RESET=""
fi

# ── Logging ──────────────────────────────────────────────────────────────────
log_init() {
    local safe_args
    safe_args=$(echo "$*" | sed -E 's/(--(github-token|cf-dns-api-token|cf-api-key|restic-repository|restic-password|aws-access-key-id|aws-secret-access-key|postgres-password|kek-hex|proxy-key-pepper|jwt-secret|grafana-password)=)[^ ]*/\1***REDACTED***/g')
    touch "$LOG_FILE"
    chmod 0600 "$LOG_FILE"
    {
        echo "=== LLM API Proxy Installer v${INSTALLER_VERSION} ==="
        echo "Date: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
        echo "User: $(whoami)"
        echo "Args: ${safe_args}"
        echo "---"
    } >> "$LOG_FILE"
}

log() { echo "[$(date -u +%H:%M:%S)] $*" >> "$LOG_FILE"; }

info()  { echo "${GREEN}  ✓${RESET} $*"; log "INFO: $*"; }
warn()  { echo "${YELLOW}  ⚠${RESET} $*"; log "WARN: $*"; }
fail()  { echo "${RED}  ✗${RESET} $*"; log "FAIL: $*"; }
step()  { echo "${BOLD}$*${RESET}"; log "STEP: $*"; }

die() {
    fail "$1"
    echo ""
    echo "Full log: ${LOG_FILE}"
    exit "${2:-1}"
}

# Mask secrets in log output
mask_secret() {
    local val="$1"
    if [[ ${#val} -le 4 ]]; then
        echo "****"
    else
        echo "${val:0:2}***${val: -2}"
    fi
}

# ── Box drawing ──────────────────────────────────────────────────────────────
draw_box() {
    local title="$1"
    shift
    local width=50
    local top_line bottom_line
    top_line="╔$(printf '═%.0s' $(seq 1 $((width - 2))))╗"
    bottom_line="╚$(printf '═%.0s' $(seq 1 $((width - 2))))╝"
    echo "$top_line"
    printf "║  %-$((width - 4))s║\n" "$title"
    echo "╠$(printf '═%.0s' $(seq 1 $((width - 2))))╣"
    for line in "$@"; do
        printf "║  %-$((width - 4))s║\n" "$line"
    done
    echo "$bottom_line"
}

# ── Dialog / whiptail wrapper ────────────────────────────────────────────────
DIALOG_CMD=""

detect_dialog() {
    if command -v dialog &>/dev/null; then
        DIALOG_CMD="dialog"
    elif command -v whiptail &>/dev/null; then
        DIALOG_CMD="whiptail"
    fi
}

# Returns 0=yes, 1=no. Falls back to read prompt if no dialog.
ask_yesno() {
    local title="$1" text="$2" default="${3:-yes}"
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local flags=()
        if [[ "$default" != "yes" ]]; then
            flags+=(--defaultno)
        fi
        "$DIALOG_CMD" "${flags[@]}" --title "$title" --yesno "$text" 12 60
        return $?
    else
        local prompt
        if [[ "$default" == "yes" ]]; then
            prompt="$text [Y/n]: "
        else
            prompt="$text [y/N]: "
        fi
        local answer
        read -r -p "$prompt" answer
        case "${answer,,}" in
            y|yes) return 0 ;;
            n|no)  return 1 ;;
            "")    [[ "$default" == "yes" ]] && return 0 || return 1 ;;
            *)     return 1 ;;
        esac
    fi
}

# Input box. Returns value on stdout. Falls back to read.
ask_input() {
    local title="$1" text="$2" default="${3:-}"
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local result
        # On Escape/cancel, fall back to default rather than propagating non-zero exit
        # (which would kill the script under set -e)
        result=$("$DIALOG_CMD" --title "$title" --inputbox "$text" 10 60 "$default" 3>&1 1>&2 2>&3) \
            || { echo "$default"; return 0; }
        echo "$result"
    else
        local answer
        if [[ -n "$default" ]]; then
            read -r -p "$text [$default]: " answer
            echo "${answer:-$default}"
        else
            read -r -p "$text: " answer
            echo "$answer"
        fi
    fi
}

# Password input (hidden). Falls back to read -s.
ask_password() {
    local title="$1" text="$2"
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local result
        # On Escape/cancel, return empty string rather than propagating non-zero exit
        result=$("$DIALOG_CMD" --title "$title" --passwordbox "$text" 10 60 3>&1 1>&2 2>&3) \
            || { echo ""; return 0; }
        echo "$result"
    else
        local answer
        read -r -s -p "$text: " answer
        echo ""  # newline after hidden input
        echo "$answer"
    fi
}

# Checklist. Returns space-separated selected items. Falls back to numbered menu.
ask_checklist() {
    local title="$1" text="$2"
    shift 2
    # Remaining args: tag description on/off triplets
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local result
        local height=$(( ($# / 3) + 8 ))
        result=$("$DIALOG_CMD" --title "$title" --checklist "$text" "$height" 60 $(($# / 3)) "$@" 3>&1 1>&2 2>&3) || return 1
        echo "$result"
    else
        echo "$text"
        local i=0
        local tags=()
        local descs=()
        local states=()
        while [[ $# -gt 0 ]]; do
            tags+=("$1"); descs+=("$2"); states+=("$3")
            shift 3
            i=$((i + 1))
        done
        for ((j=0; j<${#tags[@]}; j++)); do
            local marker=" "
            [[ "${states[$j]}" == "on" ]] && marker="X"
            echo "  [$marker] $((j+1)). ${descs[$j]}"
        done
        local selected
        # shellcheck disable=SC2034  # `selected` read but intentionally discarded; toggle logic is a future enhancement
        read -r -p "Enter numbers to toggle (e.g., 1 3), or press Enter to accept: " selected
        # Return tags that are currently enabled (simplified fallback — toggle logic in future)
        local result=""
        for ((j=0; j<${#tags[@]}; j++)); do
            if [[ "${states[$j]}" == "on" ]]; then
                result+="${tags[$j]} "
            fi
        done
        echo "$result"
    fi
}

# Single-select radiolist. Returns the tag of the selected item. Falls back to numbered menu.
ask_radiolist() {
    local title="$1" text="$2"
    shift 2
    # Remaining args: tag description on|off triplets (exactly one should be "on")
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local height=$(( ($# / 3) + 8 ))
        local result
        result=$("$DIALOG_CMD" --title "$title" --radiolist "$text" "$height" 60 $(($# / 3)) "$@" 3>&1 1>&2 2>&3) || return 1
        echo "$result"
    else
        echo "$text"
        local tags=() descs=() states=()
        while [[ $# -gt 0 ]]; do
            tags+=("$1"); descs+=("$2"); states+=("$3")
            shift 3
        done
        local default_idx=0
        for ((j=0; j<${#tags[@]}; j++)); do
            local marker=" "
            if [[ "${states[$j]}" == "on" ]]; then
                marker="*"
                default_idx=$((j + 1))
            fi
            echo "  ($marker) $((j+1)). ${descs[$j]}"
        done
        local answer
        # `read` returns 1 on EOF (e.g., non-interactive pipe); `|| true` prevents set -e from aborting
        read -r -p "Enter number [${default_idx}]: " answer || true
        answer="${answer:-$default_idx}"
        # Validate and return tag
        if [[ "$answer" =~ ^[0-9]+$ ]] && (( answer >= 1 && answer <= ${#tags[@]} )); then
            echo "${tags[$((answer - 1))]}"
        else
            # Fall back to the pre-selected default
            echo "${tags[$((default_idx - 1))]}"
        fi
    fi
}

# ── Embedded file extraction ─────────────────────────────────────────────────
extract_file() {
    local var_name="$1" dest="$2" mode="${3:-0640}"
    if [[ -z "${!var_name:-}" ]]; then
        warn "Embedded file '${var_name}' not available — skipping ${dest}"
        return 0
    fi
    $SUDO mkdir -p "$(dirname "$dest")"
    if $SUDO test -d "$dest"; then
        $SUDO rm -rf "$dest"
    fi
    echo "${!var_name}" | base64 -d | $SUDO tee "$dest" > /dev/null
    $SUDO chmod "$mode" "$dest"
}

# ── CLI argument parsing ─────────────────────────────────────────────────────
# shellcheck disable=SC2034  # All OPT_* variables used by phase functions appended by build-installer.sh
COMMAND=""
OPT_VERSION=""
OPT_INSTALL_DIR=""
OPT_NON_INTERACTIVE="false"
OPT_ACCEPT_TOS="false"
OPT_SKIP_SYSTEM_UPGRADE="false"
OPT_SKIP_FIREWALL="false"
OPT_SKIP_SECURITY_UPDATES="false"
OPT_SKIP_CHECKSUM="false"
OPT_VERIFY_SELF_CHECKSUM="false"
OPT_ROLLBACK_BACKUP_ID=""

# Installer-managed database recovery state. These flags let the EXIT/INT/TERM
# cleanup path restore the active database name and resume the prior proxy when
# a rollback is interrupted before the recovered release is healthy.
CREATED_DATABASE_BACKUP_ID=""
VALIDATED_DATABASE_BACKUP_DUMP=""
VALIDATED_DATABASE_BACKUP_MIGRATION=""
DATABASE_ROLLBACK_PROXY_STOPPED="false"
DATABASE_ROLLBACK_SWAP_ACTIVE="false"
DATABASE_ROLLBACK_ACTIVE_DATABASE=""
DATABASE_ROLLBACK_SAFETY_DATABASE=""
DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
DATABASE_ROLLBACK_SOURCE_VERSION=""
DATABASE_ROLLBACK_SOURCE_METADATA_PATH=""
DATABASE_ROLLBACK_DEPLOY_SNAPSHOT=""
DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="false"
DATABASE_ROLLBACK_RECOVERY_PHASE=""
DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE="false"

# Feature toggles
# WAF defaults to off — the Traefik modsecurity plugin requires command-line
# flags that conflict with compose overlay merging when TLS is also enabled.
# Enable explicitly with --waf when the plugin is properly configured.
OPT_WAF="false"
OPT_TLS="true"
OPT_BACKUP="true"
OPT_MONITORING="true"
OPT_MDNS="true"
# Tracks whether --no-backup was passed explicitly. Distinguishes an operator
# opt-out from the default-on state so an upgrade with omitted backup flags can
# preserve a previously-configured backup instead of disabling it (#1306).
OPT_NO_BACKUP_EXPLICIT="false"

# Core settings
OPT_POSTGRES_PASSWORD=""
OPT_KEK_HEX=""
OPT_PROXY_KEY_PEPPER=""
OPT_JWT_SECRET=""
OPT_LISTEN_PORT="7080"
OPT_FORWARD_PROXY_PORT="7443"
# Track whether each port was set explicitly (CLI flag or PROXY_INSTALL_* env).
# Ports carry non-empty defaults, so the usual `[[ -z ]]` precedence check can't
# tell "operator default" from "operator override". These flags let an upgrade
# preserve a previously-configured custom port (existing .env) when omitted, yet
# still apply an explicit override (#1306).
OPT_LISTEN_PORT_SET="false"
OPT_FORWARD_PROXY_PORT_SET="false"

# Database connection-pool sizing (#1416).
# Empty default means "auto-size from detected CPU count". An explicit value
# (CLI flag / PROXY_INSTALL_* env) overrides the auto-sizing entirely and is
# preserved verbatim across upgrades. The two pools share the Postgres
# max_connections budget (100, see docker/docker-compose.yml); auto-sizing keeps
# control + data well below it with headroom for migrations, psql, and tooling.
OPT_CONTROL_POOL_SIZE=""
OPT_DATA_POOL_SIZE=""

# TLS settings
OPT_DOMAIN=""
OPT_ACME_EMAIL=""
OPT_CF_DNS_API_TOKEN=""
OPT_CF_API_EMAIL=""
OPT_CF_API_KEY=""

# Backup settings
OPT_RESTIC_REPOSITORY=""
OPT_RESTIC_PASSWORD=""
OPT_AWS_ACCESS_KEY_ID=""
OPT_AWS_SECRET_ACCESS_KEY=""
OPT_BACKUP_SCHEDULE="0 2 * * *"
# Tracks whether --backup-schedule was supplied explicitly. When unset, an
# upgrade preserves the existing BACKUP_SCHEDULE from .env instead of resetting
# it to the default (#1306).
OPT_BACKUP_SCHEDULE_SET="false"

# Monitoring settings
OPT_GRAFANA_PASSWORD=""
OPT_GRAFANA_PORT="3000"
OPT_PROMETHEUS_PORT="9090"
# See the port _SET flags above: distinguishes an explicit monitoring-port
# override from the built-in default so an upgrade preserves custom ports (#1306).
OPT_GRAFANA_PORT_SET="false"
OPT_PROMETHEUS_PORT_SET="false"

# Uninstall settings
OPT_PURGE="false"

# GitHub auth settings
OPT_GITHUB_TOKEN=""
OPT_GITHUB_USER=""
GITHUB_TOKEN_RESOLVED=""
GITHUB_USER_RESOLVED=""

# Debug container settings
OPT_DEBUG="false"
OPT_DEBUG_PROFILE="moderate"
OPT_NO_DEBUG="false"
OPT_DEBUG_PROFILE_SET="false"

show_usage() {
    cat <<'USAGE'
LLAP — LLM API Proxy Installer

Usage: install.sh [COMMAND] [OPTIONS]

Commands:
  install         Fresh installation (default if no existing installation)
  upgrade         Upgrade to latest or specified version
  reconfigure     Change settings on existing installation
  uninstall       Remove installation (preserves data unless --purge)

General:
  --help                  Show this usage information and exit
  --installer-version     Show installer version and exit
  --verify-self-checksum  Verify the embedded installer payload and exit
  --rollback-backup=ID    Restore the named installer-created database backup
                          when targeting an older stable version

Authentication:
  --github-token=TOKEN    GitHub PAT for authenticated GHCR access
  --github-user=USER      GitHub username for docker login

  Token precedence (highest to lowest):
    1. --github-token= (CLI flag)
    2. PROXY_INSTALL_GITHUB_TOKEN (env var)
    3. CR_PAT (env var)
    4. GH_TOKEN (env var)
    5. GITHUB_TOKEN (env var)

  If multiple sources provide different values, a warning is emitted and the
  highest-precedence value is used. If no token is set, the installer works
  identically to before (unauthenticated).

  Security: prefer env vars over --github-token= to avoid token exposure in
  ps output and shell history.

  References:
    CR_PAT:       https://docs.github.com/en/packages/working-with-a-github-packages-registry/working-with-the-container-registry
    GH_TOKEN:     https://cli.github.com/manual/gh_help_environment
    GITHUB_TOKEN: https://docs.github.com/en/actions/security-for-github-actions/security-guides/automatic-token-authentication

Options:
  --version=VER           Pin image version (e.g., 0.1.0, edge)
  --install-dir=PATH      Override install directory
  --non-interactive       Never prompt, fail if required values missing
  --accept-tos            Accept Terms of Service (required for --non-interactive)
  --skip-system-upgrade   Don't offer OS package upgrade
  --skip-firewall         Don't configure the host firewall (default: hardened
                          nftables config is applied/converged automatically)
  --skip-security-updates Don't configure unattended-upgrades
  --skip-checksum         Skip remote checksum verification

Features (all ON by default):
  --no-waf                Disable ModSecurity WAF
  --no-tls                Disable TLS/HTTPS
  --no-backup             Disable backup agent
  --no-monitoring         Disable Prometheus + Grafana
  --no-mdns               Disable mDNS (always disabled on macOS)

Core:
  --postgres-password=    DB password (auto-generated if omitted)
  --kek-hex=              Encryption key (auto-generated if omitted)
  --proxy-key-pepper=HEX  64-char hex proxy key HMAC pepper (auto-generated if not set)
                          MUST match source server for credential migrations
  --listen-port=          Proxy HTTP service port (default: 7080)
  --forward-proxy-port=   Forward proxy CONNECT port (default: 7443)
  --control-pool-size=N   DB control-plane pool size (default: auto-sized from
                          CPU count: cpus*2, clamped to [8,32])
  --data-pool-size=N      DB data-plane pool size (default: auto-sized from CPU
                          count: cpus*4, clamped to [20,56])
                          Both auto-size by detected CPU count so the sum stays
                          well below Postgres max_connections=100; an explicit
                          value pins the pool and is preserved across upgrades.
                          Env: PROXY_INSTALL_CONTROL_POOL_SIZE /
                          PROXY_INSTALL_DATA_POOL_SIZE

TLS:
  --domain=               Public hostname
  --acme-email=           Let's Encrypt email
  --cf-dns-api-token=     Cloudflare scoped API token
  --cf-api-email=         Cloudflare global key email (legacy)
  --cf-api-key=           Cloudflare global API key (legacy)

Backup:
  --restic-repository=    Restic repo URL
  --restic-password=      Restic encryption password
  --aws-access-key-id=    S3 access key
  --aws-secret-access-key= S3 secret key
  --backup-schedule=      Cron expression (default: "0 2 * * *")

Monitoring:
  --grafana-password=     Grafana admin password (auto-generated)
  --grafana-port=         Grafana port (default: 3000)
  --prometheus-port=      Prometheus port (default: 9090)

Uninstall:
  --purge                 Also remove Docker volumes (DATABASE LOSS)

Debug containers:
  --debug                 Enable debug-mode sidecar containers
  --debug-profile=PROFILE Debug detail level: minimal, moderate, or full (default: moderate)
  --no-debug              Disable debug-mode sidecar containers (overrides --debug and env vars)

  Env vars:
    PROXY_INSTALL_DEBUG=true|false
    PROXY_INSTALL_DEBUG_PROFILE=minimal|moderate|full

  Note: --debug-profile= without effective debug mode (i.e. when --no-debug is also given)
        is validated after .env state is loaded, not during argument parsing.
USAGE
}

# shellcheck disable=SC2034  # All variables set here are used by phase functions appended by build-installer.sh
parse_args() {
    while [[ $# -gt 0 ]]; do
        case "$1" in
            install|upgrade|reconfigure|uninstall)
                COMMAND="$1" ;;
            --help|-h)
                show_usage; exit 0 ;;
            --installer-version)
                echo "install.sh version ${INSTALLER_VERSION}"; exit 0 ;;
            --verify-self-checksum)
                OPT_VERIFY_SELF_CHECKSUM="true" ;;
            --rollback-backup=*) OPT_ROLLBACK_BACKUP_ID="${1#*=}" ;;
            --version=*)          OPT_VERSION="${1#*=}"; OPT_VERSION="${OPT_VERSION#v}" ;;
            --install-dir=*)      OPT_INSTALL_DIR="${1#*=}" ;;
            --non-interactive)    OPT_NON_INTERACTIVE="true" ;;
            --accept-tos)         OPT_ACCEPT_TOS="true" ;;
            --skip-system-upgrade) OPT_SKIP_SYSTEM_UPGRADE="true" ;;
            --skip-firewall)      OPT_SKIP_FIREWALL="true" ;;
            --skip-security-updates) OPT_SKIP_SECURITY_UPDATES="true" ;;
            --skip-checksum)      OPT_SKIP_CHECKSUM="true" ;;
            --no-waf)             OPT_WAF="false" ;;
            --no-tls)             OPT_TLS="false" ;;
            --no-backup)          OPT_BACKUP="false"; OPT_NO_BACKUP_EXPLICIT="true" ;;
            --no-monitoring)      OPT_MONITORING="false" ;;
            --no-mdns)            OPT_MDNS="false" ;;
            --postgres-password=*) OPT_POSTGRES_PASSWORD="${1#*=}" ;;
            --kek-hex=*)          OPT_KEK_HEX="${1#*=}" ;;
            --proxy-key-pepper=*) OPT_PROXY_KEY_PEPPER="${1#*=}" ;;
            --listen-port=*)      OPT_LISTEN_PORT="${1#*=}"; OPT_LISTEN_PORT_SET="true" ;;
            --forward-proxy-port=*) OPT_FORWARD_PROXY_PORT="${1#*=}"; OPT_FORWARD_PROXY_PORT_SET="true" ;;
            --control-pool-size=*) OPT_CONTROL_POOL_SIZE="${1#*=}" ;;
            --data-pool-size=*)   OPT_DATA_POOL_SIZE="${1#*=}" ;;
            --domain=*)           OPT_DOMAIN="${1#*=}" ;;
            --acme-email=*)       OPT_ACME_EMAIL="${1#*=}" ;;
            --cf-dns-api-token=*) OPT_CF_DNS_API_TOKEN="${1#*=}" ;;
            --cf-api-email=*)     OPT_CF_API_EMAIL="${1#*=}" ;;
            --cf-api-key=*)       OPT_CF_API_KEY="${1#*=}" ;;
            --restic-repository=*) OPT_RESTIC_REPOSITORY="${1#*=}" ;;
            --restic-password=*)  OPT_RESTIC_PASSWORD="${1#*=}" ;;
            --aws-access-key-id=*) OPT_AWS_ACCESS_KEY_ID="${1#*=}" ;;
            --aws-secret-access-key=*) OPT_AWS_SECRET_ACCESS_KEY="${1#*=}" ;;
            --backup-schedule=*)  OPT_BACKUP_SCHEDULE="${1#*=}"; OPT_BACKUP_SCHEDULE_SET="true" ;;
            --grafana-password=*) OPT_GRAFANA_PASSWORD="${1#*=}" ;;
            --grafana-port=*)     OPT_GRAFANA_PORT="${1#*=}"; OPT_GRAFANA_PORT_SET="true" ;;
            --prometheus-port=*)  OPT_PROMETHEUS_PORT="${1#*=}"; OPT_PROMETHEUS_PORT_SET="true" ;;
            --purge)              OPT_PURGE="true" ;;
            --github-token=*)     OPT_GITHUB_TOKEN="${1#*=}" ;;
            --github-user=*)      OPT_GITHUB_USER="${1#*=}" ;;
            --debug)              OPT_DEBUG="true" ;;
            --debug-profile=*)
                OPT_DEBUG_PROFILE="${1#*=}"
                OPT_DEBUG_PROFILE_SET="true"
                case "$OPT_DEBUG_PROFILE" in
                    minimal|moderate|full) ;;
                    *) die "--debug-profile must be minimal, moderate, or full (got: $OPT_DEBUG_PROFILE)" ;;
                esac ;;
            --no-debug)           OPT_NO_DEBUG="true" ;;
            *)
                die "Unknown option: $1. Run with --help for usage." ;;
        esac
        shift
    done
}

# ── PROXY_INSTALL_* environment variable fallback ────────────────────────────
# CLI flags take precedence. Env vars fill in anything not set via CLI.
# Spec Section 7.9: CLI > env vars > existing .env > interactive prompts.
apply_env_defaults() {
    [[ -z "$OPT_VERSION" ]]            && OPT_VERSION="${PROXY_INSTALL_VERSION:-}"; OPT_VERSION="${OPT_VERSION#v}"
    [[ -z "$OPT_DOMAIN" ]]             && OPT_DOMAIN="${PROXY_INSTALL_DOMAIN:-}"
    [[ -z "$OPT_ACME_EMAIL" ]]         && OPT_ACME_EMAIL="${PROXY_INSTALL_ACME_EMAIL:-}"
    [[ -z "$OPT_CF_DNS_API_TOKEN" ]]   && OPT_CF_DNS_API_TOKEN="${PROXY_INSTALL_CF_DNS_API_TOKEN:-}"
    [[ -z "$OPT_CF_API_EMAIL" ]]       && OPT_CF_API_EMAIL="${PROXY_INSTALL_CF_API_EMAIL:-}"
    [[ -z "$OPT_CF_API_KEY" ]]         && OPT_CF_API_KEY="${PROXY_INSTALL_CF_API_KEY:-}"
    [[ -z "$OPT_POSTGRES_PASSWORD" ]]  && OPT_POSTGRES_PASSWORD="${PROXY_INSTALL_POSTGRES_PASSWORD:-}"
    [[ -z "$OPT_KEK_HEX" ]]           && OPT_KEK_HEX="${PROXY_INSTALL_KEK_VALUE:-}"
    [[ -z "$OPT_PROXY_KEY_PEPPER" ]] && OPT_PROXY_KEY_PEPPER="${PROXY_INSTALL_PROXY_KEY_PEPPER:-}"
    [[ -z "$OPT_RESTIC_REPOSITORY" ]]  && OPT_RESTIC_REPOSITORY="${PROXY_INSTALL_RESTIC_REPOSITORY:-}"
    [[ -z "$OPT_RESTIC_PASSWORD" ]]    && OPT_RESTIC_PASSWORD="${PROXY_INSTALL_RESTIC_PASSWORD:-}"
    [[ -z "$OPT_AWS_ACCESS_KEY_ID" ]]  && OPT_AWS_ACCESS_KEY_ID="${PROXY_INSTALL_AWS_ACCESS_KEY_ID:-}"
    [[ -z "$OPT_AWS_SECRET_ACCESS_KEY" ]] && OPT_AWS_SECRET_ACCESS_KEY="${PROXY_INSTALL_AWS_SECRET_ACCESS_KEY:-}"
    [[ -z "$OPT_GRAFANA_PASSWORD" ]]   && OPT_GRAFANA_PASSWORD="${PROXY_INSTALL_GRAFANA_PASSWORD:-}"
    # DB pool overrides (#1416): empty stays empty (= auto-size from CPU count).
    # An explicit env value overrides the auto-sizing; CLI flag still wins.
    [[ -z "$OPT_CONTROL_POOL_SIZE" ]]  && OPT_CONTROL_POOL_SIZE="${PROXY_INSTALL_CONTROL_POOL_SIZE:-}"
    [[ -z "$OPT_DATA_POOL_SIZE" ]]     && OPT_DATA_POOL_SIZE="${PROXY_INSTALL_DATA_POOL_SIZE:-}"
    # Ports: CLI flag wins (already sets *_SET). Otherwise an env var both sets
    # the value and marks it explicit so the upgrade reconcile treats it as an
    # override rather than preserving the existing .env value (#1306).
    if [[ "$OPT_LISTEN_PORT_SET" == "false" ]] && [[ -n "${PROXY_INSTALL_LISTEN_PORT:-}" ]]; then
        OPT_LISTEN_PORT="${PROXY_INSTALL_LISTEN_PORT}"; OPT_LISTEN_PORT_SET="true"
    fi
    if [[ "$OPT_FORWARD_PROXY_PORT_SET" == "false" ]] && [[ -n "${PROXY_INSTALL_FORWARD_PROXY_PORT:-}" ]]; then
        OPT_FORWARD_PROXY_PORT="${PROXY_INSTALL_FORWARD_PROXY_PORT}"; OPT_FORWARD_PROXY_PORT_SET="true"
    fi
    if [[ "$OPT_GRAFANA_PORT_SET" == "false" ]] && [[ -n "${PROXY_INSTALL_GRAFANA_PORT:-}" ]]; then
        OPT_GRAFANA_PORT="${PROXY_INSTALL_GRAFANA_PORT}"; OPT_GRAFANA_PORT_SET="true"
    fi
    if [[ "$OPT_PROMETHEUS_PORT_SET" == "false" ]] && [[ -n "${PROXY_INSTALL_PROMETHEUS_PORT:-}" ]]; then
        OPT_PROMETHEUS_PORT="${PROXY_INSTALL_PROMETHEUS_PORT}"; OPT_PROMETHEUS_PORT_SET="true"
    fi
    [[ "$OPT_NON_INTERACTIVE" == "false" ]] && [[ "${PROXY_INSTALL_NON_INTERACTIVE:-}" == "true" ]] && OPT_NON_INTERACTIVE="true"
    [[ "$OPT_ACCEPT_TOS" == "false" ]] && [[ "${PROXY_INSTALL_ACCEPT_TOS:-}" == "true" ]] && OPT_ACCEPT_TOS="true"
    if [[ -z "$OPT_GITHUB_TOKEN" ]]; then OPT_GITHUB_TOKEN="${PROXY_INSTALL_GITHUB_TOKEN:-}"; fi
    if [[ -z "$OPT_GITHUB_USER" ]];  then OPT_GITHUB_USER="${PROXY_INSTALL_GITHUB_USER:-}";  fi
    # Debug container env var fallbacks — only apply when not set via CLI flags
    if [[ "$OPT_DEBUG" == "false" ]] && [[ "$OPT_NO_DEBUG" == "false" ]]; then
        [[ "${PROXY_INSTALL_DEBUG:-}" == "true" ]] && OPT_DEBUG="true"
    fi
    if [[ "$OPT_DEBUG_PROFILE_SET" == "false" ]] && [[ -n "${PROXY_INSTALL_DEBUG_PROFILE:-}" ]]; then
        case "${PROXY_INSTALL_DEBUG_PROFILE}" in
            minimal|moderate|full)
                OPT_DEBUG_PROFILE="${PROXY_INSTALL_DEBUG_PROFILE}"
                OPT_DEBUG_PROFILE_SET="true"
                ;;
            *) die "PROXY_INSTALL_DEBUG_PROFILE must be minimal, moderate, or full (got: ${PROXY_INSTALL_DEBUG_PROFILE})" ;;
        esac
    fi
    # --no-debug always wins: if set, force OPT_DEBUG=false regardless of other flags or env vars
    if [[ "$OPT_NO_DEBUG" == "true" ]]; then
        OPT_DEBUG="false"
    fi
}

# ── URL-safe secret generation ────────────────────────────────────────────────
# Generates a random secret containing only URL-safe characters ([0-9a-f]).
#
# The DB password is embedded UN-ENCODED into the proxy's
# `DATABASE_URL=postgres://proxy:<PW>@localhost:5432/...`. A `/` or `+` (both in
# the base64 alphabet) corrupts the URL authority/path parse — `:5432` is then
# mis-read and the proxy aborts with "invalid port number" before it ever
# connects, breaking a large fraction of fresh installs (#1327).
#
# `openssl rand -hex` emits only [0-9a-f], so the result is always URL-safe and
# never needs percent-encoding. The /dev/urandom fallback (for hosts without
# openssl) is filtered through `tr` to the same alphabet.
#
# Arguments:
#   $1 — number of random bytes (output is 2× this many hex chars). Default 32.
# stdout: a URL-safe hex secret.
gen_urlsafe_secret() {
    local bytes="${1:-32}"
    openssl rand -hex "$bytes" 2>/dev/null \
        || head -c "$bytes" /dev/urandom | od -An -tx1 | tr -d ' \n'
}

# ── Early preflight-tool bootstrap ────────────────────────────────────────────
# Ensures BOTH `curl` and `jq` are available BEFORE the preflight phase, which
# makes remote calls (remote-checksum verification, ToS fetch) and the GHCR
# image-pullable probe (which parses the token-exchange JSON with jq). These are
# otherwise only installed in prepare_prerequisites (Phase 3), so on a minimal
# host (e.g. Debian-13-minimal) every preflight remote fetch would silently
# degrade and the fail-fast image probe could not run (#1325).
#
# Installs whichever of curl/jq is missing (a host can have curl but not jq).
# Best-effort via the detected package manager; failure is non-fatal here
# (individual callers still degrade gracefully), so this never blocks an
# otherwise-fine install.
#
# return: 0 only when BOTH curl and jq are available afterwards, non-zero if
#         either could not be made available.
ensure_preflight_tools() {
    command -v curl &>/dev/null && command -v jq &>/dev/null && return 0

    # Install only what is missing so we never touch already-present tools.
    local -a missing=()
    command -v curl &>/dev/null || missing+=(curl ca-certificates)
    command -v jq &>/dev/null || missing+=(jq)

    step "  Installing preflight tools (${missing[*]})..."
    case "${PKG_MANAGER:-}" in
        apt)
            $SUDO apt-get update -qq >> "$LOG_FILE" 2>&1 || true
            $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \
                "${missing[@]}" >> "$LOG_FILE" 2>&1 || true
            ;;
        dnf|yum)
            $SUDO "$PKG_MANAGER" install -y -q "${missing[@]}" >> "$LOG_FILE" 2>&1 || true
            ;;
        pacman)
            $SUDO pacman -Sy --noconfirm "${missing[@]}" >> "$LOG_FILE" 2>&1 || true
            ;;
        zypper)
            $SUDO zypper -n install "${missing[@]}" >> "$LOG_FILE" 2>&1 || true
            ;;
        brew)
            # brew has no ca-certificates package; install only curl/jq from the list.
            local -a brew_pkgs=()
            local pkg
            for pkg in "${missing[@]}"; do
                [[ "$pkg" == "ca-certificates" ]] || brew_pkgs+=("$pkg")
            done
            [[ ${#brew_pkgs[@]} -gt 0 ]] && { brew install "${brew_pkgs[@]}" >> "$LOG_FILE" 2>&1 || true; }
            ;;
        *)
            warn "Unknown package manager — cannot pre-install curl/jq; relying on later install"
            ;;
    esac

    command -v curl &>/dev/null && command -v jq &>/dev/null
}

# ── Image reference resolution ────────────────────────────────────────────────
# Computes the GHCR server image reference (repo:tag) the install will pull, used
# by the fail-fast GHCR preflight (#1325). Pure: derives from OPT_VERSION and
# OPT_DEBUG, with no side effects. Mirrors the tag that compose-command.sh pulls.
#
# - Stable/edge:  llm-api-proxy/server:<OPT_VERSION|edge>
# - Debug builds: llm-api-proxy/server-debug:<OPT_VERSION|edge>-debug
#
# stdout: "<repo>:<tag>" (without the ghcr.io/ host prefix; the probe adds it).
image_ref_for_version() {
    local version="${OPT_VERSION:-edge}"
    [[ -z "$version" ]] && version="edge"

    if [[ "$OPT_DEBUG" == "true" ]]; then
        printf 'llm-api-proxy/server-debug:%s-debug\n' "$version"
    else
        printf 'llm-api-proxy/server:%s\n' "$version"
    fi
}

# ── GitHub token resolution ───────────────────────────────────────────────────
# Resolves a GitHub PAT from 5 sources in precedence order.
# Sets GITHUB_TOKEN_RESOLVED. Warns on conflict (different values from multiple sources).
# Precedence: CLI --github-token= > PROXY_INSTALL_GITHUB_TOKEN > CR_PAT > GH_TOKEN > GITHUB_TOKEN
resolve_github_token() {
    local -a sources=()
    local -a values=()

    # 1. CLI flag (--github-token=) or PROXY_INSTALL_GITHUB_TOKEN
    #    apply_env_defaults() folds PROXY_INSTALL_GITHUB_TOKEN into OPT_GITHUB_TOKEN,
    #    so we distinguish by checking the raw env var.
    if [[ -n "${OPT_GITHUB_TOKEN:-}" ]]; then
        if [[ -n "${PROXY_INSTALL_GITHUB_TOKEN:-}" ]] && [[ "$OPT_GITHUB_TOKEN" == "$PROXY_INSTALL_GITHUB_TOKEN" ]]; then
            sources+=("--github-token / PROXY_INSTALL_GITHUB_TOKEN")
        else
            sources+=("--github-token")
        fi
        values+=("$OPT_GITHUB_TOKEN")
    elif [[ -n "${PROXY_INSTALL_GITHUB_TOKEN:-}" ]]; then
        sources+=("PROXY_INSTALL_GITHUB_TOKEN")
        values+=("$PROXY_INSTALL_GITHUB_TOKEN")
    fi

    # 2-4. Direct env vars (in precedence order)
    [[ -n "${CR_PAT:-}" ]]       && sources+=("CR_PAT")       && values+=("$CR_PAT")
    [[ -n "${GH_TOKEN:-}" ]]     && sources+=("GH_TOKEN")     && values+=("$GH_TOKEN")
    [[ -n "${GITHUB_TOKEN:-}" ]] && sources+=("GITHUB_TOKEN") && values+=("$GITHUB_TOKEN")

    if [[ ${#values[@]} -eq 0 ]]; then
        log "GitHub token: no token found in any source"
        return 0
    fi

    # Set resolved token to highest-precedence value
    GITHUB_TOKEN_RESOLVED="${values[0]}"
    local winner_source="${sources[0]}"

    # Detect conflicts: check if any other source has a different value
    local i
    for (( i=1; i<${#values[@]}; i++ )); do
        if [[ "${values[$i]}" != "$GITHUB_TOKEN_RESOLVED" ]]; then
            warn "Multiple GitHub token sources with different values. Using ${winner_source}. Ignoring: ${sources[$i]}"
        fi
    done

    log "GitHub token resolved from: ${winner_source} (value: $(mask_secret "$GITHUB_TOKEN_RESOLVED"))"
}

# ── GitHub username detection ─────────────────────────────────────────────────
# Resolves GitHub username for docker login from CLI flag, env vars, or API.
# Sets GITHUB_USER_RESOLVED. Only meaningful when GITHUB_TOKEN_RESOLVED is set.
# Precedence: OPT_GITHUB_USER > GITHUB_USER env var > GitHub API auto-detect
detect_github_user() {
    # 1. CLI flag or PROXY_INSTALL_GITHUB_USER (both folded into OPT_GITHUB_USER)
    if [[ -n "${OPT_GITHUB_USER:-}" ]]; then
        GITHUB_USER_RESOLVED="$OPT_GITHUB_USER"
        log "GitHub user resolved from OPT_GITHUB_USER: ${GITHUB_USER_RESOLVED}"
        return 0
    fi

    # 2. GITHUB_USER env var
    if [[ -n "${GITHUB_USER:-}" ]]; then
        GITHUB_USER_RESOLVED="$GITHUB_USER"
        log "GitHub user resolved from GITHUB_USER env var: ${GITHUB_USER_RESOLVED}"
        return 0
    fi

    # 3. Auto-detect via GitHub API (requires GITHUB_TOKEN_RESOLVED)
    if [[ -z "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        log "GitHub user: no token available, skipping API auto-detect"
        return 0
    fi

    local api_response login
    if api_response=$(curl --disable -fsSL --max-time 10 \
        -H "Authorization: Bearer ${GITHUB_TOKEN_RESOLVED}" \
        "https://api.github.com/user" 2>/dev/null); then
        login=$(echo "$api_response" | jq -r '.login // empty' 2>/dev/null || true)
        if [[ -n "$login" ]] && [[ "$login" != "null" ]]; then
            GITHUB_USER_RESOLVED="$login"
            log "GitHub user auto-detected from API: ${GITHUB_USER_RESOLVED}"
            return 0
        fi
    fi

    log "GitHub user: API auto-detect failed or returned no login — GITHUB_USER_RESOLVED remains empty"
    return 0
}

# ── GHCR API requests ─────────────────────────────────────────────────────────
# ghcr_api_request URL [SCOPE]
# Makes a GHCR v2 API call with OCI token exchange if a PAT is available.
# Falls back to unauthenticated on auth failure. Returns non-zero only if
# both authenticated and unauthenticated requests fail.
#
# Arguments:
#   URL   — the GHCR v2 API URL to request
#   SCOPE — optional OCI scope string (default: derived from URL path,
#            e.g. "repository:llm-api-proxy/server:pull")
#
# stdout: response body on success
# return: 0 on success (authenticated or unauthenticated fallback),
#         non-zero if both paths fail
ghcr_api_request() {
    local url="$1"
    local scope="${2:-}"

    # Derive scope from URL if not provided
    # e.g. https://ghcr.io/v2/llm-api-proxy/server/tags/list
    #   -> repository:llm-api-proxy/server:pull
    if [[ -z "$scope" ]]; then
        local path
        path=$(echo "$url" | sed -E 's|https?://ghcr.io/v2/([^/]+/[^/]+)/.*|\1|')
        scope="repository:${path}:pull"
    fi

    if [[ -n "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        # Exchange PAT for bearer token via GHCR token endpoint.
        # SECURITY: pass credentials via a temp config file so the PAT never
        # appears in curl argv (visible in ps output). The placeholder username
        # "token" is required by the GHCR token endpoint protocol; the actual
        # PAT is the password. GITHUB_USER_RESOLVED is intentionally NOT used here.
        local auth_config bearer token_response
        auth_config=$(mktemp)
        CLEANUP_FILES+=("$auth_config")
        printf 'user = "token:%s"\n' "$GITHUB_TOKEN_RESOLVED" > "$auth_config"
        chmod 0600 "$auth_config"

        local token_url="https://ghcr.io/token?service=ghcr.io&scope=${scope}"
        if token_response=$(curl --disable -fsSL --max-time 10 -K "$auth_config" "$token_url" 2>/dev/null); then
            bearer=$(echo "$token_response" | jq -r '.token // empty' 2>/dev/null || true)
            rm -f "$auth_config"
            CLEANUP_FILES=("${CLEANUP_FILES[@]/$auth_config}")

            if [[ -n "$bearer" ]]; then
                local response
                if response=$(curl --disable -fsSL --max-time 10 \
                    -H "Authorization: Bearer ${bearer}" \
                    "$url" 2>/dev/null); then
                    echo "$response"
                    return 0
                fi
                warn "Authenticated GHCR request failed for ${url}. Retrying unauthenticated."
            fi
        else
            rm -f "$auth_config"
            CLEANUP_FILES=("${CLEANUP_FILES[@]/$auth_config}")
            warn "GHCR token exchange failed. Token may be invalid, expired, or missing read:packages scope. Retrying unauthenticated."
        fi
    fi

    # Unauthenticated fallback
    local response
    if response=$(curl --disable -fsSL --max-time 10 "$url" 2>/dev/null); then
        echo "$response"
        return 0
    fi

    return 1
}

# ── GHCR image manifest existence probe ───────────────────────────────────────
# Returns 0 iff the manifest for <repo>:<tag> is pullable from GHCR — i.e. the
# tag exists AND the resolved credentials (PAT, or anonymous for public images)
# can read it. Used by the fail-fast preflight (#1325) so an image-access/tag
# error surfaces BEFORE any system mutation, not at the deploy step.
#
# Requests the manifest with the standard OCI/Docker manifest Accept types so a
# multi-arch image index is matched. Uses an authenticated bearer token when a
# PAT is available (mirroring ghcr_api_request), falling back to anonymous.
#
# Arguments:
#   $1 — repo (e.g. "llm-api-proxy/server")
#   $2 — tag  (e.g. "0.0.84")
# return: 0 if the manifest is pullable, non-zero otherwise.
ghcr_image_manifest_exists() {
    local repo="$1" tag="$2"
    local url="https://ghcr.io/v2/${repo}/manifests/${tag}"
    local accept="-H"
    local accept_val="Accept: application/vnd.oci.image.index.v1+json,application/vnd.docker.distribution.manifest.list.v2+json,application/vnd.oci.image.manifest.v1+json,application/vnd.docker.distribution.manifest.v2+json"
    local scope="repository:${repo}:pull"

    if [[ -n "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        # SECURITY: pass the PAT via a temp config file (never argv) — see
        # ghcr_api_request for rationale.
        local auth_config bearer token_response
        auth_config=$(mktemp)
        CLEANUP_FILES+=("$auth_config")
        printf 'user = "token:%s"\n' "$GITHUB_TOKEN_RESOLVED" > "$auth_config"
        chmod 0600 "$auth_config"

        local token_url="https://ghcr.io/token?service=ghcr.io&scope=${scope}"
        if token_response=$(curl --disable -fsSL --max-time 10 -K "$auth_config" "$token_url" 2>/dev/null); then
            bearer=$(echo "$token_response" | jq -r '.token // empty' 2>/dev/null || true)
            rm -f "$auth_config"
            CLEANUP_FILES=("${CLEANUP_FILES[@]/$auth_config}")
            if [[ -n "$bearer" ]]; then
                if curl --disable -fsSL --max-time 10 -o /dev/null \
                    "$accept" "$accept_val" \
                    -H "Authorization: Bearer ${bearer}" \
                    "$url" 2>/dev/null; then
                    return 0
                fi
            fi
        else
            rm -f "$auth_config"
            CLEANUP_FILES=("${CLEANUP_FILES[@]/$auth_config}")
        fi
    fi

    # Anonymous fallback: GHCR still requires a (scoped) bearer token even for
    # public images, so exchange anonymously first.
    local anon_token anon_bearer
    if anon_token=$(curl --disable -fsSL --max-time 10 \
            "https://ghcr.io/token?service=ghcr.io&scope=${scope}" 2>/dev/null); then
        anon_bearer=$(echo "$anon_token" | jq -r '.token // empty' 2>/dev/null || true)
        if [[ -n "$anon_bearer" ]]; then
            if curl --disable -fsSL --max-time 10 -o /dev/null \
                "$accept" "$accept_val" \
                -H "Authorization: Bearer ${anon_bearer}" \
                "$url" 2>/dev/null; then
                return 0
            fi
        fi
    fi

    return 1
}

# ── GHCR docker login ─────────────────────────────────────────────────────────
# Authenticates to GHCR via docker login before image pulls.
# Skips silently if no token. Warns and falls back gracefully on failure.
#
# Uses GITHUB_TOKEN_RESOLVED and GITHUB_USER_RESOLVED (set by resolve_github_token
# and detect_github_user respectively).
#
# Does NOT call docker logout — credentials are left in place for future
# upgrade runs.
#
# return: always 0 (failure is non-fatal; Docker will report pull errors)
ghcr_login() {
    if [[ -z "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        return 0
    fi

    if [[ -z "${GITHUB_USER_RESOLVED:-}" ]]; then
        warn "GitHub token set but username not available. Skipping docker login. Set --github-user= or GITHUB_USER to enable authenticated pulls."
        return 0
    fi

    local login_output
    if login_output=$(echo "$GITHUB_TOKEN_RESOLVED" | \
        $SUDO docker login ghcr.io -u "$GITHUB_USER_RESOLVED" --password-stdin 2>&1); then
        info "Authenticated to ghcr.io as ${GITHUB_USER_RESOLVED}"
    else
        warn "docker login ghcr.io failed: ${login_output}. Proceeding without authentication."
    fi
    return 0
}

# ── Setting resolution with 4-tier precedence ───────────────────────────────
# Usage: value=$(resolve_setting "OPT_DOMAIN" "DOMAIN" "Enter your domain" "proxy.example.com")
#   $1 = OPT_* variable name (already set by CLI or env)
#   $2 = .env key name to check in existing install
#   $3 = prompt text for interactive mode
#   $4 = default value (optional)
resolve_setting() {
    local opt_var="$1" env_key="$2" prompt_text="$3" default="${4:-}"
    local current_value="${!opt_var:-}"

    # 1. CLI flag or env var already set — use it
    if [[ -n "$current_value" ]]; then
        echo "$current_value"
        return 0
    fi

    # 2. Existing .env from previous installation
    if $SUDO test -f "${INSTALL_DIR:-}/docker/.env" 2>/dev/null; then
        local env_value
        env_value=$($SUDO grep "^${env_key}=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true)
        if [[ -n "$env_value" ]]; then
            echo "$env_value"
            return 0
        fi
    fi

    # 3. Interactive prompt
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        if [[ -n "$default" ]]; then
            echo "$default"
            return 0
        fi
        die "Required setting missing: ${prompt_text}. Provide via --${opt_var,,} or PROXY_INSTALL_${env_key}."
    fi

    ask_input "Configuration" "$prompt_text" "$default"
}

# Reads a single key from the existing install's docker/.env, if present.
# Echoes the value (empty when the file or key is absent). Used by upgrade
# flows to preserve previously-configured settings when flags are omitted.
# Usage: value=$(existing_env_value "RESTIC_REPOSITORY")
existing_env_value() {
    local env_key="$1"
    $SUDO test -f "${INSTALL_DIR:-}/docker/.env" 2>/dev/null || return 0
    $SUDO grep "^${env_key}=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true
}

# ── Integrity verification ───────────────────────────────────────────────────

sha256_file() {
    local file="$1"
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum -- "$file" | awk '{ print $1 }'
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 -- "$file" | awk '{ print $1 }'
    else
        die "sha256sum or shasum is required for installer integrity verification."
    fi
}

sha256_stdin() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum | awk '{ print $1 }'
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 | awk '{ print $1 }'
    else
        die "sha256sum or shasum is required for installer integrity verification."
    fi
}

verify_self_checksum() {
    local script="${SCRIPT_PATH:-$0}"
    step "Verifying installer integrity..."

    if [[ ! -f "$script" ]]; then
        die "Installer must be downloaded to a regular file before execution. Piped execution cannot bind the running bytes to the signed checksum."
    fi

    local payload
    payload=$(awk '/^# --- BEGIN EMBEDDED FILES ---$/,/^# --- END EMBEDDED FILES ---$/' "$script" \
        | grep -v '^# SELF_CHECKSUM:')
    local computed
    computed=$(printf '%s\n' "$payload" | sha256_stdin)

    local embedded
    embedded=$(grep '^# SELF_CHECKSUM:' "$script" | awk '{print $3}')

    if [[ -z "$embedded" ]] || [[ "$embedded" == "@@SELF_CHECKSUM@@" ]]; then
        warn "No self-checksum embedded (development build) — skipping"
        return 0
    fi

    if [[ "$computed" != "$embedded" ]]; then
        die "Installer integrity check failed. File may be corrupted or tampered with. Re-download from the official source."
    fi
    info "Self-checksum verified"
}

require_file_backed_execution() {
    local source_path="${BASH_SOURCE[0]:-}"
    if [[ -z "$source_path" || ! -f "$source_path" ]]; then
        die "Installer must be downloaded to a regular file before execution. Piped execution is prohibited."
    fi
}

# Decide what to do when remote checksums could not be obtained (network
# failure OR a non-checksums/HTML response). Returns 0 when the caller should
# continue without remote verification (non-interactive policy, or the operator
# explicitly opts to continue); returns 1 when the caller should abort. This is
# the shared fetch-failure policy — a non-checksums response is a fetch failure,
# NOT tampering, so both paths funnel through here instead of die-ing.
_remote_checksum_unavailable() {
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        warn "Continuing without remote verification (non-interactive)"
        return 0
    fi
    if ask_yesno "Checksum Warning" "Could not verify installer against published checksums. Continue anyway?" "no"; then
        return 0
    fi
    return 1
}

download_remote_checksums() {
    local version="${INSTALLER_VERSION}"
    local checksums_url="https://llm-api-proxy.com/.well-known/install-checksums/${version}/SHA256SUMS"

    if [[ -n "$REMOTE_CHECKSUMS_FILE" && -s "$REMOTE_CHECKSUMS_FILE" ]]; then
        return 0
    fi
    if ! command -v curl &>/dev/null; then
        return 1
    fi

    REMOTE_CHECKSUMS_FILE=$(mktemp)
    CLEANUP_FILES+=("$REMOTE_CHECKSUMS_FILE")
    if curl --disable -fsSL --max-time 10 "$checksums_url" \
        -o "$REMOTE_CHECKSUMS_FILE" 2>/dev/null \
        && [[ -s "$REMOTE_CHECKSUMS_FILE" ]]; then
        return 0
    fi
    rm -f -- "$REMOTE_CHECKSUMS_FILE"
    REMOTE_CHECKSUMS_FILE=""
    return 1
}

verify_remote_checksum() {
    if [[ "$OPT_SKIP_CHECKSUM" == "true" ]]; then
        info "Remote checksum verification skipped (--skip-checksum)"
        return 0
    fi

    if ! command -v curl &>/dev/null; then
        die "curl is required for stable installer verification. Use --skip-checksum only if you explicitly accept an unverified installer."
    fi

    local version="${INSTALLER_VERSION}"
    local checksums_url="https://llm-api-proxy.com/.well-known/install-checksums/${version}/SHA256SUMS"

    local remote_checksums
    if ! download_remote_checksums; then
        warn "Could not fetch remote checksums from ${checksums_url}"
        _remote_checksum_unavailable && return 0
        die "Remote checksum verification failed. Re-download the installer."
    fi
    remote_checksums="$(<"$REMOTE_CHECKSUMS_FILE")"

    # Guard: if the endpoint returned HTML (e.g. the website SPA index.html via a
    # Cloudflare Pages catch-all) instead of a real SHA256SUMS file, the response
    # is NOT a checksums document. Treat this as "could not fetch remote
    # checksums" — the SAME <!doctype|<html guard verify_gpg_signature() uses —
    # and honor the non-interactive policy. It MUST NOT be reported as a tamper
    # die, otherwise every staged public installer fails preflight when the
    # endpoint is misconfigured (issue #1333).
    if printf '%s' "$remote_checksums" | head -1 | grep -qi '<!doctype\|<html'; then
        warn "Checksums endpoint returned HTML instead of checksums (${checksums_url})"
        _remote_checksum_unavailable && return 0
        die "Remote checksum verification failed. Re-download the installer."
    fi

    local script="${SCRIPT_PATH:-$0}"
    if [[ ! -f "$script" ]]; then
        die "Installer must be downloaded to a regular file before remote checksum verification."
    fi
    local local_hash
    local_hash=$(sha256_file "$script")

    local entry_count expected_hash
    entry_count="$(
        awk 'NF == 2 && $2 == "install.sh" { count += 1 } END { print count + 0 }' \
            <<< "$remote_checksums"
    )"
    expected_hash="$(
        awk 'NF == 2 && $2 == "install.sh" { print $1 }' <<< "$remote_checksums"
    )"
    if [[ "$entry_count" == "1" ]] \
        && [[ "$expected_hash" =~ ^[[:xdigit:]]{64}$ ]] \
        && [[ "${expected_hash,,}" == "${local_hash,,}" ]]; then
        info "Remote checksum verified"
    else
        die "Installer does not match published checksum. It may have been tampered with."
    fi
}

verify_gpg_signature() {
    if [[ "$OPT_SKIP_CHECKSUM" == "true" ]]; then
        return 0
    fi

    local version="${INSTALLER_VERSION}"
    if [[ ! "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+([.+-][0-9A-Za-z.-]+)?$ ]]; then
        info "Non-release installer version (${version}) — skipping signature verification"
        return 0
    fi

    local gpg_cmd=""
    if command -v gpg &>/dev/null; then
        gpg_cmd="gpg"
    elif command -v gpgv &>/dev/null; then
        gpg_cmd="gpgv"
    else
        die "gpg or gpgv is required for stable installer verification. Install a verifier or explicitly pass --skip-checksum."
    fi

    local sig_url="https://llm-api-proxy.com/.well-known/install-checksums/${version}/SHA256SUMS.sig"

    download_remote_checksums \
        || die "Could not fetch checksums for GPG verification. Use --skip-checksum only if you explicitly accept an unverified installer."

    local sig_file checksums_file keyring_file
    REMOTE_SIGNATURE_FILE=$(mktemp)
    CLEANUP_FILES+=("$REMOTE_SIGNATURE_FILE")
    sig_file="$REMOTE_SIGNATURE_FILE"
    checksums_file="$REMOTE_CHECKSUMS_FILE"
    keyring_file=$(mktemp); CLEANUP_FILES+=("$keyring_file")

    if ! curl --disable -fsSL --max-time 10 "$sig_url" -o "$sig_file" 2>/dev/null \
        || [[ ! -s "$sig_file" ]]; then
        die "Could not fetch GPG signature. Use --skip-checksum only if you explicitly accept an unverified installer."
    fi

    # A 200 SPA fallback is not a signature/checksum artifact and is fatal for
    # stable installers. This was the v0.0.124 production failure mode.
    if head -1 "$sig_file" | grep -qi '<!doctype\|<html'; then
        die "Downloaded signature is not a valid armored signature."
    fi
    if head -1 "$checksums_file" | grep -qi '<!doctype\|<html'; then
        die "Downloaded checksums are not a valid SHA256SUMS document."
    fi

    grep -q '^-----BEGIN PGP SIGNATURE-----$' "$sig_file" \
        || die "Downloaded signature is not a valid armored signature."
    [[ "$(awk 'NF { line = $0 } END { print line }' "$sig_file")" \
        == "-----END PGP SIGNATURE-----" ]] \
        || die "Downloaded signature is not a valid armored signature."

    [[ -n "${EMBED_gpg_public_key:-}" ]] \
        || die "Embedded release signing public key is missing."
    if ! printf '%s' "$EMBED_gpg_public_key" | base64 --decode > "$keyring_file" 2>/dev/null; then
        : > "$keyring_file"
        printf '%s' "$EMBED_gpg_public_key" | base64 -D > "$keyring_file" 2>/dev/null \
            || die "Embedded release signing public key is invalid."
    fi
    grep -q '^-----BEGIN PGP PUBLIC KEY BLOCK-----$' "$keyring_file" \
        || die "Embedded release signing public key is invalid."

    local status valid_fingerprint primary_fingerprint
    if [[ "$gpg_cmd" == "gpg" ]]; then
        local actual_fingerprint tmpring
        actual_fingerprint="$(
            gpg --batch --no-autostart --show-keys --with-colons \
                "$keyring_file" 2>/dev/null \
                | awk -F: '$1 == "fpr" { print $10; exit }'
        )" || true
        [[ "$actual_fingerprint" =~ ^[[:xdigit:]]{40}$ ]] \
            || die "Embedded release signing public key is invalid."
        [[ "${actual_fingerprint^^}" == "$RELEASE_SIGNING_FINGERPRINT" ]] \
            || die "Embedded release signing public key fingerprint mismatch."

        tmpring=$(mktemp -d); CLEANUP_FILES+=("$tmpring")
        chmod 0700 "$tmpring"
        printf 'no-autostart\n' > "${tmpring}/common.conf"
        gpg --batch --no-autostart --homedir "$tmpring" \
            --import "$keyring_file" >/dev/null 2>&1 \
            || die "Embedded release signing public key is invalid."
        if ! status="$(
            gpg --batch --no-autostart --homedir "$tmpring" --status-fd 1 \
                --verify "$sig_file" "$checksums_file" 2>/dev/null
        )"; then
            die "GPG signature verification failed. Installer may have been tampered with."
        fi
    else
        local gpgv_keyring
        gpgv_keyring=$(mktemp); CLEANUP_FILES+=("$gpgv_keyring")
        if ! awk '
            /^-----BEGIN PGP PUBLIC KEY BLOCK-----$/ { in_key = 1; next }
            in_key && /^$/ { in_data = 1; next }
            in_data && /^=/ { exit }
            in_data && /^-----END PGP PUBLIC KEY BLOCK-----$/ { exit }
            in_data { print }
        ' "$keyring_file" | base64 --decode > "$gpgv_keyring" 2>/dev/null; then
            : > "$gpgv_keyring"
            awk '
                /^-----BEGIN PGP PUBLIC KEY BLOCK-----$/ { in_key = 1; next }
                in_key && /^$/ { in_data = 1; next }
                in_data && /^=/ { exit }
                in_data && /^-----END PGP PUBLIC KEY BLOCK-----$/ { exit }
                in_data { print }
            ' "$keyring_file" | base64 -D > "$gpgv_keyring" 2>/dev/null \
                || die "Embedded release signing public key is invalid."
        fi
        [[ -s "$gpgv_keyring" ]] \
            || die "Embedded release signing public key is invalid."
        if ! status="$(
            gpgv --status-fd 1 --keyring "$gpgv_keyring" \
                "$sig_file" "$checksums_file" 2>/dev/null
        )"; then
            die "GPG signature verification failed. Installer may have been tampered with."
        fi
    fi

    valid_fingerprint="$(
        awk '$1 == "[GNUPG:]" && $2 == "VALIDSIG" { print $3; exit }' <<< "$status"
    )"
    primary_fingerprint="$(
        awk '$1 == "[GNUPG:]" && $2 == "VALIDSIG" { print $NF; exit }' <<< "$status"
    )"
    if [[ "${valid_fingerprint^^}" != "$RELEASE_SIGNING_FINGERPRINT" ]] \
        && [[ "${primary_fingerprint^^}" != "$RELEASE_SIGNING_FINGERPRINT" ]]; then
        die "GPG signature fingerprint mismatch. Installer may have been tampered with."
    fi
    info "GPG signature verified"
}

# ── Platform detection ───────────────────────────────────────────────────────

# shellcheck disable=SC2034  # OS_ID, OS_VERSION, OS_CODENAME, PKG_MANAGER, ARCH, IS_MACOS,
# INSTALL_DIR, METADATA_DIR, PREFLIGHT_*, EXISTING_INSTALL are read by phase functions
# appended by build-installer.sh
OS_ID=""
OS_VERSION=""
OS_CODENAME=""
PKG_MANAGER=""
ARCH=""
IS_MACOS="false"
INSTALL_DIR=""
METADATA_DIR=""
PREFLIGHT_PASS=()
PREFLIGHT_WARN=()
PREFLIGHT_FAIL=()
PREFLIGHT_INFO=()

# macOS Docker Desktop host-networking state (set by detect_docker_desktop_version
# and enable_docker_desktop_host_networking).
# shellcheck disable=SC2034  # Read by deploy_extract_files and deploy_write_compose_command
MACOS_HOST_NETWORKING="false"
DOCKER_DESKTOP_VERSION=""
DOCKER_DESKTOP_HOST_NET_CAPABLE="false"

detect_os() {
    if [[ "$(uname -s)" == "Darwin" ]]; then
        IS_MACOS="true"
        OS_ID="macos"
        OS_VERSION=$(sw_vers -productVersion 2>/dev/null || echo "unknown")
        PKG_MANAGER="brew"
        INSTALL_DIR="${OPT_INSTALL_DIR:-$INSTALL_DIR_MACOS}"
        # shellcheck disable=SC2034  # METADATA_DIR used by phase functions appended by build-installer.sh
        METADATA_DIR="$METADATA_DIR_MACOS"
        # mDNS is always disabled on macOS — Docker Desktop's host networking is
        # layer-4 only (TCP/UDP). Multicast does not cross the Docker Desktop VM
        # boundary regardless of whether host networking is enabled.
        # shellcheck disable=SC2034  # OPT_MDNS used by phase functions appended by build-installer.sh
        OPT_MDNS="false"
        return 0
    fi

    INSTALL_DIR="${OPT_INSTALL_DIR:-$INSTALL_DIR_LINUX}"
    # shellcheck disable=SC2034  # METADATA_DIR used by phase functions appended by build-installer.sh
    METADATA_DIR="$METADATA_DIR_LINUX"

    if [[ ! -f /etc/os-release ]]; then
        die "Cannot detect OS — /etc/os-release not found. Supported: Debian, Ubuntu, RHEL, Fedora, Arch, openSUSE."
    fi

    # shellcheck source=/dev/null
    source /etc/os-release 2>/dev/null || true
    OS_ID="${ID:-unknown}"
    OS_VERSION="${VERSION_ID:-unknown}"
    OS_CODENAME="${VERSION_CODENAME:-}"

    case "$OS_ID" in
        debian|ubuntu)     PKG_MANAGER="apt" ;;
        rhel|centos|rocky|almalinux|fedora)
                           PKG_MANAGER="dnf"
                           command -v dnf &>/dev/null || PKG_MANAGER="yum" ;;
        arch|manjaro)      PKG_MANAGER="pacman" ;;
        opensuse*|sles)    PKG_MANAGER="zypper" ;;
        *)
            warn "Unrecognized OS: ${OS_ID}. Proceeding as best-effort."
            PKG_MANAGER="unknown" ;;
    esac
    log "Detected OS: ${OS_ID} ${OS_VERSION} (${OS_CODENAME:-n/a}), pkg: ${PKG_MANAGER}"
}

detect_arch() {
    local raw_arch
    raw_arch=$(uname -m)
    case "$raw_arch" in
        x86_64|amd64)   ARCH="amd64" ;;
        aarch64|arm64)   ARCH="arm64" ;;
        *)               die "Unsupported architecture: $raw_arch. Supported: amd64, arm64." ;;
    esac
    log "Detected arch: ${ARCH}"
}

detect_virtualization() {
    local virt="bare-metal"
    if command -v systemd-detect-virt &>/dev/null; then
        virt=$(systemd-detect-virt 2>/dev/null || echo "bare-metal")
    elif [[ -f /proc/cpuinfo ]]; then
        grep -qi "hypervisor" /proc/cpuinfo && virt="vm"
    fi
    PREFLIGHT_INFO+=("Virtualization: ${virt}")
    log "Virtualization: ${virt}"
}

# ── Docker Desktop host-networking detection (macOS only) ────────────────────

# Returns the path to Docker Desktop's Info.plist.
# Checks system /Applications first, then user ~/Applications.
# Returns 1 if Docker.app is not found in either location.
# This function is mockable in tests via `export -f _docker_desktop_plist_path`.
_docker_desktop_plist_path() {
    local system_path="/Applications/Docker.app/Contents/Info.plist"
    local user_path="${HOME}/Applications/Docker.app/Contents/Info.plist"
    if [[ -f "$system_path" ]]; then
        echo "$system_path"
    elif [[ -f "$user_path" ]]; then
        echo "$user_path"
    else
        return 1
    fi
}

# Detects the Docker Desktop version from Info.plist and sets:
#   DOCKER_DESKTOP_VERSION          — raw version string (e.g. "4.34.0")
#   DOCKER_DESKTOP_HOST_NET_CAPABLE — "true" if version ≥ 4.34, "false" otherwise
#
# Calls _docker_desktop_plist_path() (mockable in tests) to locate the plist.
# If the plist cannot be found or parsed, capability is set to "false" (safe default).
detect_docker_desktop_version() {
    local plist_path="" version="" major="" minor=""

    # Get plist path — this function is mockable in tests
    if plist_path=$(_docker_desktop_plist_path 2>/dev/null) && [[ -f "$plist_path" ]]; then
        # Parse CFBundleShortVersionString — handle text plist format.
        # Use || true so grep non-match (exit 1) does not abort under set -e.
        version=$(grep -A1 'CFBundleShortVersionString' "$plist_path" 2>/dev/null | \
            grep -o '[0-9][0-9]*\.[0-9][0-9]*\.[0-9][0-9]*' 2>/dev/null | head -1 || true)
        if [[ -z "$version" ]]; then
            # Try PlistBuddy for binary plist
            version=$(/usr/libexec/PlistBuddy -c "Print CFBundleShortVersionString" "$plist_path" 2>/dev/null | \
                grep -o '[0-9][0-9]*\.[0-9][0-9]*\.[0-9][0-9]*' 2>/dev/null | head -1 || true)
        fi
    fi

    # Note: do NOT fall back to `docker version` here — the Docker engine version
    # is not the same as Docker Desktop version. If the plist is absent, we cannot
    # determine DD version and must treat it as not capable.

    DOCKER_DESKTOP_VERSION="${version:-}"

    if [[ -z "$version" ]]; then
        DOCKER_DESKTOP_HOST_NET_CAPABLE="false"
        return 0
    fi

    # Compare major.minor — extract just first two components
    major=$(echo "$version" | cut -d. -f1)
    minor=$(echo "$version" | cut -d. -f2)

    # ≥4.34 means major>4 OR (major=4 AND minor>=34)
    if [[ "$major" -gt 4 ]] || { [[ "$major" -eq 4 ]] && [[ "$minor" -ge 34 ]]; }; then
        DOCKER_DESKTOP_HOST_NET_CAPABLE="true"
    else
        DOCKER_DESKTOP_HOST_NET_CAPABLE="false"
    fi
}

# Verifies that Docker Desktop prerequisites for host networking are met:
#   1. DOCKER_DESKTOP_HOST_NET_CAPABLE must be "true"
#   2. Docker must be in Linux containers mode
#   3. Enhanced Container Isolation (ECI) must not be enabled
# Returns 0 if all prerequisites pass, 1 otherwise.
check_docker_desktop_host_net_prerequisites() {
    # Must have been detected as capable first
    if [[ "$DOCKER_DESKTOP_HOST_NET_CAPABLE" != "true" ]]; then
        return 1
    fi

    # Capture docker info output once — the mock in tests only handles `docker info`
    # (not `docker info --format`), so we parse raw output ourselves.
    local docker_info
    docker_info=$(docker info 2>/dev/null)

    # First line should be the OS type (linux / windows / darwin)
    local os_type
    os_type=$(echo "$docker_info" | head -1)
    if [[ "$os_type" != "linux" ]]; then
        warn "Docker Desktop is not in Linux containers mode (got: ${os_type:-unknown})"
        return 1
    fi

    # Must NOT have Enhanced Container Isolation enabled
    if echo "$docker_info" | grep -qi "Enhanced Container Isolation.*true"; then
        warn "Enhanced Container Isolation (ECI) is enabled — incompatible with host networking"
        return 1
    fi

    return 0
}

# Runs a Docker container with --network=host to verify host networking works.
# Returns 0 if host networking is functional, 1 otherwise.
check_docker_host_networking() {
    if docker run --rm --network=host alpine:latest \
        sh -c 'ip -6 addr show lo 2>/dev/null | grep -q inet6' 2>/dev/null; then
        return 0
    fi
    return 1
}

# Enables Docker Desktop host networking on macOS (DD 4.34+).
# Sets MACOS_HOST_NETWORKING="true" if host networking is confirmed working.
# Returns 0 on success, 1 if host networking could not be enabled or verified.
enable_docker_desktop_host_networking() {
    if [[ "$DOCKER_DESKTOP_HOST_NET_CAPABLE" != "true" ]]; then
        return 1
    fi

    # Check if host networking is already enabled via smoke test
    if check_docker_host_networking; then
        MACOS_HOST_NETWORKING="true"
        return 0
    fi

    # Non-interactive mode: skip guided enablement
    if [[ "${OPT_NON_INTERACTIVE:-false}" == "true" ]]; then
        warn "Host networking not enabled — using bridge networking (non-interactive mode)"
        return 1
    fi

    # Guided manual enablement
    echo ""
    echo "  Docker Desktop ${DOCKER_DESKTOP_VERSION} supports host networking,"
    echo "  which preserves real client source IPs and improves performance."
    echo ""
    echo "  To enable it:"
    echo "    1. Open Docker Desktop → Settings → Resources → Network"
    echo "    2. Enable 'Enable host networking'"
    echo "    3. Click 'Apply & restart'"
    echo ""
    echo "  ⚠  Restarting Docker Desktop will stop all running containers."
    echo ""
    read -r -p "  Press Enter after enabling host networking in Docker Desktop..."

    # Wait for Docker Desktop to come back
    local attempts=0
    while ! docker info &>/dev/null; do
        attempts=$((attempts + 1))
        if [[ $attempts -ge 30 ]]; then
            warn "Docker Desktop not responding after restart — using bridge networking"
            return 1
        fi
        sleep 2
    done

    # Verify host networking actually works
    if check_docker_host_networking; then
        MACOS_HOST_NETWORKING="true"
        info "Host networking enabled and verified"
        return 0
    else
        warn "Host networking could not be verified — using bridge networking"
        return 1
    fi
}

check_root() {
    if [[ "$IS_MACOS" == "true" ]]; then
        return 0
    fi
    if [[ $EUID -eq 0 ]]; then
        PREFLIGHT_PASS+=("Root access: running as root")
    elif sudo -n true 2>/dev/null; then
        PREFLIGHT_PASS+=("Root access: sudo available")
    else
        PREFLIGHT_FAIL+=("Root access required — after verification run: sudo bash install.sh")
    fi
}

check_ipv6() {
    if [[ "$IS_MACOS" == "true" ]]; then
        PREFLIGHT_PASS+=("IPv6: available (macOS)")
        return 0
    fi
    if [[ -f /proc/sys/net/ipv6/conf/all/disable_ipv6 ]]; then
        local disabled
        disabled=$(cat /proc/sys/net/ipv6/conf/all/disable_ipv6)
        if [[ "$disabled" == "1" ]]; then
            PREFLIGHT_FAIL+=("IPv6: disabled in kernel")
            PREFLIGHT_FAIL+=("  → Enable: sysctl -w net.ipv6.conf.all.disable_ipv6=0")
        else
            PREFLIGHT_PASS+=("IPv6: enabled")
        fi
    elif [[ -d /proc/sys/net/ipv6 ]]; then
        PREFLIGHT_PASS+=("IPv6: kernel support available")
    else
        PREFLIGHT_FAIL+=("IPv6: not available in kernel")
        PREFLIGHT_FAIL+=("  → Rebuild kernel with CONFIG_IPV6=y or load ipv6 module")
    fi
}

_get_total_ram_kb() {
    if [[ "$IS_MACOS" == "true" ]]; then
        sysctl -n hw.memsize 2>/dev/null | awk '{print int($1/1024)}'
    else
        grep MemTotal /proc/meminfo 2>/dev/null | awk '{print $2}'
    fi
}

# ── Database connection-pool auto-sizing (#1416) ─────────────────────────────
# Detect the host's logical CPU count. Prefers `nproc`, falls back to
# getconf/sysctl, then to /proc/cpuinfo, and finally to a conservative 2 when
# nothing reports a usable count. Always echoes a positive integer.
_get_cpu_count() {
    local n=""
    if command -v nproc >/dev/null 2>&1; then
        n=$(nproc 2>/dev/null || true)
    fi
    if [[ -z "$n" || ! "$n" =~ ^[0-9]+$ || "$n" -lt 1 ]]; then
        n=$(getconf _NPROCESSORS_ONLN 2>/dev/null || true)
    fi
    if [[ -z "$n" || ! "$n" =~ ^[0-9]+$ || "$n" -lt 1 ]]; then
        n=$(sysctl -n hw.ncpu 2>/dev/null || true)
    fi
    if [[ -z "$n" || ! "$n" =~ ^[0-9]+$ || "$n" -lt 1 ]]; then
        n=$(grep -c '^processor' /proc/cpuinfo 2>/dev/null || true)
    fi
    if [[ -z "$n" || ! "$n" =~ ^[0-9]+$ || "$n" -lt 1 ]]; then
        n=2
    fi
    printf '%s\n' "$n"
}

# Compute the data-plane (request-path) pool size for a given CPU count.
# Heuristic: data_pool = cpus * 4, clamped to [DB_DATA_POOL_MIN, DB_DATA_POOL_MAX].
# Rationale: the data pool serves the hot request path, which is the bottleneck
# the SEV (#1414) exposed — the old hardcoded 20 starved on a 12-core host. The
# clamp keeps small hosts sane (never below the historical default of 20) and
# keeps large hosts within the Postgres max_connections budget (see below).
# Echoes a positive integer.
_compute_data_pool_size() {
    local cpus="$1"
    local size=$(( cpus * DB_DATA_POOL_PER_CPU ))
    if [[ "$size" -lt "$DB_DATA_POOL_MIN" ]]; then size="$DB_DATA_POOL_MIN"; fi
    if [[ "$size" -gt "$DB_DATA_POOL_MAX" ]]; then size="$DB_DATA_POOL_MAX"; fi
    printf '%s\n' "$size"
}

# Compute the control-plane (background-writer / management) pool size for a
# given CPU count. Heuristic: control_pool = cpus * 2, clamped to
# [DB_CONTROL_POOL_MIN, DB_CONTROL_POOL_MAX]. The old hardcoded 5 was a direct
# contributor to the SEV (#1414): too few control connections meant the
# background write storm starved the request path. The minimum (8) keeps a floor
# above that, and the per-CPU scaling tracks real concurrency.
# Echoes a positive integer.
_compute_control_pool_size() {
    local cpus="$1"
    local size=$(( cpus * DB_CONTROL_POOL_PER_CPU ))
    if [[ "$size" -lt "$DB_CONTROL_POOL_MIN" ]]; then size="$DB_CONTROL_POOL_MIN"; fi
    if [[ "$size" -gt "$DB_CONTROL_POOL_MAX" ]]; then size="$DB_CONTROL_POOL_MAX"; fi
    printf '%s\n' "$size"
}

# Pool-sizing tunables. The Postgres server runs with max_connections=100 (see
# docker/docker-compose.yml). Auto-sizing keeps control + data well below that
# ceiling so migrations, psql, and background tooling always have headroom:
# at the maxima (control 32 + data 56 = 88) there are still 12 connections free.
# These are plain integers (not OPT_* flags) so tests can override them in-shell.
: "${DB_CONTROL_POOL_PER_CPU:=2}"
: "${DB_CONTROL_POOL_MIN:=8}"
: "${DB_CONTROL_POOL_MAX:=32}"
: "${DB_DATA_POOL_PER_CPU:=4}"
: "${DB_DATA_POOL_MIN:=20}"
: "${DB_DATA_POOL_MAX:=56}"

# Resolve the final control/data pool sizes into RESOLVED_CONTROL_POOL_SIZE /
# RESOLVED_DATA_POOL_SIZE. An explicit operator override (OPT_*) — supplied via
# --control-pool-size / --data-pool-size, PROXY_INSTALL_*, or preserved from an
# existing .env by resolve_setting — is honoured verbatim. Otherwise the size is
# auto-computed from the detected CPU count. Each pool resolves independently, so
# an operator may pin one and auto-size the other.
resolve_db_pool_sizes() {
    local cpus
    cpus=$(_get_cpu_count)

    if [[ -n "${OPT_CONTROL_POOL_SIZE:-}" ]]; then
        if [[ ! "$OPT_CONTROL_POOL_SIZE" =~ ^[0-9]+$ || "$OPT_CONTROL_POOL_SIZE" -lt 1 ]]; then
            die "--control-pool-size must be a positive integer (got: $OPT_CONTROL_POOL_SIZE)"
        fi
        RESOLVED_CONTROL_POOL_SIZE="$OPT_CONTROL_POOL_SIZE"
    else
        RESOLVED_CONTROL_POOL_SIZE=$(_compute_control_pool_size "$cpus")
    fi

    if [[ -n "${OPT_DATA_POOL_SIZE:-}" ]]; then
        if [[ ! "$OPT_DATA_POOL_SIZE" =~ ^[0-9]+$ || "$OPT_DATA_POOL_SIZE" -lt 1 ]]; then
            die "--data-pool-size must be a positive integer (got: $OPT_DATA_POOL_SIZE)"
        fi
        RESOLVED_DATA_POOL_SIZE="$OPT_DATA_POOL_SIZE"
    else
        RESOLVED_DATA_POOL_SIZE=$(_compute_data_pool_size "$cpus")
    fi
}

check_ram() {
    local total_kb
    total_kb=$(_get_total_ram_kb)
    local total_mb=$((total_kb / 1024))
    local total_gb=$((total_mb / 1024))

    PREFLIGHT_INFO+=("RAM: ${total_mb} MB (${total_gb} GB)")

    if [[ $total_kb -lt 2097152 ]]; then
        PREFLIGHT_FAIL+=("RAM: ${total_mb} MB — minimum 2 GB required")
        return 1
    elif [[ $total_kb -lt 4194304 ]]; then
        PREFLIGHT_WARN+=("RAM: ${total_mb} MB — 4+ GB recommended for production")
    else
        PREFLIGHT_PASS+=("RAM: ${total_mb} MB (minimum 2 GB)")
    fi
    return 0
}

_get_free_disk_kb() {
    df -k "$1" 2>/dev/null | tail -1 | awk '{print $4}'
}

check_disk() {
    local path="${1:-$INSTALL_DIR}"
    local check_path="$path"
    while [[ ! -d "$check_path" ]] && [[ "$check_path" != "/" ]]; do
        check_path=$(dirname "$check_path")
    done

    local free_kb
    free_kb=$(_get_free_disk_kb "$check_path")
    local free_gb=$((free_kb / 1024 / 1024))

    PREFLIGHT_INFO+=("Disk: ${free_gb} GB free at ${path}")

    if [[ $free_kb -lt 10485760 ]]; then
        PREFLIGHT_FAIL+=("Disk: ${free_gb} GB free — minimum 10 GB required at ${path}")
        return 1
    else
        PREFLIGHT_PASS+=("Disk: ${free_gb} GB free (minimum 10 GB)")
    fi
    return 0
}

check_ports() {
    local -a public_ports=(443 8443)
    local -a localhost_ports=(7080 7443 5432 8500 8180 3000 9090 5353)

    if ! command -v ss &>/dev/null && ! command -v lsof &>/dev/null; then
        PREFLIGHT_WARN+=("Port check: ss/lsof not available — skipping")
        return 0
    fi

    local port proc
    for port in "${public_ports[@]}" "${localhost_ports[@]}"; do
        proc=""
        if command -v ss &>/dev/null; then
            proc=$(ss -tlnp "sport = :${port}" 2>/dev/null | grep -v "^State" | head -1 || true)
        elif command -v lsof &>/dev/null; then
            proc=$(lsof -iTCP:"${port}" -sTCP:LISTEN -P -n 2>/dev/null | tail -1 || true)
        fi
        if [[ -n "$proc" ]]; then
            PREFLIGHT_WARN+=("Port ${port}: in use — ${proc}")
        fi
    done
}

check_docker() {
    if ! command -v docker &>/dev/null; then
        PREFLIGHT_INFO+=("Docker: not installed (will install)")
        return 0
    fi

    local docker_version
    docker_version=$(docker --version 2>/dev/null || echo "unknown")
    PREFLIGHT_INFO+=("Docker: ${docker_version}")

    if docker --version 2>/dev/null | grep -qi "docker.io"; then
        PREFLIGHT_WARN+=("Docker: distro package (docker.io) — official docker-ce recommended")
    fi

    if ! docker compose version &>/dev/null; then
        PREFLIGHT_WARN+=("Docker Compose plugin not found (will install)")
    else
        local compose_version
        compose_version=$(docker compose version --short 2>/dev/null || echo "unknown")
        PREFLIGHT_INFO+=("Docker Compose: ${compose_version}")
    fi
}

check_container() {
    if [[ -f /proc/1/environ ]] && grep -qai "container=lxc" /proc/1/environ 2>/dev/null; then
        PREFLIGHT_FAIL+=("Running inside LXC container — Docker-in-container not supported")
    fi
    if [[ -d /proc/vz ]] && [[ ! -d /proc/bc ]]; then
        PREFLIGHT_FAIL+=("Running inside OpenVZ container — Docker-in-container not supported")
    fi
}

check_internet() {
    local -a hosts=("ghcr.io")
    local host
    for host in "${hosts[@]}"; do
        if ! curl --disable -fsSL --max-time 5 "https://${host}" -o /dev/null 2>/dev/null; then
            if ! ping -c1 -W3 "$host" &>/dev/null; then
                PREFLIGHT_FAIL+=("Cannot reach ${host} — internet connectivity required")
            fi
        fi
    done
}

detect_existing_install() {
    local -a search_paths=(
        "/etc/llm-api-proxy/install.json"
        "${HOME}/.config/llm-api-proxy/install.json"
    )
    if [[ -n "${OPT_INSTALL_DIR:-}" ]]; then
        search_paths=("${OPT_INSTALL_DIR}/install.json" "${search_paths[@]}")
    fi

    local p
    for p in "${search_paths[@]}"; do
        # Use $SUDO for the file test so detection works when the script is
        # run as a non-root user (install.json is typically owned by root).
        if $SUDO test -f "$p" 2>/dev/null; then
            EXISTING_INSTALL="$p"
            local existing_version
            existing_version=$($SUDO jq -r '.version // "unknown"' "$p" 2>/dev/null || echo "unknown")
            local existing_dir
            existing_dir=$($SUDO jq -r '.install_dir // "unknown"' "$p" 2>/dev/null || echo "unknown")
            PREFLIGHT_INFO+=("Existing install: v${existing_version} at ${existing_dir}")
            return 0
        fi
    done
    EXISTING_INSTALL=""
}

# Validate GHCR access to private debug container images.
# Called from run_preflight() when OPT_DEBUG=true.
# Probes server-debug (always) and backup-debug (when OPT_BACKUP=true).
# Gracefully skips the probe if jq is not available.
preflight_debug_registry() {
    [[ "$OPT_DEBUG" == "true" ]] || return 0

    # Graceful degradation: skip probe if jq unavailable
    if ! command -v jq &>/dev/null; then
        warn "jq not available — skipping GHCR debug registry preflight probe"
        return 0
    fi

    # Token is required for private debug images
    if [[ -z "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        die "Debug containers require a GitHub PAT with package:read access. Provide it via --github-token=, PROXY_INSTALL_GITHUB_TOKEN, CR_PAT, GH_TOKEN, or GITHUB_TOKEN."
    fi

    step "  Checking GHCR debug container access..."

    # Probe server-debug
    local server_url="https://ghcr.io/v2/llm-api-proxy/server-debug/tags/list"
    local server_scope="repository:llm-api-proxy/server-debug:pull"
    if ! ghcr_api_request "$server_url" "$server_scope" &>/dev/null; then
        die "Cannot access GHCR package 'server-debug'. Check your token has package:read access to llm-api-proxy/server-debug."
    fi

    # Probe backup-debug only when backups are enabled
    if [[ "$OPT_BACKUP" == "true" ]]; then
        local backup_url="https://ghcr.io/v2/llm-api-proxy/backup-debug/tags/list"
        local backup_scope="repository:llm-api-proxy/backup-debug:pull"
        if ! ghcr_api_request "$backup_url" "$backup_scope" &>/dev/null; then
            die "Cannot access GHCR package 'backup-debug'. Check your token has package:read access to llm-api-proxy/backup-debug."
        fi
    fi

    info "Debug container registry accessible"
}

# Fail-fast (#1325): verify the server image the install will pull is actually
# pullable from GHCR BEFORE the prepare phase mutates the system (Docker install,
# system user, firewall, unattended-upgrades). Previously an image-access or
# bad-tag error only surfaced at the deploy step, after all those mutations.
#
# Records a PREFLIGHT_FAIL (aborting the run before any mutation) when the image
# is not pullable. Skips gracefully only when curl/jq are genuinely unavailable
# AFTER the early ensure_curl bootstrap — in that case the existing deploy-step
# pull error remains the backstop.
preflight_image_pullable() {
    if ! command -v curl &>/dev/null || ! command -v jq &>/dev/null; then
        PREFLIGHT_WARN+=("Skipped GHCR image preflight (curl/jq unavailable) — pull errors will surface at deploy")
        return 0
    fi

    local image_ref repo tag
    image_ref=$(image_ref_for_version)
    repo="${image_ref%%:*}"
    tag="${image_ref##*:}"

    step "  Checking image is pullable from GHCR (${image_ref})..."
    if ghcr_image_manifest_exists "$repo" "$tag"; then
        PREFLIGHT_PASS+=("Image pullable: ghcr.io/${image_ref}")
    else
        if [[ -n "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
            PREFLIGHT_FAIL+=("Cannot pull ghcr.io/${image_ref} — tag missing or token lacks read:packages access")
        else
            PREFLIGHT_FAIL+=("Cannot pull ghcr.io/${image_ref} — tag missing, or image is private (set --github-token=)")
        fi
    fi
}

# Verify the installer and the host privilege boundary before inspecting any
# target release. Durable source recovery is allowed only from this verified
# installer, but must not depend on target registry or image availability.
run_installer_verification() {
    step "Verifying installer and host access..."
    PREFLIGHT_PASS=()
    PREFLIGHT_WARN=()
    PREFLIGHT_FAIL=()
    PREFLIGHT_INFO=()

    # Verification needs curl, while later target preflight also needs jq.
    # Preserve the existing best-effort bootstrap before either use.
    ensure_preflight_tools \
        || warn "curl/jq unavailable — remote verification may fail closed"

    verify_self_checksum
    verify_remote_checksum
    verify_gpg_signature
    check_root

    if [[ ${#PREFLIGHT_FAIL[@]} -gt 0 ]]; then
        draw_box "Installer Verification Results" "${PREFLIGHT_FAIL[@]}"
        fail "Verified installer recovery requires root or non-interactive sudo access."
        return 1
    fi
    info "Installer verification and host access passed"
}

run_preflight() {
    step "[1/5] Running target preflight checks..."
    PREFLIGHT_PASS=()
    PREFLIGHT_WARN=()
    PREFLIGHT_FAIL=()
    PREFLIGHT_INFO=()
    # shellcheck disable=SC2034  # EXISTING_INSTALL used by phase functions appended by build-installer.sh
    EXISTING_INSTALL=""

    preflight_debug_registry
    preflight_image_pullable

    PREFLIGHT_INFO+=("OS: ${OS_ID} ${OS_VERSION} (${ARCH})")
    check_root
    check_ipv6
    check_ram || true
    check_disk "$INSTALL_DIR" || true
    check_container
    check_internet
    check_ports
    check_docker
    detect_virtualization
    detect_existing_install

    local lines=()
    local item
    for item in "${PREFLIGHT_PASS[@]}"; do lines+=("✓ ${item}"); done
    for item in "${PREFLIGHT_WARN[@]}"; do lines+=("⚠ ${item}"); done
    for item in "${PREFLIGHT_FAIL[@]}"; do lines+=("✗ ${item}"); done
    for item in "${PREFLIGHT_INFO[@]}"; do lines+=("  ${item}"); done

    draw_box "Preflight Check Results" "${lines[@]}"

    if [[ ${#PREFLIGHT_FAIL[@]} -gt 0 ]]; then
        echo ""
        echo "${#PREFLIGHT_FAIL[@]} critical failure(s) — cannot proceed."
        echo "Fix the issues above and re-run."
        exit 1
    fi

    if [[ ${#PREFLIGHT_WARN[@]} -gt 0 ]]; then
        if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
            warn "${#PREFLIGHT_WARN[@]} warning(s) — continuing (non-interactive)"
        else
            if ! ask_yesno "Preflight Warnings" "${#PREFLIGHT_WARN[@]} warning(s) found. Continue anyway?" "yes"; then
                die "Aborted by user."
            fi
        fi
    fi

    info "Preflight checks passed"
}

# ── Phase 2: Legal / Terms of Service ────────────────────────────────────────

# shellcheck disable=SC2034  # Used by deploy_write_metadata and main
TOS_URL="https://llm-api-proxy.com/legal/terms"
# shellcheck disable=SC2034
TOS_CONTENT=""
# shellcheck disable=SC2034
TOS_SHA256=""
# shellcheck disable=SC2034
TOS_VERSION=""
# shellcheck disable=SC2034
TOS_ACCEPTED_AT=""

fetch_tos() {
    local fetched
    if fetched=$(curl --disable -fsSL --max-time 15 "$TOS_URL" 2>/dev/null); then
        # Guard: SPA fallback returns HTML instead of plain-text terms
        if printf '%s' "$fetched" | head -1 | grep -qi '<!doctype\|<html'; then
            log "ToS endpoint returned HTML (SPA fallback) — treating as fetch failure"
        else
            TOS_CONTENT="$fetched"
            TOS_SHA256=$(printf '%s' "$TOS_CONTENT" | sha256_stdin)
            log "Fetched ToS from ${TOS_URL} (sha256: ${TOS_SHA256:0:12}...)"
            return 0
        fi
    fi

    if [[ -n "${EMBED_tos_text:-}" ]]; then
        TOS_CONTENT=$(printf '%s' "$EMBED_tos_text" | base64 -d)
        TOS_SHA256=$(printf '%s' "$TOS_CONTENT" | sha256_stdin)
        warn "Could not fetch latest Terms of Service."
        warn "Showing embedded version. Current terms may have changed —"
        warn "review at ${TOS_URL} when online."
        return 0
    fi

    # No plain-text terms available — use a reference notice instead.
    warn "Could not fetch Terms of Service text."
    TOS_CONTENT="$(cat <<TERMS_NOTICE
LLAP Terms of Service

The full Terms of Service are available at:
  ${TOS_URL}

By proceeding with installation you confirm that you have read and
accept the Terms of Service published at the URL above.
TERMS_NOTICE
)"
    TOS_SHA256=$(printf '%s' "$TOS_CONTENT" | sha256_stdin)
    return 0
}

display_tos() {
    local tos_file
    tos_file=$(mktemp); CLEANUP_FILES+=("$tos_file")
    printf '%s\n' "$TOS_CONTENT" > "$tos_file"

    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        "$DIALOG_CMD" --title "Terms of Service" --textbox "$tos_file" 24 78
    elif command -v less &>/dev/null && [[ -t 0 ]]; then
        less "$tos_file"
    else
        echo "═══ Terms of Service ═══"
        printf '%s\n' "$TOS_CONTENT"
        echo "════════════════════════"
    fi
}

run_tos() {
    step "[2/5] Terms of Service"

    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        if [[ "$OPT_ACCEPT_TOS" != "true" ]]; then
            die "Terms of Service acceptance required. Pass --accept-tos to accept."
        fi
        fetch_tos
        # shellcheck disable=SC2034  # Consumed by deploy_write_metadata
        TOS_ACCEPTED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
        info "Terms of Service accepted (non-interactive by $(whoami))"
        return 0
    fi

    # If --accept-tos was passed, skip display and accept immediately
    if [[ "$OPT_ACCEPT_TOS" == "true" ]]; then
        fetch_tos
        # shellcheck disable=SC2034
        TOS_ACCEPTED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
        info "Terms of Service accepted (--accept-tos flag)"
        return 0
    fi

    fetch_tos
    display_tos

    # When stdin is not a tty, interactive prompts are impossible. Proceeding
    # with a verified file in automation implies acceptance.
    if [[ ! -t 0 ]]; then
        info "Terms of Service accepted (proceeding with installation implies acceptance)"
        # shellcheck disable=SC2034
        TOS_ACCEPTED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
        return 0
    fi

    if ! ask_yesno "Terms of Service" "Do you accept the Terms of Service?" "no"; then
        die "You must accept the Terms of Service to install or upgrade llm-api-proxy."
    fi

    # shellcheck disable=SC2034  # Consumed by deploy_write_metadata
    TOS_ACCEPTED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
    info "Terms of Service accepted"
}

# ── Phase 3: Prepare (system modifications) ──────────────────────────────────

prepare_system_upgrade() {
    if [[ "$OPT_SKIP_SYSTEM_UPGRADE" == "true" ]]; then
        info "System package upgrade skipped (--skip-system-upgrade)"
        return 0
    fi

    if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        if ! ask_yesno "System Update" "Update all system packages before proceeding? (recommended)" "yes"; then
            info "System package upgrade skipped by user"
            return 0
        fi
    fi

    step "  Updating system packages..."
    case "$PKG_MANAGER" in
        apt)
            $SUDO apt-get update -qq >> "$LOG_FILE" 2>&1
            $SUDO env DEBIAN_FRONTEND=noninteractive apt-get upgrade -y -qq >> "$LOG_FILE" 2>&1
            ;;
        dnf)    $SUDO dnf upgrade -y -q >> "$LOG_FILE" 2>&1 ;;
        yum)    $SUDO yum update -y -q >> "$LOG_FILE" 2>&1 ;;
        pacman) $SUDO pacman -Syu --noconfirm >> "$LOG_FILE" 2>&1 ;;
        zypper) $SUDO zypper -n update >> "$LOG_FILE" 2>&1 ;;
        brew)   brew update >> "$LOG_FILE" 2>&1 && brew upgrade >> "$LOG_FILE" 2>&1 ;;
        *)      warn "Unknown package manager — skipping system upgrade" ;;
    esac
    info "System packages updated"
}

prepare_prerequisites() {
    step "  Installing prerequisites..."
    local -a pkgs=()

    case "$PKG_MANAGER" in
        apt)
            pkgs=(curl jq ca-certificates gnupg lsb-release)
            if ! command -v dialog &>/dev/null && ! command -v whiptail &>/dev/null; then
                pkgs+=(dialog)
            fi
            $SUDO apt-get update -qq >> "$LOG_FILE" 2>&1
            $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "${pkgs[@]}" >> "$LOG_FILE" 2>&1
            ;;
        dnf|yum)
            pkgs=(curl jq ca-certificates gnupg2)
            command -v dialog &>/dev/null || pkgs+=(dialog)
            $SUDO "$PKG_MANAGER" install -y -q "${pkgs[@]}" >> "$LOG_FILE" 2>&1
            ;;
        pacman)
            pkgs=(curl jq ca-certificates gnupg)
            command -v dialog &>/dev/null || pkgs+=(dialog)
            $SUDO pacman -S --noconfirm --needed "${pkgs[@]}" >> "$LOG_FILE" 2>&1
            ;;
        zypper)
            pkgs=(curl jq ca-certificates gpg2)
            command -v dialog &>/dev/null || pkgs+=(dialog)
            $SUDO zypper -n install "${pkgs[@]}" >> "$LOG_FILE" 2>&1
            ;;
        brew)
            for pkg in curl jq gnupg; do
                brew list "$pkg" &>/dev/null || brew install "$pkg" >> "$LOG_FILE" 2>&1
            done
            ;;
    esac
    detect_dialog
    info "Prerequisites installed"
}

prepare_docker() {
    if command -v docker &>/dev/null; then
        if docker --version 2>/dev/null | grep -qi "docker.io"; then
            warn "Distro Docker package detected. Official docker-ce recommended."
            if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
                if ask_yesno "Docker" "Replace distro Docker with official docker-ce?" "yes"; then
                    case "$PKG_MANAGER" in
                        apt) $SUDO apt-get remove -y docker.io docker-doc docker-compose >> "$LOG_FILE" 2>&1 ;;
                        dnf|yum) $SUDO "$PKG_MANAGER" remove -y docker docker-common >> "$LOG_FILE" 2>&1 ;;
                    esac
                else
                    info "Keeping existing Docker installation"
                    return 0
                fi
            fi
        else
            info "Docker already installed (official)"
            return 0
        fi
    fi

    step "  Installing Docker..."
    case "$PKG_MANAGER" in
        apt)
            $SUDO install -m 0755 -d /etc/apt/keyrings
            local repo_url="https://download.docker.com/linux/${OS_ID}"
            curl --disable -fsSL "${repo_url}/gpg" | $SUDO gpg --dearmor -o /etc/apt/keyrings/docker.gpg >> "$LOG_FILE" 2>&1
            $SUDO chmod a+r /etc/apt/keyrings/docker.gpg
            echo "deb [arch=${ARCH} signed-by=/etc/apt/keyrings/docker.gpg] ${repo_url} ${OS_CODENAME} stable" \
                | $SUDO tee /etc/apt/sources.list.d/docker.list > /dev/null
            $SUDO apt-get update -qq >> "$LOG_FILE" 2>&1
            $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \
                docker-ce docker-ce-cli containerd.io docker-compose-plugin >> "$LOG_FILE" 2>&1
            ;;
        dnf)
            local docker_repo="https://download.docker.com/linux/centos/docker-ce.repo"
            [[ "$OS_ID" == "fedora" ]] && docker_repo="https://download.docker.com/linux/fedora/docker-ce.repo"
            $SUDO dnf config-manager --add-repo "$docker_repo" >> "$LOG_FILE" 2>&1
            $SUDO dnf install -y docker-ce docker-ce-cli containerd.io docker-compose-plugin >> "$LOG_FILE" 2>&1
            ;;
        yum)
            $SUDO yum-config-manager --add-repo "https://download.docker.com/linux/centos/docker-ce.repo" >> "$LOG_FILE" 2>&1
            $SUDO yum install -y docker-ce docker-ce-cli containerd.io docker-compose-plugin >> "$LOG_FILE" 2>&1
            ;;
        pacman)
            $SUDO pacman -S --noconfirm docker docker-compose >> "$LOG_FILE" 2>&1
            ;;
        zypper)
            $SUDO zypper -n install docker docker-compose >> "$LOG_FILE" 2>&1 || {
                warn "Trying official Docker repo for openSUSE..."
                $SUDO zypper addrepo "https://download.docker.com/linux/sles/docker-ce.repo" >> "$LOG_FILE" 2>&1
                $SUDO zypper -n install docker-ce docker-ce-cli containerd.io docker-compose-plugin >> "$LOG_FILE" 2>&1
            }
            ;;
        brew)
            if [[ ! -d "/Applications/Docker.app" ]]; then
                brew install --cask docker >> "$LOG_FILE" 2>&1
                echo ""
                echo "  Docker Desktop installed. Please open Docker Desktop"
                echo "  from your Applications folder and wait for it to start."
                echo ""
                if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
                    read -r -p "  Press Enter when Docker Desktop is running..."
                fi
            fi
            local attempts=0
            while ! docker info &>/dev/null; do
                attempts=$((attempts + 1))
                if [[ $attempts -ge 30 ]]; then
                    die "Docker Desktop not responding. Open it and re-run."
                fi
                sleep 2
            done
            info "Docker Desktop running"
            # Docker Desktop host networking (macOS only, DD 4.34+)
            detect_docker_desktop_version
            if check_docker_desktop_host_net_prerequisites; then
                enable_docker_desktop_host_networking
            fi
            return 0
            ;;
        *)
            die "Cannot install Docker automatically on ${OS_ID}. Install manually: https://docs.docker.com/engine/install/"
            ;;
    esac

    if [[ "$IS_MACOS" != "true" ]]; then
        $SUDO systemctl enable docker >> "$LOG_FILE" 2>&1
        $SUDO systemctl start docker >> "$LOG_FILE" 2>&1
    fi

    if ! $SUDO docker info &>/dev/null; then
        die "Docker installed but not responding. Check: systemctl status docker"
    fi
    info "Docker installed and running"
}

prepare_docker_ipv6() {
    step "  Configuring Docker IPv6..."

    if [[ "$IS_MACOS" == "true" ]]; then
        if $SUDO docker info --format '{{.IPv6Forwarding}}' 2>/dev/null | grep -qi "true"; then
            info "Docker IPv6 already enabled"
            return 0
        fi
        echo ""
        echo "  Docker Desktop requires manual IPv6 configuration:"
        echo "  Settings → Docker Engine → add to JSON:"
        echo '    "ipv6": true,'
        echo '    "fixed-cidr-v6": "fd00:d0c:1::/64"'
        echo ""
        if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
            read -r -p "  Press Enter after enabling IPv6 in Docker Desktop..."
        fi
        return 0
    fi

    local daemon_json="/etc/docker/daemon.json"
    local existing="{}"
    if [[ -f "$daemon_json" ]]; then
        existing=$($SUDO cat "$daemon_json")
    fi

    if echo "$existing" | jq -e '.ipv6 == true' &>/dev/null; then
        info "Docker IPv6 already configured"
        return 0
    fi

    if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        if ! ask_yesno "Docker IPv6" "Enabling IPv6 requires restarting Docker (stops running containers). Proceed?" "yes"; then
            die "IPv6 is required. This project is IPv6-first. Please enable IPv6 and re-run."
        fi
    fi

    local merged
    merged=$(echo "$existing" | jq '. + {"ipv6":true,"fixed-cidr-v6":"fd00:d0c:1::/64","ip6tables":true}')
    local tmpfile
    tmpfile=$(mktemp); CLEANUP_FILES+=("$tmpfile")
    echo "$merged" > "$tmpfile"
    $SUDO mv "$tmpfile" "$daemon_json"
    $SUDO chmod 0644 "$daemon_json"

    $SUDO systemctl restart docker >> "$LOG_FILE" 2>&1
    local attempts=0
    while ! $SUDO docker info &>/dev/null; do
        attempts=$((attempts + 1))
        if [[ $attempts -ge 15 ]]; then
            die "Docker did not restart after IPv6 configuration. Check: journalctl -u docker"
        fi
        sleep 2
    done
    info "Docker IPv6 configured and restarted"
}

prepare_system_user() {
    if [[ "$IS_MACOS" == "true" ]]; then
        return 0
    fi

    if id "$SERVICE_USER" &>/dev/null; then
        info "System user '${SERVICE_USER}' already exists"
    else
        step "  Creating system user '${SERVICE_USER}'..."
        $SUDO useradd --system --no-create-home --shell /usr/sbin/nologin "$SERVICE_USER"
        info "Created system user '${SERVICE_USER}'"
    fi

    if ! groups "$SERVICE_USER" 2>/dev/null | grep -q docker; then
        $SUDO usermod -aG docker "$SERVICE_USER"
        info "Added '${SERVICE_USER}' to docker group"
    fi
}

# Stable marker embedded in every installer-managed /etc/nftables.conf. Its
# presence proves the config is the clean template (so convergence is a no-op);
# its absence — or any sign of the old manual "0a.5" hackery — triggers a
# converging rewrite on the next install/upgrade.
readonly NFT_TEMPLATE_MARKER="# Managed by llm-api-proxy installer — do not edit by hand."

# firewall_service_ports — print the host service ports the firewall must open.
#
# One `port/proto` token per line:
#   - 22/tcp     SSH (always — prevents lockout)
#   - 443/tcp    HTTPS (TLS on) OR 80/tcp (TLS off)
#   - 8443/tcp   forward proxy CONNECT entrypoint
#   - 5353/udp   mDNS (only when enabled)
#
# All backend ports (7080, 7443, 5432, 8500, …) bind to [::1] and are NEVER
# opened. This is the single source of truth for both the ufw/firewalld paths
# and the hardened nftables template, so they cannot drift.
firewall_service_ports() {
    echo "22/tcp"
    if [[ "$OPT_TLS" == "true" ]]; then
        echo "443/tcp"
    else
        echo "80/tcp"
    fi
    echo "8443/tcp"
    [[ "$OPT_MDNS" == "true" ]] && echo "5353/udp"
    return 0
}

# generate_hardened_nftables_config — print a clean, reboot-safe, docker-aware
# nftables ruleset to stdout.
#
# This is the authoritative, install/template-managed firewall (issues #1336,
# #1546). The installer owns THREE tables and nothing else:
#   - `inet filter` — host INPUT/FORWARD/OUTPUT policy. It lets bridge traffic
#     through via the rename-proof `br-*` wildcard.
#   - `ip llap-nat`  — SNAT (masquerade) for the Docker bridge IPv4 subnets so
#     containers can reach the internet.
#   - `ip6 llap-nat` — NAT66 (masquerade) for the Docker bridge IPv6 ULA so the
#     IPv6-first stack has egress too.
#
# The installer NAT tables are deliberately NOT named `ip nat`/`ip6 nat`: those
# are Docker's runtime tables. We never dump Docker's `ip/ip6 nat|filter|raw`
# tables (whose `xt target "DNAT"`/`"MASQUERADE"` compat expressions make
# `nft -f` fail atomically at boot and leave INPUT wide open). Docker manages
# its own NAT/filter tables at runtime; our dedicated `llap-nat` tables guarantee
# bridge egress deterministically regardless of Docker's lazy NAT-creation
# timing (issue #1546 — a host-side `flush ruleset` wiped Docker's `ip nat`,
# which does not return until `systemctl restart docker`, black-holing backups).
#
# Pure function: writes only to stdout (no logging / no $SUDO), so it is
# trivially testable and safe to capture into a temp file for `nft -c -f`.
#
# Mode (first arg):
#   persist (default) — the on-disk /etc/nftables.conf for boot. Begins with
#                       `flush ruleset`, which is safe at boot because dockerd
#                       starts AFTER nftables.service, so there are no Docker
#                       tables to wipe yet. Emits the NAT tables as plain
#                       definitions (the leading flush already cleared state).
#   live              — for an `nft -f` reload while the system is RUNNING (and
#                       Docker / fail2ban tables already exist). Replaces ONLY
#                       the installer-owned `inet filter`, `ip llap-nat` and
#                       `ip6 llap-nat` tables via the create-empty / delete /
#                       recreate idiom, so Docker's runtime ip/ip6 nat|filter|raw
#                       tables and fail2ban's chains are left untouched. NEVER
#                       `flush ruleset`.
generate_hardened_nftables_config() {
    local mode="${1:-persist}"
    local ssh_port=22

    if [[ "$mode" == "live" ]]; then
        cat <<EOF
#!/usr/sbin/nft -f
${NFT_TEMPLATE_MARKER}
#
# Live reload — replaces ONLY the installer-owned \`inet filter\`,
# \`ip llap-nat\` and \`ip6 llap-nat\` tables so Docker's runtime
# ip/ip6 nat|filter|raw tables and fail2ban's chains survive untouched.

table inet filter {}
delete table inet filter

table inet filter {
EOF
    else
        cat <<EOF
#!/usr/sbin/nft -f
${NFT_TEMPLATE_MARKER}
#
# Hardened, reboot-safe, docker-aware firewall for the public box.
# Installer-owned tables: \`inet filter\` (host policy) plus \`ip llap-nat\` and
# \`ip6 llap-nat\` (Docker bridge SNAT/NAT66). Docker manages its own
# ip/ip6 nat|filter tables at runtime; dumping those here breaks the atomic
# boot-time \`nft -f\`, so we never emit them.

flush ruleset

table inet filter {
EOF
    fi
    cat <<EOF
	chain input {
		type filter hook input priority filter; policy drop;

		# Loopback is always trusted.
		iif "lo" accept

		# Established/return traffic.
		ct state established,related accept

		# Drop obviously invalid packets.
		ct state invalid drop

		# IPv6 neighbour discovery / ICMPv6 are required for IPv6 to work.
		meta l4proto ipv6-icmp accept
		# Allow a conservative set of ICMPv4 (echo + path-MTU).
		ip protocol icmp icmp type { echo-request, destination-unreachable, time-exceeded, parameter-problem } accept

		# SSH — always open to prevent lockout.
		tcp dport ${ssh_port} accept

EOF

    # Service ports (skip ssh: already emitted above so it can never be omitted).
    local port proto num
    while IFS= read -r port; do
        [[ -z "$port" ]] && continue
        [[ "$port" == "${ssh_port}/tcp" ]] && continue
        proto="${port##*/}"
        num="${port%%/*}"
        printf '\t\t%s dport %s accept\n' "$proto" "$num"
    done < <(firewall_service_ports)

    cat <<EOF
	}

	chain forward {
		type filter hook forward priority filter; policy drop;

		# Return traffic for forwarded connections.
		ct state established,related accept
		ct state invalid drop

		# Docker default bridge.
		iifname "docker0" accept
		oifname "docker0" accept

		# All Docker user-defined bridges. The wildcard is rename-proof:
		# \`docker compose\` regenerates br-<hash> names on network recreate,
		# so a hardcoded br-<hash> goes stale and silently blocks egress
		# (issue #1336). Docker still enforces its own per-container rules
		# in its runtime ip/ip6 filter tables.
		iifname "br-*" accept
		oifname "br-*" accept
	}

	chain output {
		type filter hook output priority filter; policy accept;
	}
}
EOF

    # Installer-owned NAT tables for Docker bridge egress (issue #1546). They are
    # named \`llap-nat\` (NOT \`ip nat\`/\`ip6 nat\`) so they never collide with —
    # or get mistaken for — Docker's runtime tables, and so the existing
    # substring guards (\`table ip nat\`, \`xt target\`) stay valid. Masquerade is
    # matched by SOURCE CIDR + non-loopback egress, never by a \`br-<hash>\` name
    # (Docker auto-assigns and renames bridge subnets — the #1336 stale-name
    # hazard). 172.16.0.0/12 + 10.0.0.0/8 cover Docker's default IPv4 pools;
    # fd00::/8 covers the pinned ULA + the daemon fixed-cidr-v6.
    if [[ "$mode" == "live" ]]; then
        # Live reload: atomically replace each named table via the
        # create-empty / delete / recreate idiom — no \`flush ruleset\`, so
        # Docker's own ip/ip6 nat tables and fail2ban chains are untouched.
        # Re-running cannot accumulate duplicate masquerade rules.
        cat <<EOF

table ip llap-nat {}
delete table ip llap-nat
table ip llap-nat {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		ip saddr 172.16.0.0/12 oifname != "lo" masquerade
		ip saddr 10.0.0.0/8 oifname != "lo" masquerade
	}
}

table ip6 llap-nat {}
delete table ip6 llap-nat
table ip6 llap-nat {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		ip6 saddr fd00::/8 oifname != "lo" masquerade
	}
}
EOF
    else
        # Persist/boot form: the leading \`flush ruleset\` already cleared prior
        # state, so just define the tables.
        cat <<EOF

table ip llap-nat {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		# SNAT Docker bridge egress so containers reach the internet. Match by
		# RFC1918 source + non-loopback egress (rename/renumber-proof; the IPv4
		# bridge subnet is Docker-auto-assigned, never hardcode br-<hash>).
		ip saddr 172.16.0.0/12 oifname != "lo" masquerade
		ip saddr 10.0.0.0/8 oifname != "lo" masquerade
	}
}

table ip6 llap-nat {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		# NAT66 for the pinned ULA bridge subnet (fc00::/7 is non-routable);
		# REQUIRED for IPv6 egress from the bridge.
		ip6 saddr fd00::/8 oifname != "lo" masquerade
	}
}
EOF
    fi
    return 0
}

# nftables_config_needs_convergence <path> — decide whether an existing
# /etc/nftables.conf must be rewritten to the clean template.
#
# Returns 0 (needs convergence) when the file:
#   - is missing or empty, OR
#   - is a full-ruleset DUMP (contains Docker's `xt target` compat lines), OR
#   - contains a hardcoded br-<hash> forward whitelist (12 hex chars), OR
#   - is not already the installer template (missing the template marker), OR
#   - is a pre-#1546 template that lacks the `ip llap-nat` bridge SNAT table
#     (so upgrading an already-marked-but-NAT-less box rewrites the boot file).
# Returns 1 when the file is already the clean template (no-op).
nftables_config_needs_convergence() {
    local path="$1"

    # Missing/empty → write the template.
    [[ -s "$path" ]] || return 0

    # Dumped Docker runtime tables — the boot-breaking state.
    grep -q "xt target" "$path" && return 0

    # Hardcoded Docker bridge name (br- followed by 12 hex chars) — the stale
    # whitelist that breaks bridge egress on network recreate.
    grep -Eq 'br-[0-9a-f]{12}' "$path" && return 0

    # Anything that is not our marked template gets replaced.
    grep -qF "$NFT_TEMPLATE_MARKER" "$path" || return 0

    # Pre-#1546 marked template without the bridge SNAT table — rewrite so the
    # boot config gains `ip llap-nat`/`ip6 llap-nat` and survives a reboot.
    grep -q 'table ip llap-nat' "$path" || return 0

    return 1
}

# nft_check_syntax <file> — validate an nftables config's SYNTAX.
#
# `nft -c -f` is not a pure offline parser: it initialises a netlink cache from
# the kernel, so it returns "Operation not permitted" for unprivileged callers
# (CI runners, containers) even when the config is syntactically perfect. To get
# a reliable syntax check that works unprivileged, run the check inside a fresh
# user+network namespace (`unshare -rn`), where the caller owns an empty ruleset.
#
# Returns:
#   0  — config parsed cleanly, OR no validator was available (best-effort: the
#        config is our own tested template, never user input, so we never block
#        the firewall on a missing/locked-down validator).
#   1  — a validator that actually ran reported a genuine parse error.
nft_check_syntax() {
    local file="$1"
    command -v nft &>/dev/null || return 0

    # Preferred: isolated namespace check — works without root/CAP_NET_ADMIN.
    if command -v unshare &>/dev/null; then
        local out
        if out=$(unshare -rn nft -c -f "$file" 2>&1); then
            return 0
        fi
        # The namespace ran but nft rejected it. Treat netlink/permission
        # failures as "could not validate" (pass); anything else is a real
        # syntax error.
        if grep -qiE 'operation not permitted|cache initialization failed|permission denied' <<<"$out"; then
            : # environment limitation, not a syntax problem
        else
            printf '%s\n' "$out" >> "$LOG_FILE" 2>&1 || true
            return 1
        fi
    fi

    # Fallback: direct check (succeeds when running as root with CAP_NET_ADMIN).
    local out2
    if out2=$($SUDO nft -c -f "$file" 2>&1); then
        return 0
    fi
    if grep -qiE 'operation not permitted|cache initialization failed|permission denied' <<<"$out2"; then
        return 0  # cannot validate here — best-effort pass
    fi
    printf '%s\n' "$out2" >> "$LOG_FILE" 2>&1 || true
    return 1
}

# install_hardened_nftables — write, validate, persist and load the hardened
# template config, converging any pre-existing manual hardening.
#
# Idempotent: re-running leaves a correct config. Reboot-safe: the config's
# SYNTAX is validated (see nft_check_syntax) before it is installed and
# `nftables.service` is enabled so it reloads cleanly at boot. Returns non-zero
# only on a failure the caller should surface (a genuine parse error in our own
# template).
install_hardened_nftables() {
    # NFT_CONFIG_PATH overrides the persisted config location (tests only); it
    # defaults to the real /etc/nftables.conf.
    local target="${NFT_CONFIG_PATH:-/etc/nftables.conf}"
    local persistfile livefile staged

    persistfile=$(mktemp "${BATS_TMPDIR:-/tmp}/nft-llap-persist-XXXXXX.conf")
    livefile=$(mktemp "${BATS_TMPDIR:-/tmp}/nft-llap-live-XXXXXX.conf")
    generate_hardened_nftables_config persist > "$persistfile"
    generate_hardened_nftables_config live    > "$livefile"

    # Validate our own output before touching anything. A genuine parse error in
    # either form is a bug we must not ship to disk or load.
    if ! nft_check_syntax "$persistfile" || ! nft_check_syntax "$livefile"; then
        rm -f "$persistfile" "$livefile"
        warn "nftables: generated hardened config failed syntax validation — leaving firewall unchanged"
        return 1
    fi

    # Persist the boot config (flush ruleset form). Converge only when needed
    # (keeps upgrades quiet and idempotent), backing up any prior config.
    if nftables_config_needs_convergence "$target"; then
        if [[ -f "$target" ]]; then
            staged="${target}.llap-bak-$(date -u +%Y%m%d%H%M%S)"
            $SUDO cp -f "$target" "$staged" >> "$LOG_FILE" 2>&1 || true
            info "nftables: backed up prior config to ${staged}"
        fi
        $SUDO install -m 0644 "$persistfile" "$target" >> "$LOG_FILE" 2>&1
        info "nftables: installed hardened ${target} (inet filter + ip/ip6 llap-nat bridge SNAT, br-* wildcard)"
    else
        # Already the template — refresh in place so port/TLS changes apply.
        $SUDO install -m 0644 "$persistfile" "$target" >> "$LOG_FILE" 2>&1
        info "nftables: hardened config already managed — refreshed ${target}"
    fi

    # Apply now using the LIVE (non-flushing) form so Docker's runtime tables
    # and fail2ban's chains are not wiped if this runs while the system is up.
    if command -v nft &>/dev/null; then
        if $SUDO nft -f "$livefile" >> "$LOG_FILE" 2>&1; then
            info "nftables: hardened inet filter + ip/ip6 llap-nat bridge SNAT loaded (Docker/fail2ban tables preserved)"
            # Re-arm fail2ban's nft hooks in case its chains predated this load.
            if command -v systemctl &>/dev/null \
                && $SUDO systemctl is-active fail2ban &>/dev/null; then
                $SUDO systemctl reload-or-restart fail2ban >> "$LOG_FILE" 2>&1 || true
            fi
        else
            warn "nftables: failed to load hardened table — review with: nft -c -f ${target}"
        fi
    else
        warn "nftables: nft binary unavailable — hardened ${target} persisted for boot but NOT applied to the running system; reboot or install nftables to activate"
    fi

    rm -f "$persistfile" "$livefile"

    if command -v systemctl &>/dev/null; then
        $SUDO systemctl enable nftables >> "$LOG_FILE" 2>&1 || true
    fi
    return 0
}

# configure_fail2ban — install fail2ban with an nftables backend so repeated
# SSH/auth abuse is banned at the firewall layer. Best-effort.
configure_fail2ban() {
    if ! command -v fail2ban-client &>/dev/null; then
        case "$PKG_MANAGER" in
            apt)    $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq fail2ban >> "$LOG_FILE" 2>&1 || true ;;
            dnf|yum) $SUDO "$PKG_MANAGER" install -y -q fail2ban >> "$LOG_FILE" 2>&1 || true ;;
            *)      : ;;
        esac
    fi
    if command -v fail2ban-client &>/dev/null && command -v systemctl &>/dev/null; then
        # Prefer the nftables banaction so bans live in the same firewall stack.
        if [[ -d /etc/fail2ban/jail.d ]]; then
            printf '[DEFAULT]\nbanaction = nftables-multiport\nbanaction_allports = nftables-allports\n\n[sshd]\nenabled = true\n' \
                | $SUDO tee /etc/fail2ban/jail.d/llm-api-proxy.conf > /dev/null 2>&1 || true
        fi
        $SUDO systemctl enable --now fail2ban >> "$LOG_FILE" 2>&1 || true
        info "fail2ban: enabled (sshd jail, nftables backend)"
    else
        warn "fail2ban not available — skipping intrusion protection"
    fi
}

# enable_ip_forwarding — persist + apply IPv4/IPv6 forwarding (issue #1546).
#
# Host-side SNAT/NAT66 for the Docker bridge (the `ip/ip6 llap-nat` tables) only
# routes packets if the kernel forwards them. Docker usually enables
# net.ipv4.ip_forward, but the host must own forwarding deterministically for
# both families — otherwise masquerade exists but bridge egress still
# black-holes. We write an idempotent sysctl drop-in (reboot-safe) and apply it
# live (best-effort).
#
# SYSCTL_FORWARD_PATH overrides the drop-in location (tests only); it defaults
# to the real /etc/sysctl.d/99-llm-api-proxy-forward.conf.
enable_ip_forwarding() {
    local conf="${SYSCTL_FORWARD_PATH:-/etc/sysctl.d/99-llm-api-proxy-forward.conf}"
    local tmp
    tmp=$(mktemp "${BATS_TMPDIR:-/tmp}/llap-forward-XXXXXX.conf")
    cat > "$tmp" <<EOF
${NFT_TEMPLATE_MARKER}
# IP forwarding for Docker bridge SNAT/NAT66 (issue #1546).
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
EOF
    # Persist the drop-in (idempotent overwrite — re-running yields byte-identical
    # content). The durable write is the reboot-safe half of the fix, so a failure
    # here must NOT be swallowed: warn and bail (without aborting the installer —
    # the caller does not gate on our return). Ensure the target dir exists first.
    $SUDO mkdir -p "$(dirname "$conf")" >> "$LOG_FILE" 2>&1 || true
    if ! $SUDO install -m 0644 "$tmp" "$conf" >> "$LOG_FILE" 2>&1; then
        rm -f "$tmp"
        warn "sysctl: failed to write IP-forwarding drop-in ${conf} — bridge egress may break after reboot"
        return 1
    fi
    rm -f "$tmp"

    # Apply live (best-effort): prefer reloading the drop-in we just wrote so the
    # values match the persisted file; fall back to setting them directly. Live
    # application failing is non-fatal (Docker also sets ip_forward at runtime).
    if command -v sysctl &>/dev/null; then
        if ! $SUDO sysctl --system >> "$LOG_FILE" 2>&1; then
            $SUDO sysctl -w net.ipv4.ip_forward=1 >> "$LOG_FILE" 2>&1 || true
            $SUDO sysctl -w net.ipv6.conf.all.forwarding=1 >> "$LOG_FILE" 2>&1 || true
        fi
    fi
    info "sysctl: IPv4/IPv6 forwarding enabled for Docker bridge egress (${conf})"
    return 0
}

# prepare_firewall — configure the host firewall (issues #1336, #1546).
#
# Default-on hardening for public/TLS boxes: when nftables is the firewall
# manager (or can be installed), the installer enables IP forwarding, then
# writes the clean, reboot-safe, docker-aware template (inet filter + the
# `ip/ip6 llap-nat` bridge SNAT/NAT66 tables) and integrates fail2ban. On hosts
# managed by ufw or firewalld we defer to that manager and only open the
# required service ports (we do not fight an admin-chosen firewall). The
# `--skip-firewall` flag remains the full escape hatch.
prepare_firewall() {
    if [[ "$OPT_SKIP_FIREWALL" == "true" ]]; then
        info "Firewall configuration skipped (--skip-firewall)"
        return 0
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        info "Firewall configuration skipped (macOS)"
        return 0
    fi

    local -a ports=()
    local port
    while IFS= read -r port; do
        [[ -n "$port" ]] && ports+=("$port")
    done < <(firewall_service_ports)

    step "  Configuring firewall..."
    echo "  Opening ports: ${ports[*]}"

    if command -v ufw &>/dev/null && $SUDO ufw status | grep -q "active"; then
        # An admin already runs ufw — respect it, just open our ports.
        for port in "${ports[@]}"; do
            $SUDO ufw allow "$port" >> "$LOG_FILE" 2>&1
            info "ufw: opened ${port}"
        done
    elif command -v firewall-cmd &>/dev/null && $SUDO systemctl is-active firewalld &>/dev/null; then
        # An admin already runs firewalld — respect it, just open our ports.
        for port in "${ports[@]}"; do
            $SUDO firewall-cmd --permanent --add-port="$port" >> "$LOG_FILE" 2>&1
            info "firewalld: opened ${port}"
        done
        $SUDO firewall-cmd --reload >> "$LOG_FILE" 2>&1
    else
        # Default path: install/converge the hardened nftables template.
        if ! command -v nft &>/dev/null; then
            case "$PKG_MANAGER" in
                apt)    $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq nftables >> "$LOG_FILE" 2>&1 || true ;;
                dnf|yum) $SUDO "$PKG_MANAGER" install -y -q nftables >> "$LOG_FILE" 2>&1 || true ;;
                pacman) $SUDO pacman -S --noconfirm --needed nftables >> "$LOG_FILE" 2>&1 || true ;;
                zypper) $SUDO zypper -n install nftables >> "$LOG_FILE" 2>&1 || true ;;
            esac
        fi
        if command -v nft &>/dev/null || command -v systemctl &>/dev/null; then
            # Forwarding must be on for the host-side bridge SNAT/NAT66 tables in
            # install_hardened_nftables to actually route bridge egress (#1546).
            enable_ip_forwarding
            install_hardened_nftables
            configure_fail2ban
        else
            warn "No recognized firewall found — skipping. Manually open: ${ports[*]}"
        fi
    fi
}

# configure_nftables_docker_forward — re-converge the hardened firewall after
# the Docker stack is up (issue #1336).
#
# Docker's daemon rewrites the live nftables ruleset when it starts bridges and
# can clobber /etc/nftables.conf into a full-ruleset dump. Because the template
# uses the rename-proof `br-*` wildcard, no per-bridge discovery is needed: we
# simply re-install/re-converge the clean template so the persisted config is
# correct and reboot-safe regardless of what Docker did at runtime.
#
# Must be called AFTER `deploy_start_remaining_services`.
configure_nftables_docker_forward() {
    if [[ "$OPT_SKIP_FIREWALL" == "true" ]]; then
        return 0
    fi
    if [[ "$IS_MACOS" == "true" ]]; then
        return 0
    fi

    # Only act when we are the nftables manager (not when ufw/firewalld own it).
    if { command -v ufw &>/dev/null && $SUDO ufw status 2>/dev/null | grep -q "active"; } \
        || { command -v firewall-cmd &>/dev/null && $SUDO systemctl is-active firewalld &>/dev/null; }; then
        return 0
    fi

    if command -v nft &>/dev/null || command -v systemctl &>/dev/null; then
        install_hardened_nftables
    fi
}

prepare_security_updates() {
    if [[ "$OPT_SKIP_SECURITY_UPDATES" == "true" ]]; then
        info "Automatic security updates skipped (--skip-security-updates)"
        return 0
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        return 0
    fi

    step "  Configuring automatic security updates..."
    case "$PKG_MANAGER" in
        apt)
            $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq unattended-upgrades >> "$LOG_FILE" 2>&1
            $SUDO env DEBIAN_FRONTEND=noninteractive dpkg-reconfigure -plow unattended-upgrades >> "$LOG_FILE" 2>&1 || true
            info "unattended-upgrades configured"
            ;;
        dnf)
            $SUDO dnf install -y -q dnf-automatic >> "$LOG_FILE" 2>&1
            $SUDO sed -i 's/^apply_updates = no/apply_updates = yes/' /etc/dnf/automatic.conf 2>/dev/null || true
            $SUDO systemctl enable --now dnf-automatic.timer >> "$LOG_FILE" 2>&1
            info "dnf-automatic configured"
            ;;
        yum)
            $SUDO yum install -y -q yum-cron >> "$LOG_FILE" 2>&1
            $SUDO systemctl enable --now yum-cron >> "$LOG_FILE" 2>&1
            info "yum-cron configured"
            ;;
        *)
            warn "Auto security updates not configured for ${PKG_MANAGER}"
            ;;
    esac
}

run_prepare() {
    step "[3/5] Preparing system..."
    local step_num=0
    local total_steps=7

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] System package upgrade"
    prepare_system_upgrade

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] Prerequisites"
    prepare_prerequisites

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] Docker"
    prepare_docker

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] Docker IPv6"
    prepare_docker_ipv6

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] System user"
    prepare_system_user

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] Firewall"
    prepare_firewall

    step_num=$((step_num + 1))
    echo "  [${step_num}/${total_steps}] Security updates"
    prepare_security_updates

    info "System preparation complete"
}

# ── Phase 4: Configure (settings collection) ────────────────────────────────

configure_install_mode() {
    if [[ -z "${EXISTING_INSTALL:-}" ]]; then
        if [[ -z "$COMMAND" ]]; then
            COMMAND="install"
        fi
        return 0
    fi

    if [[ -n "$COMMAND" ]]; then
        return 0
    fi

    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        COMMAND="upgrade"
        return 0
    fi

    local choice
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        choice=$("$DIALOG_CMD" --title "Existing Installation" --menu \
            "An existing installation was found. What would you like to do?" \
            12 60 3 \
            "upgrade" "Upgrade to new version" \
            "reconfigure" "Change settings" \
            "reinstall" "Full reinstall (warning: may lose data)" \
            3>&1 1>&2 2>&3) || die "Cancelled."
    else
        echo ""
        echo "Existing installation detected. Choose:"
        echo "  1) Upgrade to new version"
        echo "  2) Reconfigure settings"
        echo "  3) Full reinstall"
        local answer
        read -r -p "Choice [1]: " answer
        case "${answer:-1}" in
            1) choice="upgrade" ;;
            2) choice="reconfigure" ;;
            3) choice="reinstall" ;;
            *) choice="upgrade" ;;
        esac
    fi

    if [[ "$choice" == "reinstall" ]]; then
        if ! ask_yesno "Full Reinstall" "This will reinstall from scratch. Existing data in Docker volumes is preserved but config will be regenerated. Continue?" "no"; then
            die "Aborted."
        fi
        COMMAND="install"
    else
        COMMAND="$choice"
    fi
}

is_stable_semver() {
    [[ "$1" =~ ^[0-9]+[.][0-9]+[.][0-9]+$ ]]
}

stable_semver_gt() {
    local left="$1" right="$2"
    is_stable_semver "$left" || return 1
    is_stable_semver "$right" || return 1

    local left_major left_minor left_patch
    local right_major right_minor right_patch
    IFS=. read -r left_major left_minor left_patch <<< "$left"
    IFS=. read -r right_major right_minor right_patch <<< "$right"

    if (( 10#$left_major > 10#$right_major )); then return 0; fi
    if (( 10#$left_major < 10#$right_major )); then return 1; fi
    if (( 10#$left_minor > 10#$right_minor )); then return 0; fi
    if (( 10#$left_minor < 10#$right_minor )); then return 1; fi
    (( 10#$left_patch > 10#$right_patch ))
}

existing_install_version() {
    [[ -n "${EXISTING_INSTALL:-}" ]] || return 1
    $SUDO jq -er '.version | strings | select(test("^[0-9]+[.][0-9]+[.][0-9]+$"))' \
        "$EXISTING_INSTALL" 2>/dev/null
}

database_backup_id_is_safe() {
    [[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$ ]]
}

configure_database_recovery_contract() {
    local installed_version=""
    installed_version=$(existing_install_version 2>/dev/null || true)

    if [[ -n "$OPT_ROLLBACK_BACKUP_ID" ]]; then
        [[ "$COMMAND" == "upgrade" ]] \
            || die "--rollback-backup is valid only with the upgrade command."
        database_backup_id_is_safe "$OPT_ROLLBACK_BACKUP_ID" \
            || die "--rollback-backup must be an installer-issued backup ID, not a path."
        [[ -n "$installed_version" ]] \
            || die "--rollback-backup requires an existing stable-version installation."
        is_stable_semver "$OPT_VERSION" \
            || die "--rollback-backup requires an older stable version target."
        stable_semver_gt "$installed_version" "$OPT_VERSION" \
            || die "--rollback-backup is accepted only when targeting an older stable version."
        return 0
    fi

    if [[ "$COMMAND" == "upgrade" ]] \
        && stable_semver_gt "$installed_version" "$OPT_VERSION"; then
        die "Downgrading from ${installed_version} to ${OPT_VERSION} requires --rollback-backup=ID from the installer-created pre-upgrade backup."
    fi
}

configure_version() {
    if [[ -n "$OPT_VERSION" ]]; then
        info "Version: ${OPT_VERSION} (from CLI/env)"
        return 0
    fi

    local latest=""

    if [[ "$OPT_DEBUG" == "true" ]]; then
        # Debug images are not published to the public releases repo.
        # Fall back to GHCR tag list which requires auth (may return 401 without a PAT).
        local scope="repository:llm-api-proxy/server-debug:pull"
        local tags_json
        if tags_json=$(ghcr_api_request "https://ghcr.io/v2/llm-api-proxy/server-debug/tags/list" "$scope"); then
            latest=$(echo "$tags_json" | jq -r '.tags[]' 2>/dev/null \
                | grep -E '^[0-9]+\.[0-9]+\.[0-9]+-debug$' | sort -V | tail -1)
            latest="${latest%-debug}"
        fi
    else
        # Query the public GitHub Releases API — no auth required.
        local releases_url="https://api.github.com/repos/LLM-API-Proxy/llap/releases?per_page=10"
        local releases_json
        if releases_json=$(curl --disable -fsSL --max-time 10 \
                -H "Accept: application/vnd.github+json" \
                "$releases_url" 2>/dev/null); then
            latest=$(echo "$releases_json" \
                | jq -r '[.[] | select(.prerelease==false and .draft==false) | .tag_name] | first' \
                2>/dev/null | sed 's/^v//')
            [[ "$latest" == "null" ]] && latest=""
        fi
    fi

    if [[ "$OPT_DEBUG" != "true" ]] && is_stable_semver "$INSTALLER_VERSION"; then
        if [[ -z "$latest" ]]; then
            latest="$INSTALLER_VERSION"
        elif stable_semver_gt "$INSTALLER_VERSION" "$latest"; then
            warn "Public release API reports ${latest}, older than installer ${INSTALLER_VERSION}; using installer version."
            latest="$INSTALLER_VERSION"
        fi
    fi

    if [[ -n "$latest" ]] && [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        OPT_VERSION=$(ask_input "Version" "Enter version to install" "$latest")
    elif [[ -n "$latest" ]]; then
        OPT_VERSION="$latest"
    else
        if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
            OPT_VERSION="edge"
        else
            OPT_VERSION=$(ask_input "Version" "Could not query releases. Enter version" "edge")
        fi
    fi

    info "Version: ${OPT_VERSION}"
}

configure_features() {
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        return 0
    fi

    local mdns_state="on"
    [[ "$IS_MACOS" == "true" ]] && mdns_state="off"

    local selected
    selected=$(ask_checklist "Components" "Select components to install:" \
        "waf" "WAF (ModSecurity OWASP CRS)" "$([ "$OPT_WAF" = "true" ] && echo on || echo off)" \
        "tls" "TLS (automated HTTPS via Traefik)" "$([ "$OPT_TLS" = "true" ] && echo on || echo off)" \
        "backup" "Backup (Restic to S3)" "$([ "$OPT_BACKUP" = "true" ] && echo on || echo off)" \
        "monitoring" "Monitoring (Prometheus + Grafana)" "$([ "$OPT_MONITORING" = "true" ] && echo on || echo off)" \
        "mdns" "mDNS service discovery" "$mdns_state") || return 0

    OPT_WAF="false"; OPT_TLS="false"; OPT_BACKUP="false"
    OPT_MONITORING="false"; OPT_MDNS="false"
    local item
    for item in $selected; do
        item=$(echo "$item" | tr -d '"')
        case "$item" in
            waf) OPT_WAF="true" ;;
            tls) OPT_TLS="true" ;;
            backup) OPT_BACKUP="true" ;;
            monitoring) OPT_MONITORING="true" ;;
            mdns) OPT_MDNS="true" ;;
        esac
    done

    [[ "$IS_MACOS" == "true" ]] && OPT_MDNS="false"
}

configure_core() {
    step "  Core settings..."

    if [[ -z "$OPT_POSTGRES_PASSWORD" ]]; then
        # MUST be URL-safe: embedded un-encoded into DATABASE_URL (#1327).
        OPT_POSTGRES_PASSWORD=$(resolve_setting "OPT_POSTGRES_PASSWORD" "POSTGRES_PASSWORD" \
            "PostgreSQL password" "$(gen_urlsafe_secret 24)")
    fi

    if [[ -z "$OPT_KEK_HEX" ]]; then
        local existing_kek=""
        if $SUDO test -f "${INSTALL_DIR}/docker/.env" 2>/dev/null; then
            existing_kek=$($SUDO grep "^PROXY_KEK_VALUE=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true)
        fi
        if [[ -n "$existing_kek" ]]; then
            OPT_KEK_HEX="$existing_kek"
        else
            OPT_KEK_HEX=$(openssl rand -hex 32 2>/dev/null || head -c 32 /dev/urandom | xxd -p | tr -d '\n')
        fi
    fi

    if [[ "${COMMAND:-}" == "reconfigure" ]] && $SUDO test -f "${INSTALL_DIR}/docker/.env" 2>/dev/null; then
        local old_kek
        old_kek=$($SUDO grep "^PROXY_KEK_VALUE=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true)
        if [[ -n "$old_kek" ]] && [[ "$old_kek" != "$OPT_KEK_HEX" ]]; then
            warn "KEK is changing! All encrypted provider credentials will become unreadable."
            if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
                if ! ask_yesno "KEK Change" "Changing the KEK invalidates all encrypted credentials. Continue?" "no"; then
                    OPT_KEK_HEX="$old_kek"
                fi
            fi
        fi
    fi

    # ── Proxy key pepper ───────────────────────────────────────────────────────
    local existing_pepper=""
    if $SUDO test -f "${INSTALL_DIR}/docker/.env" 2>/dev/null; then
        existing_pepper=$($SUDO grep "^PROXY_PROXY_KEY_PEPPER=" "${INSTALL_DIR}/docker/.env" \
            2>/dev/null | cut -d= -f2- | tr -d '"' || true)
    fi

    if [[ -z "$OPT_PROXY_KEY_PEPPER" ]]; then
        if [[ -n "$existing_pepper" ]]; then
            OPT_PROXY_KEY_PEPPER="$existing_pepper"
            log "Preserving existing PROXY_PROXY_KEY_PEPPER"
        else
            OPT_PROXY_KEY_PEPPER=$(openssl rand -hex 32 2>/dev/null || head -c 32 /dev/urandom | xxd -p | tr -d '\n')
            log "Generated new PROXY_PROXY_KEY_PEPPER"
            warn "IMPORTANT: Save your PROXY_PROXY_KEY_PEPPER value securely."
            warn "This value must be IDENTICAL on the destination server when migrating credentials."
            warn "Losing this value will break proxy key validation after a migration."
        fi
    fi

    # Warn if pepper is changing on reconfigure
    if [[ "${COMMAND:-}" == "reconfigure" ]] && \
       [[ -n "$existing_pepper" ]] && \
       [[ "$existing_pepper" != "$OPT_PROXY_KEY_PEPPER" ]]; then
        warn "WARNING: PROXY_PROXY_KEY_PEPPER is changing!"
        warn "All existing proxy key hashes will become INVALID."
        warn "Users will need to regenerate their proxy keys after reconfiguration."
    fi

    # ── JWT secret ─────────────────────────────────────────────────────────────
    # Preserve existing JWT secret on upgrades to avoid invalidating all sessions.
    if [[ -z "$OPT_JWT_SECRET" ]]; then
        local existing_jwt=""
        if $SUDO test -f "${INSTALL_DIR}/docker/.env" 2>/dev/null; then
            existing_jwt=$($SUDO grep "^PROXY_JWT_SECRET=" "${INSTALL_DIR}/docker/.env" \
                2>/dev/null | cut -d= -f2- || true)
        fi
        if [[ -n "$existing_jwt" ]]; then
            OPT_JWT_SECRET="$existing_jwt"
            log "Preserving existing PROXY_JWT_SECRET"
        else
            OPT_JWT_SECRET=$(openssl rand -hex 32 2>/dev/null || head -c 32 /dev/urandom | xxd -p | tr -d '\n')
        fi
    fi

    # Ports carry non-empty defaults, so resolve_setting (which keys off an empty
    # OPT_*) can't be used. Preserve a previously-configured custom port from the
    # existing .env when no explicit override was supplied, so an upgrade keeps
    # the operator's ports instead of resetting them to the defaults (#1306). An
    # explicit CLI flag / env var (tracked via *_SET) always wins.
    if [[ "$OPT_LISTEN_PORT_SET" != "true" ]]; then
        local existing_listen_port
        existing_listen_port=$(existing_env_value "PROXY_LISTEN_PORT")
        [[ -n "$existing_listen_port" ]] && OPT_LISTEN_PORT="$existing_listen_port"
    fi
    if [[ "$OPT_FORWARD_PROXY_PORT_SET" != "true" ]]; then
        local existing_forward_port
        existing_forward_port=$(existing_env_value "PROXY_FORWARD_PROXY__PORT")
        if [[ -z "$existing_forward_port" ]]; then
            # Compatibility for installs created before #1632. The upgrade
            # reconciliation below removes this ignored spelling after carrying
            # its value into the canonical nested key.
            existing_forward_port=$(existing_env_value "PROXY_FORWARD_PROXY_PORT")
        fi
        [[ -n "$existing_forward_port" ]] && OPT_FORWARD_PROXY_PORT="$existing_forward_port"
    fi

    # DB pool overrides (#1416). Only an EXPLICIT operator override is preserved
    # across upgrades: if the existing .env value matches what auto-sizing would
    # compute on this host, leave OPT empty so we keep auto-sizing (and re-tune if
    # the operator changes hardware). If it differs, the operator pinned it — treat
    # it as an override and preserve it verbatim. An explicit flag/env always wins
    # (OPT already non-empty → this block is skipped).
    local _cpus
    _cpus=$(_get_cpu_count)
    if [[ -z "${OPT_CONTROL_POOL_SIZE:-}" ]]; then
        local existing_control
        existing_control=$(existing_env_value "PROXY_DATABASE__CONTROL_POOL_SIZE")
        if [[ -n "$existing_control" ]] && \
           [[ "$existing_control" != "$(_compute_control_pool_size "$_cpus")" ]]; then
            OPT_CONTROL_POOL_SIZE="$existing_control"
        fi
    fi
    if [[ -z "${OPT_DATA_POOL_SIZE:-}" ]]; then
        local existing_data
        existing_data=$(existing_env_value "PROXY_DATABASE__DATA_POOL_SIZE")
        if [[ -n "$existing_data" ]] && \
           [[ "$existing_data" != "$(_compute_data_pool_size "$_cpus")" ]]; then
            OPT_DATA_POOL_SIZE="$existing_data"
        fi
    fi

    if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        OPT_LISTEN_PORT=$(ask_input "Port" "Proxy HTTP service port" "${OPT_LISTEN_PORT}")
        OPT_FORWARD_PROXY_PORT=$(ask_input "Port" "Forward proxy CONNECT port" "${OPT_FORWARD_PROXY_PORT}")
    fi
}

configure_tls() {
    [[ "$OPT_TLS" != "true" ]] && return 0

    # In non-interactive mode, TLS requires --domain= to be set.
    # Without it, disable TLS rather than dying — the user can reconfigure later.
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]] && [[ -z "${OPT_DOMAIN:-}" ]]; then
        if [[ ! -f "${INSTALL_DIR:-}/docker/.env" ]] || ! $SUDO grep -q "^PROXY_TLS__DOMAIN=" "${INSTALL_DIR}/docker/.env" 2>/dev/null; then
            warn "TLS disabled — no --domain= provided. Reconfigure with: install.sh reconfigure --domain=your.host"
            OPT_TLS="false"
            return 0
        fi
    fi

    step "  TLS settings..."

    OPT_DOMAIN=$(resolve_setting "OPT_DOMAIN" "PROXY_TLS__DOMAIN" "Enter your public hostname (e.g., proxy.example.com)" "")
    OPT_ACME_EMAIL=$(resolve_setting "OPT_ACME_EMAIL" "PROXY_TLS__ACME_EMAIL" "Email for Let's Encrypt notifications" "")

    if [[ -z "$OPT_CF_DNS_API_TOKEN" ]] && [[ -z "$OPT_CF_API_KEY" ]]; then
        local existing_token existing_key
        existing_token=$($SUDO grep "^CF_DNS_API_TOKEN=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true)
        existing_key=$($SUDO grep "^CF_API_KEY=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true)

        if [[ -n "$existing_token" ]]; then
            OPT_CF_DNS_API_TOKEN="$existing_token"
        elif [[ -n "$existing_key" ]]; then
            OPT_CF_API_KEY="$existing_key"
            OPT_CF_API_EMAIL=$($SUDO grep "^CF_API_EMAIL=" "${INSTALL_DIR}/docker/.env" 2>/dev/null | cut -d= -f2- || true)
        elif [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
            if ask_yesno "Cloudflare Auth" "Use scoped API token (recommended)? No=use global API key" "yes"; then
                OPT_CF_DNS_API_TOKEN=$(ask_password "Cloudflare" "Enter Cloudflare scoped API token")
            else
                warn "Global API key has broad permissions. Consider a scoped token."
                OPT_CF_API_EMAIL=$(ask_input "Cloudflare" "Cloudflare account email" "")
                OPT_CF_API_KEY=$(ask_password "Cloudflare" "Enter Cloudflare global API key")
            fi
        fi
    fi
}

configure_backup() {
    # An explicit --no-backup always wins, even when an existing install has a
    # backup configured. Without an explicit opt-out, fall through so an upgrade
    # can preserve a previously-configured backup.
    if [[ "$OPT_NO_BACKUP_EXPLICIT" == "true" ]]; then
        OPT_BACKUP="false"
        return 0
    fi

    [[ "$OPT_BACKUP" != "true" ]] && return 0

    # Backup credential resolution follows the same precedence as the core
    # secrets (CLI flag > env var > existing .env > prompt/default). On upgrade
    # the operator should not have to re-pass live S3/restic secrets just to
    # keep backup enabled — that leaks them into shell history and `ps` (#1306).
    #
    # A usable backup requires a restic repository (the mandatory field). Treat
    # backup as already configured when a RESTIC_REPOSITORY is available from any
    # source: a flag/env var on the OPT_* variable, or the existing .env.
    local existing_restic_repo
    existing_restic_repo=$(existing_env_value "RESTIC_REPOSITORY")

    local have_backup_config="false"
    if [[ -n "${OPT_RESTIC_REPOSITORY:-}" ]] || [[ -n "$existing_restic_repo" ]]; then
        have_backup_config="true"
    fi

    # In non-interactive mode, backup requires a repository. Disable only when no
    # repository is available from CLI/env/existing .env — never disable just
    # because the flags were omitted on an already-configured install. When the
    # repository is preserved, the AWS/restic secrets are restored below via
    # resolve_setting, so the operator need not re-pass live secrets on upgrade.
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]] && [[ "$have_backup_config" != "true" ]]; then
        warn "Backup disabled — no S3 credentials provided. Reconfigure with: install.sh reconfigure"
        OPT_BACKUP="false"
        return 0
    fi

    step "  Backup settings..."

    OPT_RESTIC_REPOSITORY=$(resolve_setting "OPT_RESTIC_REPOSITORY" "RESTIC_REPOSITORY" \
        "Restic repository URL (e.g., s3:s3.amazonaws.com/mybucket/llm-proxy)" "")

    if [[ -z "$OPT_RESTIC_PASSWORD" ]]; then
        # URL-safe by default (same generator family as the DB password) to
        # remove any latent risk of breaking a URL the password is composed into.
        OPT_RESTIC_PASSWORD=$(resolve_setting "OPT_RESTIC_PASSWORD" "RESTIC_PASSWORD" \
            "Restic encryption password" "$(gen_urlsafe_secret 24)")
    fi

    OPT_AWS_ACCESS_KEY_ID=$(resolve_setting "OPT_AWS_ACCESS_KEY_ID" "AWS_ACCESS_KEY_ID" "AWS Access Key ID" "")
    OPT_AWS_SECRET_ACCESS_KEY=$(resolve_setting "OPT_AWS_SECRET_ACCESS_KEY" "AWS_SECRET_ACCESS_KEY" "AWS Secret Access Key" "")

    # Preserve the existing backup schedule from .env when --backup-schedule was
    # not supplied explicitly, so an upgrade keeps the configured cadence rather
    # than resetting it to the default. An explicit flag always wins.
    if [[ "$OPT_BACKUP_SCHEDULE_SET" != "true" ]]; then
        local existing_schedule
        existing_schedule=$(existing_env_value "BACKUP_SCHEDULE")
        [[ -n "$existing_schedule" ]] && OPT_BACKUP_SCHEDULE="$existing_schedule"
    fi

    if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        OPT_BACKUP_SCHEDULE=$(ask_input "Backup" "Backup schedule (cron expression)" "${OPT_BACKUP_SCHEDULE}")
    fi
}

configure_monitoring() {
    [[ "$OPT_MONITORING" != "true" ]] && return 0
    step "  Monitoring settings..."

    if [[ -z "$OPT_GRAFANA_PASSWORD" ]]; then
        # URL-safe by default (same generator family as the DB password) to
        # remove any latent risk of breaking a URL the password is composed into.
        OPT_GRAFANA_PASSWORD=$(resolve_setting "OPT_GRAFANA_PASSWORD" "GRAFANA_PASSWORD" \
            "Grafana admin password" "$(gen_urlsafe_secret 16)")
    fi

    # Preserve previously-configured monitoring ports from the existing .env when
    # no explicit override was supplied (same rationale as the core ports). An
    # explicit CLI flag / env var (tracked via *_SET) always wins (#1306).
    if [[ "$OPT_GRAFANA_PORT_SET" != "true" ]]; then
        local existing_grafana_port
        existing_grafana_port=$(existing_env_value "GRAFANA_PORT")
        [[ -n "$existing_grafana_port" ]] && OPT_GRAFANA_PORT="$existing_grafana_port"
    fi
    if [[ "$OPT_PROMETHEUS_PORT_SET" != "true" ]]; then
        local existing_prometheus_port
        existing_prometheus_port=$(existing_env_value "PROMETHEUS_PORT")
        [[ -n "$existing_prometheus_port" ]] && OPT_PROMETHEUS_PORT="$existing_prometheus_port"
    fi

    if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        OPT_GRAFANA_PORT=$(ask_input "Monitoring" "Grafana port" "${OPT_GRAFANA_PORT}")
        OPT_PROMETHEUS_PORT=$(ask_input "Monitoring" "Prometheus port" "${OPT_PROMETHEUS_PORT}")
    fi
}

configure_review() {
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        return 0
    fi

    local features=""
    [[ "$OPT_WAF" == "true" ]] && features+="WAF "
    [[ "$OPT_TLS" == "true" ]] && features+="TLS "
    [[ "$OPT_BACKUP" == "true" ]] && features+="Backup "
    [[ "$OPT_MONITORING" == "true" ]] && features+="Monitor "
    [[ "$OPT_MDNS" == "true" ]] && features+="mDNS "

    local tls_line=""
    [[ "$OPT_TLS" == "true" ]] && tls_line="Domain: ${OPT_DOMAIN}"

    draw_box "Installation Summary" \
        "Version:    ${OPT_VERSION}" \
        "Directory:  ${INSTALL_DIR}" \
        "Components: ${features}" \
        "${tls_line}" \
        "DB Pass:    $(mask_secret "$OPT_POSTGRES_PASSWORD")" \
        "KEK:        $(mask_secret "$OPT_KEK_HEX")" \
        "" \
        "Proceed with installation?"

    if ! ask_yesno "Confirm" "Proceed with installation?" "yes"; then
        configure_features
        configure_core
        [[ "$OPT_TLS" == "true" ]] && configure_tls
        [[ "$OPT_BACKUP" == "true" ]] && configure_backup
        [[ "$OPT_MONITORING" == "true" ]] && configure_monitoring
        configure_review
    fi
}

# ── Debug profile configuration ───────────────────────────────────────────────

# Displays the full debug profile security warning box.
_show_full_profile_warning() {
    draw_box "SECURITY WARNING — Full Debug Profile" \
        "Full profile enables SYS_PTRACE capability and" \
        "disables the read-only filesystem on the proxy" \
        "container. This significantly reduces isolation." \
        "" \
        "Only use Full profile for active debugging sessions." \
        "Do NOT run Full profile in production or on" \
        "internet-exposed hosts."
}

# Present debug profile selection dialog.
# Called from run_configure() when OPT_DEBUG=true.
# Skips dialog if profile already set via CLI, env var, or .env restore.
configure_debug_profile() {
    [[ "$OPT_DEBUG" == "true" ]] || return 0

    if [[ "$OPT_DEBUG_PROFILE_SET" == "false" && "$OPT_NON_INTERACTIVE" == "false" ]]; then
        local minimal_state="off" moderate_state="on" full_state="off"
        case "$OPT_DEBUG_PROFILE" in
            minimal)  minimal_state="on";  moderate_state="off" ;;
            full)     full_state="on";     moderate_state="off" ;;
        esac

        while true; do
            local selected
            selected=$(ask_radiolist "Debug Profile" "Select debug profile:" \
                minimal "Minimal — image swap only" "$minimal_state" \
                moderate "Moderate — +RUST_LOG=debug, RUST_BACKTRACE=1" "$moderate_state" \
                full "Full — +SYS_PTRACE (reduces isolation)" "$full_state")
            OPT_DEBUG_PROFILE="$selected"

            if [[ "$OPT_DEBUG_PROFILE" == "full" ]]; then
                _show_full_profile_warning
                if ask_yesno "Full Profile" "Continue with full debug profile?" "no"; then
                    break
                fi
                minimal_state="off"; moderate_state="on"; full_state="off"
                OPT_DEBUG_PROFILE="moderate"
                continue
            fi
            break
        done
        OPT_DEBUG_PROFILE_SET="true"
        return 0
    fi

    # Non-interactive or pre-set: always show the warning for full profile
    if [[ "$OPT_DEBUG_PROFILE" == "full" ]]; then
        _show_full_profile_warning
    fi
}

run_configure() {
    step "[4/5] Collecting configuration..."
    configure_install_mode
    configure_version
    configure_database_recovery_contract
    configure_features
    configure_debug_profile
    configure_core
    configure_tls
    configure_backup
    configure_monitoring
    configure_review
    info "Configuration complete"
}

# ── Phase 5: Deploy ──────────────────────────────────────────────────────────

deploy_create_dirs() {
    step "  Creating install directory..."
    $SUDO mkdir -p "${INSTALL_DIR}/docker/modsecurity"
    $SUDO mkdir -p "${INSTALL_DIR}/docker/prometheus"
    $SUDO mkdir -p "${INSTALL_DIR}/docker/grafana/provisioning/dashboards"
    $SUDO mkdir -p "${INSTALL_DIR}/docker/grafana/provisioning/datasources"
    # Operator Traefik drop-in directory (issue #1340). Bind-mounted read-only
    # into the Traefik container at /etc/traefik/dynamic by the compose files for
    # custom operator dynamic config (routers/middlewares/redirects). Created
    # EMPTY so a clean install changes no behaviour. `mkdir -p` is idempotent and
    # never wipes — operator drop-in *.yml/*.toml files are PRESERVED on upgrade.
    $SUDO mkdir -p "${INSTALL_DIR}/docker/traefik-dynamic"
    $SUDO mkdir -p "${METADATA_DIR}"

    if [[ "$IS_MACOS" != "true" ]]; then
        $SUDO chown -R "${SERVICE_USER}:${SERVICE_USER}" "${INSTALL_DIR}"
        $SUDO chmod 0750 "${INSTALL_DIR}"
        $SUDO chown root:root "${METADATA_DIR}"
        $SUDO chmod 0755 "${METADATA_DIR}"
    fi
    # The drop-in dir is bind-mounted read-only into the Traefik container, which
    # runs as a non-root, non-SERVICE_USER UID. It MUST be world-traversable or
    # Traefik's file provider crashes at startup ("unable to read directory
    # /etc/traefik/dynamic: permission denied") and silently ignores every
    # operator override. `mkdir -p` inherits the caller's umask (0700 on a
    # restrictive host) and the recursive chown above leaves the mode untouched,
    # so set it explicitly here — idempotent on upgrade; operator-dropped
    # *.yml/*.toml files are not affected (#1548).
    $SUDO chmod 0755 "${INSTALL_DIR}/docker/traefik-dynamic"
    info "Install directory created: ${INSTALL_DIR}"
}

deploy_extract_files() {
    step "  Extracting embedded files..."
    extract_file EMBED_docker_compose_yml "${INSTALL_DIR}/docker/docker-compose.yml"
    extract_file EMBED_docker_compose_hardened_yml "${INSTALL_DIR}/docker/docker-compose.hardened.yml"

    # backend-unavailable/default.conf is bind-mounted as a FILE into the proxy's
    # backend-unavailable nginx sidecar in the BASE compose (always present, not
    # gated by any feature flag). If this file is absent on the host, Docker
    # auto-creates a DIRECTORY at the mount path and `compose up` aborts with
    # "not a directory" — which took prod ingress down on the v0.0.87 upgrade
    # (#1390). Extract it unconditionally with world-readable perms (the nginx
    # container reads it as a non-root UID).
    extract_file EMBED_backend_unavailable_default_conf \
        "${INSTALL_DIR}/docker/backend-unavailable/default.conf" 0644

    # Consul ACL self-heal (#1552). The reconciler is invoked at install/upgrade
    # (deploy_consul_acl_bootstrap) AND on every boot (systemd ExecStartPre /
    # launchd via llap-boot.sh), so it must always be on disk and executable.
    # 0750 root:${SERVICE_USER}: only root/the service user run it; it handles raw
    # Consul SecretIDs and writes the root:${SERVICE_USER} .env.
    extract_file EMBED_docker_consul_acl_ensure_sh \
        "${INSTALL_DIR}/docker/consul-acl-ensure.sh" 0750
    extract_file EMBED_docker_llap_boot_sh \
        "${INSTALL_DIR}/docker/llap-boot.sh" 0750

    [[ "$OPT_WAF" == "true" ]] && {
        extract_file EMBED_docker_compose_waf_yml "${INSTALL_DIR}/docker/docker-compose.waf.yml"
        extract_file EMBED_modsecurity_exclusion_rules "${INSTALL_DIR}/docker/modsecurity/REQUEST-900-EXCLUSION-RULES-BEFORE-CRS.conf"
    }
    [[ "$OPT_TLS" == "true" ]] && \
        extract_file EMBED_docker_compose_tls_yml "${INSTALL_DIR}/docker/docker-compose.tls.yml"
    [[ "$OPT_MONITORING" == "true" ]] && {
        extract_file EMBED_docker_compose_monitoring_yml "${INSTALL_DIR}/docker/docker-compose.monitoring.yml"
        # Monitoring config files are bind-mounted into containers that run as
        # non-root UIDs — they need world-readable (0644) permissions.
        extract_file EMBED_alertmanager_yml "${INSTALL_DIR}/docker/alertmanager/alertmanager.yml" 0644
        extract_file EMBED_prometheus_prometheus_yml "${INSTALL_DIR}/docker/prometheus/prometheus.yml" 0644
        extract_file EMBED_prometheus_rules_llap_rate_limit_yml "${INSTALL_DIR}/docker/prometheus/rules/llap-rate-limit.yml" 0644
        # prometheus.yml's rule_files references rules/llap-sse-health.yml; the
        # rules dir is bind-mounted as a directory, so every file Prometheus
        # loads must be deployed or Prometheus fails to start (#1390).
        extract_file EMBED_prometheus_rules_llap_sse_health_yml "${INSTALL_DIR}/docker/prometheus/rules/llap-sse-health.yml" 0644
        extract_file EMBED_grafana_dashboard_yml "${INSTALL_DIR}/docker/grafana/provisioning/dashboards/dashboard.yml" 0644
        extract_file EMBED_grafana_proxy_json "${INSTALL_DIR}/docker/grafana/provisioning/dashboards/proxy.json" 0644
        extract_file EMBED_grafana_backup_health_json "${INSTALL_DIR}/docker/grafana/provisioning/dashboards/backup-health.json" 0644
        extract_file EMBED_grafana_datasources_yml "${INSTALL_DIR}/docker/grafana/provisioning/datasources/prometheus.yml" 0644
    }
    [[ "$OPT_BACKUP" == "true" ]] && \
        extract_file EMBED_docker_compose_backup_yml "${INSTALL_DIR}/docker/docker-compose.backup.yml"
    if [[ "$IS_MACOS" == "true" ]] && [[ "$MACOS_HOST_NETWORKING" != "true" ]]; then
        # Bridge networking mode: extract the no-mdns overlay for Docker Compose.
        # When host networking is active, PROXY_MDNS__ENABLED=false in .env is sufficient.
        extract_file EMBED_docker_compose_no_mdns_yml "${INSTALL_DIR}/docker/docker-compose.no-mdns.yml"
    fi
    [[ "$OPT_MDNS" != "true" ]] && [[ "$IS_MACOS" != "true" ]] && \
        extract_file EMBED_docker_compose_no_mdns_yml "${INSTALL_DIR}/docker/docker-compose.no-mdns.yml"

    extract_file EMBED_config_example_toml "${INSTALL_DIR}/config.example.toml"

    if [[ "$OPT_DEBUG" == "true" ]]; then
        deploy_write_debug_overlay
    else
        # Clean up debug overlay if downgrading from debug to production
        $SUDO rm -f "${INSTALL_DIR}/docker/docker-compose.debug.yml"
    fi

    info "Files extracted"
}

# Generate docker-compose.debug.yml overlay dynamically based on OPT_DEBUG_PROFILE.
# Called from deploy_extract_files() when OPT_DEBUG=true.
# The overlay is NOT in files.manifest — it is dynamically generated.
# SECURITY NOTE: Backup service MUST only use BACKUP_LOG_LEVEL=debug.
#   NEVER use set -x, BACKUP_DEBUG=true, or any command-tracing mechanism
#   in the backup environment. The backup script handles Consul ACL tokens,
#   PostgreSQL passwords, and S3 credentials.
deploy_write_debug_overlay() {
    local overlay_file="${INSTALL_DIR}/docker/docker-compose.debug.yml"
    local version_tag="${OPT_VERSION:-edge}-debug"

    step "  Writing docker-compose.debug.yml (profile: ${OPT_DEBUG_PROFILE})..."

    {
        echo "# docker-compose.debug.yml — generated by install.sh"
        echo "# Profile: ${OPT_DEBUG_PROFILE} — INTERNAL USE ONLY"
        echo "# DO NOT EDIT — regenerated on each install/upgrade"
        echo "services:"
        echo "  proxy:"
        echo "    image: ghcr.io/llm-api-proxy/server-debug:${version_tag}"

        if [[ "$OPT_DEBUG_PROFILE" == "moderate" || "$OPT_DEBUG_PROFILE" == "full" ]]; then
            echo "    environment:"
            echo "      RUST_LOG: debug"
            echo "      RUST_BACKTRACE: '1'"
        fi

        if [[ "$OPT_DEBUG_PROFILE" == "full" ]]; then
            echo "    read_only: false"
            echo "    cap_add:"
            echo "      - SYS_PTRACE"
        fi

        if [[ "$OPT_BACKUP" == "true" ]]; then
            echo "  backup:"
            echo "    image: ghcr.io/llm-api-proxy/backup-debug:${version_tag}"
            if [[ "$OPT_DEBUG_PROFILE" == "moderate" || "$OPT_DEBUG_PROFILE" == "full" ]]; then
                echo "    environment:"
                echo "      BACKUP_LOG_LEVEL: debug"
            fi
        fi
    } | $SUDO tee "$overlay_file" > /dev/null

    $SUDO chmod 0640 "$overlay_file"
    info "docker-compose.debug.yml written"
}

deploy_write_env() {
    step "  Writing .env configuration..."
    local env_file="${INSTALL_DIR}/docker/.env"

    # SAFETY: Always backup the existing .env before overwriting.
    # This is the last line of defence against secret loss (KEK, pepper,
    # JWT secret, restic password) if the install/upgrade flow
    # incorrectly falls through to a fresh write.
    if $SUDO test -f "$env_file" 2>/dev/null; then
        local safety_backup
        safety_backup="${env_file}.backup.$(date +%Y%m%d-%H%M%S)"
        $SUDO cp "$env_file" "$safety_backup"
        warn "Existing .env backed up to ${safety_backup}"
    fi

    local tmpfile
    tmpfile=$(mktemp)

    local gen_date
    gen_date=$(date -u +%Y-%m-%dT%H:%M:%SZ)

    # Resolve DB pool sizes (#1416): explicit override or CPU-derived auto-size.
    resolve_db_pool_sizes
    {
        printf '# %s\n' "══════════════════════════════════════════════════════════════"
        printf '# LLM API Proxy — Environment Configuration\n'
        printf '# Generated by install.sh v%s on %s\n' "$INSTALLER_VERSION" "$gen_date"
        printf '# %s\n' "══════════════════════════════════════════════════════════════"
        printf '\n# ── Version ──────────────────────────────────────────────────\n'
        printf 'PROXY_VERSION=%s\n' "$OPT_VERSION"
        printf '\n# ── Core ─────────────────────────────────────────────────────\n'
        printf 'POSTGRES_DB=llm_proxy\n'
        printf 'POSTGRES_USER=proxy\n'
        printf 'POSTGRES_PASSWORD=%s\n' "$OPT_POSTGRES_PASSWORD"
        printf 'PROXY_KEK_VALUE=%s\n' "$OPT_KEK_HEX"
        printf 'PROXY_PROXY_KEY_PEPPER=%s\n' "$OPT_PROXY_KEY_PEPPER"
        printf 'PROXY_JWT_SECRET=%s\n' "$OPT_JWT_SECRET"
        printf 'RUST_LOG=info\n'
        printf 'LOG_FORMAT=json\n'
        printf 'PROXY_LISTEN_ADDR=::\n'
        printf 'PROXY_LISTEN_PORT=%s\n' "$OPT_LISTEN_PORT"
        printf 'PROXY_FORWARD_PROXY__PORT=%s\n' "$OPT_FORWARD_PROXY_PORT"
        printf '\n# ── Database connection pools (#1416) ────────────────────────\n'
        printf '# Auto-sized from detected CPU count (control = cpus*%s, data = cpus*%s),\n' \
            "$DB_CONTROL_POOL_PER_CPU" "$DB_DATA_POOL_PER_CPU"
        printf '# clamped to control [%s,%s] / data [%s,%s] so their sum stays well below\n' \
            "$DB_CONTROL_POOL_MIN" "$DB_CONTROL_POOL_MAX" "$DB_DATA_POOL_MIN" "$DB_DATA_POOL_MAX"
        printf '# the Postgres max_connections=100 budget. Override with\n'
        printf '# --control-pool-size / --data-pool-size (preserved across upgrades).\n'
        printf 'PROXY_DATABASE__CONTROL_POOL_SIZE=%s\n' "$RESOLVED_CONTROL_POOL_SIZE"
        printf 'PROXY_DATABASE__DATA_POOL_SIZE=%s\n' "$RESOLVED_DATA_POOL_SIZE"
    } > "$tmpfile"

    if [[ "$OPT_TLS" == "true" ]]; then
        {
            printf '\n# ── TLS ──────────────────────────────────────────────────────\n'
            printf 'PROXY_TLS__ENABLED=true\n'
            printf 'PROXY_TLS__DOMAIN=%s\n' "$OPT_DOMAIN"
            printf 'PROXY_TLS__ACME_EMAIL=%s\n' "$OPT_ACME_EMAIL"
        } >> "$tmpfile"
        if [[ -n "${OPT_CF_DNS_API_TOKEN:-}" ]]; then
            printf 'CF_DNS_API_TOKEN=%s\n' "$OPT_CF_DNS_API_TOKEN" >> "$tmpfile"
        elif [[ -n "${OPT_CF_API_KEY:-}" ]]; then
            printf 'CF_API_EMAIL=%s\n' "$OPT_CF_API_EMAIL" >> "$tmpfile"
            printf 'CF_API_KEY=%s\n' "$OPT_CF_API_KEY" >> "$tmpfile"
        fi
    else
        # Emit PROXY_TLS__ENABLED=false explicitly (rather than omitting it) so an
        # upgrade reconcile can flip a previously-enabled install back off. A
        # bare-absent key would leave a stale PROXY_TLS__ENABLED=true in the live
        # .env, keeping TLS on in app config (#1306). Dormant DOMAIN/ACME_EMAIL/CF
        # keys are intentionally left untouched by the reconcile so a later
        # reconfigure can re-enable TLS without re-prompting.
        {
            printf '\n# ── TLS (disabled) ───────────────────────────────────────────\n'
            printf 'PROXY_TLS__ENABLED=false\n'
        } >> "$tmpfile"
    fi

    if [[ "$OPT_BACKUP" == "true" ]]; then
        {
            printf '\n# ── Backup ───────────────────────────────────────────────────\n'
            printf 'RESTIC_REPOSITORY=%s\n' "$OPT_RESTIC_REPOSITORY"
            printf 'RESTIC_PASSWORD=%s\n' "$OPT_RESTIC_PASSWORD"
            printf 'AWS_ACCESS_KEY_ID=%s\n' "$OPT_AWS_ACCESS_KEY_ID"
            printf 'AWS_SECRET_ACCESS_KEY=%s\n' "$OPT_AWS_SECRET_ACCESS_KEY"
            printf 'BACKUP_SCHEDULE=%s\n' "$OPT_BACKUP_SCHEDULE"
        } >> "$tmpfile"
    fi

    if [[ "$OPT_MONITORING" == "true" ]]; then
        {
            printf '\n# ── Monitoring ───────────────────────────────────────────────\n'
            printf 'GRAFANA_PASSWORD=%s\n' "$OPT_GRAFANA_PASSWORD"
            printf 'GRAFANA_PORT=%s\n' "$OPT_GRAFANA_PORT"
            printf 'PROMETHEUS_PORT=%s\n' "$OPT_PROMETHEUS_PORT"
        } >> "$tmpfile"
    fi

    # macOS: mDNS is always disabled — multicast does not cross the Docker Desktop
    # VM boundary regardless of host networking mode. Write this unconditionally
    # so the proxy service never attempts mDNS advertisement on macOS.
    if [[ "$IS_MACOS" == "true" ]]; then
        {
            printf '\n# ── macOS: mDNS disabled (Docker Desktop VM boundary) ────────\n'
            printf 'PROXY_MDNS__ENABLED=false\n'
        } >> "$tmpfile"
    fi

    {
        printf '\n# ── Debug containers ─────────────────────────────────────────\n'
        printf 'PROXY_DEBUG=%s\n' "$OPT_DEBUG"
        printf 'PROXY_DEBUG_PROFILE=%s\n' "$OPT_DEBUG_PROFILE"
    } >> "$tmpfile"

    $SUDO chmod 0640 "$tmpfile"
    if [[ "$IS_MACOS" != "true" ]]; then
        $SUDO chown "root:${SERVICE_USER}" "$tmpfile" 2>/dev/null || true
    fi

    $SUDO mv "$tmpfile" "$env_file"
    info ".env written (atomic)"
    log "ENV: $($SUDO grep -c '=' "$env_file") variables set"
}

deploy_upgrade_env() {
    local env_file="${INSTALL_DIR}/docker/.env"
    if [[ ! -f "$env_file" ]]; then
        deploy_write_env
        return 0
    fi

    local backup
    backup="${env_file}.backup.$(date +%Y%m%d-%H%M%S)"
    $SUDO cp "$env_file" "$backup"
    info "Backed up .env to ${backup}"

    $SUDO sed -i "s/^PROXY_VERSION=.*/PROXY_VERSION=${OPT_VERSION}/" "$env_file"

    # Build a reference .env reflecting the fully-resolved settings. run_configure
    # has already applied the CLI > env > existing-.env > default precedence to the
    # OPT_* variables, so the reference encodes the desired final state for every
    # OVERRIDE-CAPABLE key: omitted flags keep the existing value, provided flags
    # carry the override (#1306).
    local ref_file
    ref_file=$(mktemp); CLEANUP_FILES+=("$ref_file")
    local old_env_file="${env_file}"
    local old_install_dir="${INSTALL_DIR}"
    INSTALL_DIR=$(mktemp -d); CLEANUP_FILES+=("$INSTALL_DIR")
    mkdir -p "${INSTALL_DIR}/docker"
    deploy_write_env
    mv "${INSTALL_DIR}/docker/.env" "$ref_file"
    rm -rf "$INSTALL_DIR"
    INSTALL_DIR="$old_install_dir"

    # Vetted set of OVERRIDE-CAPABLE keys: the only managed keys the reconcile
    # may overwrite in place. Every one is resolved CLI > env > existing-.env >
    # default (via resolve_setting / existing_env_value / an explicit existing
    # .env read in the configure_* functions), so the reference value already
    # equals the existing value UNLESS the operator supplied an override — making
    # an in-place overwrite a no-op when flags are omitted and a true override
    # when they are not. Any key NOT in this list (hardcoded constants like
    # RUST_LOG / LOG_FORMAT / PROXY_LISTEN_ADDR, and operator hand-edits) is
    # preserved verbatim, so an upgrade never reverts a value the operator did
    # not explicitly change (#1306). PROXY_DEBUG / PROXY_DEBUG_PROFILE are
    # deliberately excluded here: deploy_upgrade_debug_state reconciles them
    # afterwards from their own resolved state.
    #
    # Keep this list in sync with the resolve_setting / existing-.env reads in
    # configure_core, configure_tls, configure_backup, and configure_monitoring.
    # The ports below are resolved from the existing .env (preserve-on-omit) yet
    # honour an explicit --*-port flag / PROXY_INSTALL_*_PORT env via their *_SET
    # markers, so they belong in the override set.
    local override_keys
    override_keys=$(cat <<'OVERRIDE_KEYS'
POSTGRES_PASSWORD
PROXY_KEK_VALUE
PROXY_PROXY_KEY_PEPPER
PROXY_JWT_SECRET
PROXY_LISTEN_PORT
PROXY_FORWARD_PROXY__PORT
PROXY_DATABASE__CONTROL_POOL_SIZE
PROXY_DATABASE__DATA_POOL_SIZE
PROXY_TLS__ENABLED
PROXY_TLS__DOMAIN
PROXY_TLS__ACME_EMAIL
CF_DNS_API_TOKEN
CF_API_KEY
CF_API_EMAIL
RESTIC_REPOSITORY
RESTIC_PASSWORD
AWS_ACCESS_KEY_ID
AWS_SECRET_ACCESS_KEY
BACKUP_SCHEDULE
GRAFANA_PASSWORD
GRAFANA_PORT
PROMETHEUS_PORT
OVERRIDE_KEYS
)

    # One-time key migration. A pre-#1632 install may contain the legacy
    # single-underscore spelling, which Figment loaded into a dead top-level
    # field instead of the listener configuration. The reference contains only
    # the canonical nested spelling; drop the legacy line when that replacement
    # is present so the upgraded .env has one unambiguous authority.
    local legacy_key_replacements
    legacy_key_replacements=$(cat <<'LEGACY_KEY_REPLACEMENTS'
PROXY_FORWARD_PROXY_PORT=PROXY_FORWARD_PROXY__PORT
LEGACY_KEY_REPLACEMENTS
)

    # Mutually-exclusive Cloudflare DNS-01 auth keys. The lego provider uses
    # CF_DNS_API_TOKEN when present and otherwise the CF_API_EMAIL/CF_API_KEY
    # pair; setting both is unsupported (see docker/docker-compose.tls.yml). The
    # reference .env selects exactly ONE mode, so when the operator switches modes
    # the previous mode's keys must be PRUNED rather than preserved — otherwise a
    # stale CF_DNS_API_TOKEN would silently win over an explicit global-key
    # override. Pruning only kicks in when the reference actually selects a CF
    # mode, so toggling TLS off still preserves the keys verbatim (#1306).
    local cf_auth_keys
    cf_auth_keys=$(cat <<'CF_AUTH_KEYS'
CF_DNS_API_TOKEN
CF_API_KEY
CF_API_EMAIL
CF_AUTH_KEYS
)

    # Reconcile the live .env to the reference:
    #   1. Update OVERRIDE-CAPABLE keys whose resolved value changed (flag
    #      overrides); for omitted flags the reference equals the existing value
    #      so this is a no-op write.
    #   2. Preserve every other existing live value verbatim — including
    #      non-override-capable managed keys (ports, RUST_LOG, …) and any
    #      custom/unmanaged keys the operator added by hand.
    #   3. Drop a live Cloudflare auth key when the operator switched CF auth
    #      modes (it is absent from the reference and the reference selects a CF
    #      mode), so the explicit override actually takes effect.
    #   4. Append reference keys genuinely introduced by the new version.
    # awk is used (not sed) so arbitrary secret characters can't break escaping.
    local reconciled
    reconciled=$(mktemp); CLEANUP_FILES+=("$reconciled")
    # shellcheck disable=SC2016  # the awk program is intentionally single-quoted; $ refs are awk fields/vars, not shell expansions
    $SUDO awk \
        -v upgrade_marker="# Added by upgrade to v${OPT_VERSION} on $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        -v override_keys="$override_keys" \
        -v legacy_key_replacements="$legacy_key_replacements" \
        -v cf_auth_keys="$cf_auth_keys" '
        BEGIN {
            n = split(override_keys, _ok, "\n")
            for (i = 1; i <= n; i++) {
                if (_ok[i] != "") is_override[_ok[i]] = 1
            }
            legacy_count = split(legacy_key_replacements, _legacy, "\n")
            for (i = 1; i <= legacy_count; i++) {
                separator = index(_legacy[i], "=")
                if (separator > 1) {
                    legacy_key = substr(_legacy[i], 1, separator - 1)
                    legacy_replacement[legacy_key] = substr(_legacy[i], separator + 1)
                }
            }
            m = split(cf_auth_keys, _cf, "\n")
            for (i = 1; i <= m; i++) {
                if (_cf[i] != "") is_cf_auth[_cf[i]] = 1
            }
        }
        # First pass: load reference key=value pairs. Note whether the reference
        # selects a Cloudflare auth mode (any CF auth key present).
        FNR == NR {
            if ($0 ~ /^[A-Za-z_][A-Za-z0-9_]*=/) {
                eq = index($0, "=")
                key = substr($0, 1, eq - 1)
                ref_val[key] = substr($0, eq + 1)
                ref_seen[key] = 1
                ref_order[++ref_count] = key
                if (key in is_cf_auth) ref_has_cf_auth = 1
            }
            next
        }
        # Second pass: rewrite the live .env. Track which reference keys exist in
        # the live file so genuinely-new ones can be appended; only override the
        # value for vetted override-capable keys; prune stale CF auth keys.
        {
            if ($0 ~ /^[A-Za-z_][A-Za-z0-9_]*=/) {
                eq = index($0, "=")
                key = substr($0, 1, eq - 1)
                if (key in ref_seen) live_has[key] = 1
                # Replace a legacy key only when its canonical successor exists
                # in this version reference file.
                if ((key in legacy_replacement) && (legacy_replacement[key] in ref_seen)) {
                    next
                }
                # Drop a CF auth key the operator switched away from.
                if ((key in is_cf_auth) && !(key in ref_seen) && ref_has_cf_auth) {
                    next
                }
                if ((key in is_override) && (key in ref_seen)) {
                    print key "=" ref_val[key]
                    next
                }
            }
            print
        }
        # After live lines: append reference keys not present in the live .env.
        END {
            appended = 0
            for (i = 1; i <= ref_count; i++) {
                key = ref_order[i]
                if (!(key in live_has)) {
                    if (!appended) { print ""; print upgrade_marker; appended = 1 }
                    print key "=" ref_val[key]
                }
            }
        }
    ' "$ref_file" "$old_env_file" > "$reconciled"

    $SUDO cp "$reconciled" "$old_env_file"
    rm -f "$reconciled"

    deploy_upgrade_debug_state
}

# Load debug state persisted from a previous install/upgrade.
# Called after detect_os() (which resolves INSTALL_DIR) and before the warning gate.
# Respects CLI flags and env vars — does NOT override them.
load_debug_state_from_env() {
    local env_file="${INSTALL_DIR}/docker/.env"
    [[ -f "$env_file" ]] || return 0

    # Read persisted values (|| true prevents set -e exit when key is absent)
    local persisted_debug persisted_profile
    persisted_debug=$(grep -E '^PROXY_DEBUG=' "$env_file" 2>/dev/null | tail -1 | cut -d= -f2- || true)
    persisted_profile=$(grep -E '^PROXY_DEBUG_PROFILE=' "$env_file" 2>/dev/null | tail -1 | cut -d= -f2- || true)

    # Apply persisted debug flag only if not overridden by CLI or env var
    if [[ "$OPT_DEBUG" == "false" && "$OPT_NO_DEBUG" == "false" && -n "$persisted_debug" ]]; then
        OPT_DEBUG="$persisted_debug"
    fi

    # Apply persisted profile only if not already set explicitly AND debug is on.
    # When PROXY_DEBUG=false the profile is irrelevant — loading it would trip the
    # deferred validation below ("--debug-profile requires --debug") on upgrade.
    if [[ "$OPT_DEBUG_PROFILE_SET" == "false" && "$OPT_DEBUG" == "true" && -n "$persisted_profile" ]]; then
        # Validate profile value (handle malformed .env)
        case "$persisted_profile" in
            minimal|moderate|full)
                OPT_DEBUG_PROFILE="$persisted_profile"
                OPT_DEBUG_PROFILE_SET="true"  # treat as explicit to skip the dialog
                ;;
            *)
                warn "Invalid PROXY_DEBUG_PROFILE in .env: '${persisted_profile}' — defaulting to moderate"
                OPT_DEBUG_PROFILE="moderate"
                ;;
        esac
    fi

    # Deferred validation: --debug-profile= without effective debug mode
    if [[ "$OPT_DEBUG_PROFILE_SET" == "true" && "$OPT_DEBUG" == "false" && "$OPT_NO_DEBUG" == "false" ]]; then
        die "--debug-profile requires --debug (or PROXY_DEBUG=true in .env)"
    fi
}

# Display INTERNAL USE ONLY warning and confirmation when debug mode is active.
# Called after load_debug_state_from_env() and before run_preflight().
# Skips confirmation gate in non-interactive mode, but always shows the warning.
warn_debug_mode() {
    [[ "$OPT_DEBUG" == "true" ]] || return 0

    draw_box "DEBUG CONTAINERS — INTERNAL USE ONLY" \
        "You are about to install using private debug container" \
        "images from GHCR. These images are intended for internal" \
        "development and testing only. They are NOT suitable for" \
        "production use and are NOT publicly available." \
        "" \
        "Debug profile: ${OPT_DEBUG_PROFILE}" \
        "" \
        "Ensure you have a valid GitHub PAT with package:read" \
        "access to the llm-api-proxy organisation."

    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        return 0
    fi

    if ! ask_yesno "Debug Containers" "Continue with debug containers?" "no"; then
        die "Aborted."
    fi
}

# Update PROXY_DEBUG and PROXY_DEBUG_PROFILE in an existing .env file.
# Uses sed for in-place updates (intentionally different from deploy_upgrade_env()
# which only appends missing keys — we need to UPDATE and REMOVE too).
deploy_upgrade_debug_state() {
    local env_file="${INSTALL_DIR}/docker/.env"
    [[ -f "$env_file" ]] || return 0

    if grep -qE '^PROXY_DEBUG=' "$env_file"; then
        # Update existing key
        $SUDO sed -i "s|^PROXY_DEBUG=.*|PROXY_DEBUG=${OPT_DEBUG}|" "$env_file"
    else
        # Append new key (upgrading from production to debug for first time)
        echo "PROXY_DEBUG=${OPT_DEBUG}" | $SUDO tee -a "$env_file" > /dev/null
    fi

    if [[ "$OPT_DEBUG" == "true" ]]; then
        if grep -qE '^PROXY_DEBUG_PROFILE=' "$env_file"; then
            $SUDO sed -i "s|^PROXY_DEBUG_PROFILE=.*|PROXY_DEBUG_PROFILE=${OPT_DEBUG_PROFILE}|" "$env_file"
        else
            echo "PROXY_DEBUG_PROFILE=${OPT_DEBUG_PROFILE}" | $SUDO tee -a "$env_file" > /dev/null
        fi
    else
        # Clear profile when disabling debug (prevent stale state)
        if grep -qE '^PROXY_DEBUG_PROFILE=' "$env_file"; then
            $SUDO sed -i "s|^PROXY_DEBUG_PROFILE=.*|PROXY_DEBUG_PROFILE=|" "$env_file"
        else
            # Append empty profile key so future loads have a consistent key present
            echo "PROXY_DEBUG_PROFILE=" | $SUDO tee -a "$env_file" > /dev/null
        fi
    fi
}

# ── Deploy phase: compose command, stack start, Consul ACL ───────────────────

# Return success when an address is a syntactically valid, container-routable
# DNS server literal. Loopback and link-local addresses are deliberately
# rejected: they can work in the host network namespace but are not reachable
# from bridge-networked services such as the backup agent.
container_dns_server_is_usable() {
    local address="${1,,}"

    if [[ "$address" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
        local first second third fourth extra octet
        IFS=. read -r first second third fourth extra <<< "$address"
        [[ -z "${extra:-}" ]] || return 1
        for octet in "$first" "$second" "$third" "$fourth"; do
            (( 10#$octet <= 255 )) || return 1
        done
        (( 10#$first != 0 && 10#$first != 127 && 10#$first < 224 )) || return 1
        (( 10#$first != 169 || 10#$second != 254 )) || return 1
        return 0
    fi

    [[ "$address" == *:* ]] || return 1
    [[ "$address" =~ ^[0-9a-f:]+$ ]] || return 1
    if [[ "$address" == :* && "$address" != ::* ]]; then
        return 1
    fi
    if [[ "$address" == *: && "$address" != *:: ]]; then
        return 1
    fi
    [[ "$address" != *:::* ]] || return 1
    if [[ "$address" == *::* ]]; then
        [[ "${address#*::}" != *::* ]] || return 1
        local left="${address%%::*}" right="${address#*::}"
        local -a left_parts=() right_parts=()
        [[ -z "$left" ]] || IFS=: read -r -a left_parts <<< "$left"
        [[ -z "$right" ]] || IFS=: read -r -a right_parts <<< "$right"
        (( ${#left_parts[@]} + ${#right_parts[@]} < 8 )) || return 1
        local part
        for part in "${left_parts[@]}" "${right_parts[@]}"; do
            [[ "$part" =~ ^[0-9a-f]{1,4}$ ]] || return 1
        done
    else
        local -a parts=()
        IFS=: read -r -a parts <<< "$address"
        (( ${#parts[@]} == 8 )) || return 1
        local part
        for part in "${parts[@]}"; do
            [[ "$part" =~ ^[0-9a-f]{1,4}$ ]] || return 1
        done
    fi

    local hex_digits="${address//:/}"
    local nonzero_digits="${hex_digits//0/}"
    [[ -n "$nonzero_digits" ]] || return 1
    local last_hextet="${address##*:}"
    if [[ "$nonzero_digits" == "1" && "$last_hextet" =~ ^0*1$ ]]; then
        return 1
    fi
    [[ ! "$address" =~ ^fe[89ab] ]] || return 1
    [[ ! "$address" =~ ^ff ]] || return 1
    return 0
}

# Print the unique interfaces carrying a default IPv6 or IPv4 route. Resolver
# discovery is intentionally scoped to these links so a stale global
# systemd-resolved DNS list cannot override the working uplink configuration.
container_dns_default_route_interfaces() {
    {
        ip -o -6 route show default 2>/dev/null || true
        ip -o -4 route show default 2>/dev/null || true
    } | awk '
        {
            for (i = 1; i < NF; i++) {
                if ($i == "dev" && !seen[$(i + 1)]++) {
                    print $(i + 1)
                    break
                }
            }
        }
    '
}

container_systemd_resolved_is_active() {
    command -v resolvectl >/dev/null 2>&1 || return 1
    if command -v systemctl >/dev/null 2>&1 \
        && systemctl is-active --quiet systemd-resolved 2>/dev/null; then
        return 0
    fi
    local resolved_socket="${CONTAINER_DNS_RESOLVED_SOCKET_PATH:-/run/systemd/resolve/io.systemd.Resolve}"
    [[ -S "$resolved_socket" ]]
}

# Emit at most three validated upstream literals, one per line. Three matches
# libc's portable MAXNS limit. systemd-resolved hosts use DNS from the active
# default-route links; other hosts fall back to their resolver file.
discover_container_dns_servers() {
    local -a candidates=()
    local candidate interface line

    if container_systemd_resolved_is_active; then
        while IFS= read -r interface; do
            [[ -n "$interface" ]] || continue
            while IFS= read -r line; do
                line="${line#*:}"
                for candidate in $line; do
                    candidates+=("$candidate")
                done
            done < <(resolvectl dns "$interface" 2>/dev/null || true)
        done < <(container_dns_default_route_interfaces)
    else
        local resolv_conf="${CONTAINER_DNS_RESOLV_CONF_PATH:-/etc/resolv.conf}"
        if [[ -r "$resolv_conf" ]]; then
            while read -r _ candidate _; do
                candidates+=("$candidate")
            done < <(awk '$1 == "nameserver" && NF >= 2 { print $1, $2 }' "$resolv_conf")
        fi
    fi

    local emitted=0
    local seen=$'\n'
    for candidate in "${candidates[@]}"; do
        container_dns_server_is_usable "$candidate" || continue
        [[ "$seen" != *$'\n'"$candidate"$'\n'* ]] || continue
        printf '%s\n' "$candidate"
        seen+="$candidate"$'\n'
        emitted=$((emitted + 1))
        (( emitted < 3 )) || break
    done

    (( emitted > 0 ))
}

# Generate a Linux-only Compose override that gives outbound services direct,
# container-reachable DNS upstreams. The file is replaced atomically on every
# install/upgrade and is included before any Compose mutation occurs.
deploy_write_container_dns_overlay() {
    local overlay_file="${INSTALL_DIR}/docker/docker-compose.dns.yml"

    if [[ "$IS_MACOS" == "true" ]]; then
        $SUDO rm -f "$overlay_file"
        return 0
    fi

    step "  Discovering container DNS upstreams..."
    local discovered
    if ! discovered=$(discover_container_dns_servers); then
        die "Container DNS preflight failed: no container-reachable DNS upstreams were discovered"
    fi

    local -a servers=()
    mapfile -t servers <<< "$discovered"
    (( ${#servers[@]} > 0 )) \
        || die "Container DNS preflight failed: no container-reachable DNS upstreams were discovered"

    local tmpfile
    tmpfile=$($SUDO mktemp "${INSTALL_DIR}/docker/.docker-compose.dns.yml.XXXXXX")
    CLEANUP_FILES+=("$tmpfile")
    {
        echo "# docker-compose.dns.yml — generated by install.sh"
        echo "# DO NOT EDIT — regenerated on each install/upgrade"
        echo "services:"
        echo "  proxy:"
        echo "    dns:"
        local server
        for server in "${servers[@]}"; do
            printf '      - "%s"\n' "$server"
        done
        if [[ "$OPT_BACKUP" == "true" ]]; then
            echo "  backup:"
            echo "    dns:"
            for server in "${servers[@]}"; do
                printf '      - "%s"\n' "$server"
            done
        fi
    } | $SUDO tee "$tmpfile" > /dev/null

    $SUDO chmod 0640 "$tmpfile"
    if [[ "$IS_MACOS" != "true" ]]; then
        $SUDO chown "root:${SERVICE_USER}" "$tmpfile" 2>/dev/null || true
    fi
    $SUDO mv "$tmpfile" "$overlay_file"
    info "Container DNS overlay written with ${#servers[@]} upstream(s)"
}

deploy_write_compose_command() {
    step "  Generating compose-command.sh..."
    local cmd_file="${INSTALL_DIR}/compose-command.sh"

    local -a overlays=("docker-compose.yml" "docker-compose.hardened.yml")
    [[ "$OPT_WAF" == "true" ]] && overlays+=("docker-compose.waf.yml")
    [[ "$OPT_TLS" == "true" ]] && overlays+=("docker-compose.tls.yml")
    [[ "$OPT_MONITORING" == "true" ]] && overlays+=("docker-compose.monitoring.yml")
    [[ "$OPT_BACKUP" == "true" ]] && overlays+=("docker-compose.backup.yml")
    $SUDO test -f "${INSTALL_DIR}/docker/docker-compose.dns.yml" \
        && overlays+=("docker-compose.dns.yml")
    if [[ "$IS_MACOS" == "true" ]] && [[ "$MACOS_HOST_NETWORKING" == "true" ]]; then
        # Host networking available — no bridge overlay needed.
        # mDNS disabled via PROXY_MDNS__ENABLED=false in .env
        :
    elif [[ "$IS_MACOS" == "true" ]] || [[ "$OPT_MDNS" != "true" ]]; then
        overlays+=("docker-compose.no-mdns.yml")
    fi
    # Debug overlay must be last — overrides hardened overlay settings
    [[ "$OPT_DEBUG" == "true" ]] && overlays+=("docker-compose.debug.yml")

    local tmpfile
    tmpfile=$(mktemp)
    {
        echo '#!/bin/bash'
        echo "# compose-command.sh — single source of truth for running the stack."
        echo "# Generated by install.sh v${INSTALLER_VERSION}"
        echo 'set -euo pipefail'
        echo "cd \"${INSTALL_DIR}/docker\""
        echo -n 'exec docker compose'
        for overlay in "${overlays[@]}"; do
            echo " \\"
            echo -n "  -f ${overlay}"
        done
        echo " \\"
        # shellcheck disable=SC1003  # Backslash is a line continuation in the generated script
        echo '  --env-file .env \'
        echo '  "$@"'
    } > "$tmpfile"

    $SUDO mv "$tmpfile" "$cmd_file"
    $SUDO chmod 0750 "$cmd_file"
    if [[ "$IS_MACOS" != "true" ]]; then
        $SUDO chown "root:${SERVICE_USER}" "$cmd_file" 2>/dev/null || true
    fi
    info "compose-command.sh generated with overlays: ${overlays[*]}"
}

deploy_backup_compose_files() {
    if [[ ! -d "${INSTALL_DIR}/docker" ]]; then
        return 0
    fi
    local backup_dir
    backup_dir="${INSTALL_DIR}/compose-backup-$(date +%Y%m%d-%H%M%S)"
    $SUDO mkdir -p "$backup_dir"
    $SUDO cp "${INSTALL_DIR}"/docker/docker-compose*.yml "$backup_dir/" 2>/dev/null || true
    $SUDO cp "${INSTALL_DIR}/compose-command.sh" "$backup_dir/" 2>/dev/null || true
    info "Compose files backed up to ${backup_dir}"
}

deploy_pull_images() {
    step "  Pulling Docker images..."
    $SUDO "${INSTALL_DIR}/compose-command.sh" pull >> "$LOG_FILE" 2>&1 || {
        if [[ "$OPT_DEBUG" == "true" ]]; then
            local version_tag="${OPT_VERSION:-edge}-debug"
            local images="ghcr.io/llm-api-proxy/server-debug:${version_tag}"
            [[ "$OPT_BACKUP" == "true" ]] && images+=", ghcr.io/llm-api-proxy/backup-debug:${version_tag}"
            draw_box "FAILED: Pull debug Docker images" \
                "" \
                "Error pulling one or more private debug images:" \
                "  ${images}" \
                "" \
                "This usually means:" \
                "  • Your GitHub PAT lacks package:read access" \
                "  • The version tag '${version_tag}' doesn't exist" \
                "  • GHCR is temporarily unavailable" \
                "" \
                "Try:" \
                "  1. Verify your token: export CR_PAT=ghp_xxx" \
                "  2. Check available tags at: ghcr.io/llm-api-proxy/server-debug" \
                "  3. Re-run with: install.sh install --debug --github-token=ghp_xxx" \
                "" \
                "Full log: ${LOG_FILE}"
        else
            draw_box "FAILED: Pull Docker images" \
                "" \
                "Error pulling one or more images." \
                "" \
                "This usually means:" \
                "  • The version tag doesn't exist" \
                "  • GHCR is temporarily unavailable" \
                "  • Network/proxy is blocking the request" \
                "" \
                "Try:" \
                "  1. Check: ghcr.io/llm-api-proxy/server" \
                "  2. Run: docker pull <image> manually" \
                "  3. Re-run install.sh to retry" \
                "" \
                "Full log: ${LOG_FILE}"
        fi
        exit 1
    }
    info "Docker images pulled"
}

database_recovery_journal_path() {
    printf '%s/database-rollback/recovery-journal.json\n' "$METADATA_DIR"
}

database_recovery_identifier_is_safe() {
    [[ "$1" =~ ^[A-Za-z_][A-Za-z0-9_]{0,62}$ ]]
}

# Persist every identity needed to reverse a non-transactional database-name
# swap after SIGKILL or host restart. The journal is replaced atomically and is
# private to root; it remains until either source recovery or target health is
# complete.
database_write_recovery_journal() {
    local phase="$1"
    local rollback_root journal payload journal_staging
    case "$phase" in
        deploy-mutating|staging|swap-active|forward-target-healthy|target-healthy) ;;
        *) return 1 ;;
    esac
    is_stable_semver "$DATABASE_ROLLBACK_SOURCE_VERSION" || return 1
    database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_ACTIVE_DATABASE" || return 1
    if [[ "$phase" == "staging" || "$phase" == "swap-active" ]]; then
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    elif [[ "$phase" == "forward-target-healthy" ]]; then
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    elif [[ "$phase" == "target-healthy" \
        && ( -n "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
            || -n "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" ) ]]; then
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    fi
    rollback_root="${METADATA_DIR}/database-rollback"
    [[ "$(dirname -- "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT")" == "$rollback_root" ]] || return 1
    [[ "$(basename -- "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT")" == .source-deploy-* ]] || return 1
    [[ "$(dirname -- "$DATABASE_ROLLBACK_SOURCE_METADATA_PATH")" == "$METADATA_DIR" ]] || return 1
    [[ "$(basename -- "$DATABASE_ROLLBACK_SOURCE_METADATA_PATH")" == "install.json" ]] || return 1

    payload=$(mktemp) || return 1
    CLEANUP_FILES+=("$payload")
    if ! jq -n \
        --arg phase "$phase" \
        --arg source_version "$DATABASE_ROLLBACK_SOURCE_VERSION" \
        --arg metadata_path "$DATABASE_ROLLBACK_SOURCE_METADATA_PATH" \
        --arg snapshot_path "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT" \
        --arg active_database "$DATABASE_ROLLBACK_ACTIVE_DATABASE" \
        --arg safety_database "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
        --arg replacement_database "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" \
        '{format_version: 1, phase: $phase, source_version: $source_version,
          metadata_path: $metadata_path,
          snapshot_path: $snapshot_path, active_database: $active_database,
          safety_database: $safety_database,
          replacement_database: $replacement_database}' > "$payload"; then
        return 1
    fi
    journal=$(database_recovery_journal_path)
    journal_staging="${rollback_root}/.recovery-journal-$$"
    if $SUDO test -e "$journal_staging"; then
        return 1
    fi
    if ! $SUDO install -d -m 0700 "$rollback_root" \
        || ! $SUDO install -m 0600 "$payload" "$journal_staging" \
        || ! $SUDO mv "$journal_staging" "$journal"; then
        $SUDO rm -f "$journal_staging" 2>/dev/null || true
        return 1
    fi
    DATABASE_ROLLBACK_RECOVERY_PHASE="$phase"
}

database_load_recovery_journal() {
    local rollback_root journal payload phase source_version metadata_path snapshot_path
    local active_database safety_database replacement_database
    rollback_root="${METADATA_DIR}/database-rollback"
    journal=$(database_recovery_journal_path)
    if ! $SUDO test -f "$journal" || $SUDO test -L "$journal"; then
        return 1
    fi
    payload=$(mktemp) || return 1
    CLEANUP_FILES+=("$payload")
    if ! $SUDO cat "$journal" > "$payload" \
        || ! jq -e '
            .format_version == 1 and
            (.phase == "deploy-mutating" or .phase == "staging" or
             .phase == "swap-active" or .phase == "forward-target-healthy" or
             .phase == "target-healthy") and
            (.source_version | type == "string" and test("^[0-9]+[.][0-9]+[.][0-9]+$")) and
            (.metadata_path | type == "string") and
            (.snapshot_path | type == "string") and
            (.active_database | type == "string" and test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
            (.safety_database | type == "string") and
            (.replacement_database | type == "string") and
            (if .phase == "deploy-mutating" then
                .safety_database == "" and .replacement_database == ""
             elif .phase == "forward-target-healthy" then
                (.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))
             elif .phase == "target-healthy" then
                ((.safety_database == "" and .replacement_database == "") or
                 ((.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                  (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))))
             else
                (.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))
             end)' "$payload" >/dev/null; then
        fail "Pending database recovery journal is malformed; refusing deployment."
        return 1
    fi
    phase=$(jq -r '.phase' "$payload")
    source_version=$(jq -r '.source_version' "$payload")
    metadata_path=$(jq -r '.metadata_path' "$payload")
    snapshot_path=$(jq -r '.snapshot_path' "$payload")
    active_database=$(jq -r '.active_database' "$payload")
    safety_database=$(jq -r '.safety_database' "$payload")
    replacement_database=$(jq -r '.replacement_database' "$payload")
    if [[ "$(dirname -- "$snapshot_path")" != "$rollback_root" ]] \
        || [[ "$(basename -- "$snapshot_path")" != .source-deploy-* ]]; then
        fail "Pending database recovery journal references an unsafe source snapshot."
        return 1
    fi
    if [[ "$(dirname -- "$metadata_path")" != "$METADATA_DIR" ]] \
        || [[ "$(basename -- "$metadata_path")" != "install.json" ]]; then
        fail "Pending database recovery journal references unsafe install metadata."
        return 1
    fi

    DATABASE_ROLLBACK_RECOVERY_PHASE="$phase"
    DATABASE_ROLLBACK_SOURCE_VERSION="$source_version"
    DATABASE_ROLLBACK_SOURCE_METADATA_PATH="$metadata_path"
    DATABASE_ROLLBACK_DEPLOY_SNAPSHOT="$snapshot_path"
    DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="true"
    DATABASE_ROLLBACK_ACTIVE_DATABASE="$active_database"
    DATABASE_ROLLBACK_SAFETY_DATABASE="$safety_database"
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE="$replacement_database"
    if [[ "$phase" == "swap-active" ]]; then
        DATABASE_ROLLBACK_SWAP_ACTIVE="true"
    else
        DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    fi
    DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE="false"
}

database_clear_recovery_journal() {
    local journal
    journal=$(database_recovery_journal_path)
    if ! $SUDO rm -f "$journal"; then
        return 1
    fi
    DATABASE_ROLLBACK_RECOVERY_PHASE=""
}

# Preserve the exact source deploy tree before a rollback rewrites embedded
# Compose/configuration files. The root-only archive is kept until the recovered
# target proves healthy, so every earlier failure can restore reboot-safe state.
database_snapshot_source_deploy_state() {
    [[ "$DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED" != "true" ]] || return 0
    local rollback_root snapshot_dir temp_archive checksum source_version active_database
    local metadata_path metadata_archive metadata_checksum checksums_file
    local -a entries=("docker")

    [[ -d "${INSTALL_DIR}/docker" ]] || {
        fail "Cannot snapshot source deploy state: docker directory is missing."
        return 1
    }
    [[ -f "${INSTALL_DIR}/compose-command.sh" \
        && ! -L "${INSTALL_DIR}/compose-command.sh" \
        && -x "${INSTALL_DIR}/compose-command.sh" ]] || {
        fail "Cannot snapshot source deploy state: compose command is missing or unsafe."
        return 1
    }
    entries+=("compose-command.sh")
    [[ -f "${INSTALL_DIR}/.version" ]] && entries+=(".version")
    source_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$source_version" || {
        fail "Cannot snapshot source deploy state: installed source version is invalid."
        return 1
    }
    metadata_path="${EXISTING_INSTALL:-${METADATA_DIR}/install.json}"
    [[ -f "$metadata_path" && ! -L "$metadata_path" \
        && "$(dirname -- "$metadata_path")" == "$METADATA_DIR" \
        && "$(basename -- "$metadata_path")" == "install.json" ]] || {
        fail "Cannot snapshot source deploy state: install metadata is missing or unsafe."
        return 1
    }
    active_database=$(database_install_identifier) || return 1

    rollback_root="${METADATA_DIR}/database-rollback"
    snapshot_dir="${rollback_root}/.source-deploy-$(date -u +%Y%m%dT%H%M%SZ)-$$"
    temp_archive=$(mktemp) || {
        fail "Could not allocate temporary storage for the source deploy snapshot."
        return 1
    }
    metadata_archive=$(mktemp) || return 1
    checksums_file=$(mktemp) || return 1
    CLEANUP_FILES+=("$temp_archive" "$metadata_archive" "$checksums_file")

    if ! $SUDO tar -C "$INSTALL_DIR" -cpf "$temp_archive" "${entries[@]}" \
        || ! $SUDO tar -C "$METADATA_DIR" -cpf "$metadata_archive" "install.json"; then
        fail "Could not archive the source deploy state before rollback."
        return 1
    fi
    if ! checksum=$(sha256_file "$temp_archive") \
        || ! metadata_checksum=$(sha256_file "$metadata_archive") \
        || ! printf '%s  source-deploy.tar\n%s  source-metadata.tar\n' \
            "$checksum" "$metadata_checksum" > "$checksums_file"; then
        fail "Could not checksum the source deploy snapshot."
        return 1
    fi
    if $SUDO test -e "$snapshot_dir"; then
        fail "Source deploy snapshot collision: ${snapshot_dir}"
        return 1
    fi
    if ! $SUDO install -d -m 0700 "$rollback_root" "$snapshot_dir" \
        || ! $SUDO install -m 0600 "$temp_archive" "${snapshot_dir}/source-deploy.tar" \
        || ! $SUDO install -m 0600 "$metadata_archive" "${snapshot_dir}/source-metadata.tar" \
        || ! $SUDO install -m 0600 "$checksums_file" "${snapshot_dir}/SHA256SUMS"; then
        fail "Could not publish the private source deploy snapshot."
        $SUDO rm -rf "$snapshot_dir" 2>/dev/null || true
        return 1
    fi

    DATABASE_ROLLBACK_DEPLOY_SNAPSHOT="$snapshot_dir"
    DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="true"
    DATABASE_ROLLBACK_SOURCE_VERSION="$source_version"
    DATABASE_ROLLBACK_SOURCE_METADATA_PATH="$metadata_path"
    DATABASE_ROLLBACK_ACTIVE_DATABASE="$active_database"
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
    if ! database_write_recovery_journal "deploy-mutating"; then
        fail "Could not persist the rollback recovery journal before deploy mutation."
        $SUDO rm -rf "$snapshot_dir"
        DATABASE_ROLLBACK_DEPLOY_SNAPSHOT=""
        DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="false"
        return 1
    fi
    info "Source deploy state snapshotted for rollback failure recovery"
}

database_restore_failed_deploy_staging() {
    local failed_dir="$1"
    local metadata_path="${DATABASE_ROLLBACK_SOURCE_METADATA_PATH:-}"
    if $SUDO test -d "${failed_dir}/docker"; then
        $SUDO rm -rf "${INSTALL_DIR}/docker"
        $SUDO mv "${failed_dir}/docker" "${INSTALL_DIR}/docker"
    fi
    if $SUDO test -f "${failed_dir}/compose-command.sh"; then
        $SUDO rm -f "${INSTALL_DIR}/compose-command.sh"
        $SUDO mv "${failed_dir}/compose-command.sh" "${INSTALL_DIR}/compose-command.sh"
    fi
    if $SUDO test -f "${failed_dir}/.version"; then
        $SUDO rm -f "${INSTALL_DIR}/.version"
        $SUDO mv "${failed_dir}/.version" "${INSTALL_DIR}/.version"
    fi
    if [[ -n "$metadata_path" ]] && $SUDO test -f "${failed_dir}/install.json"; then
        $SUDO rm -f "$metadata_path"
        $SUDO mv "${failed_dir}/install.json" "$metadata_path"
    fi
    if ! $SUDO rm -rf "$failed_dir"; then
        warn "Exact source files were restored, but rollback staging could not be removed."
        return 1
    fi
}

database_restore_source_deploy_state() {
    [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]] || return 0
    local snapshot_dir archive metadata_archive expected metadata_expected actual metadata_actual
    local temp_archive temp_metadata_archive temp_dir metadata_temp_dir failed_dir metadata_path
    snapshot_dir="$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT"
    archive="${snapshot_dir}/source-deploy.tar"
    metadata_archive="${snapshot_dir}/source-metadata.tar"
    metadata_path="$DATABASE_ROLLBACK_SOURCE_METADATA_PATH"

    if ! $SUDO test -d "$snapshot_dir" || ! $SUDO test -s "$archive" \
        || ! $SUDO test -s "$metadata_archive" \
        || ! $SUDO test -s "${snapshot_dir}/SHA256SUMS" \
        || $SUDO test -L "$snapshot_dir" || $SUDO test -L "$archive" \
        || $SUDO test -L "$metadata_archive"; then
        warn "Source deploy snapshot is absent or unsafe; refusing partial file recovery."
        return 1
    fi
    # shellcheck disable=SC2016  # Awk fields are intentionally single-quoted.
    expected=$($SUDO awk '$2 == "source-deploy.tar" {print $1}' \
        "${snapshot_dir}/SHA256SUMS")
    # shellcheck disable=SC2016  # Awk fields are intentionally single-quoted.
    metadata_expected=$($SUDO awk '$2 == "source-metadata.tar" {print $1}' \
        "${snapshot_dir}/SHA256SUMS")
    [[ "$expected" =~ ^[0-9a-f]{64}$ \
        && "$metadata_expected" =~ ^[0-9a-f]{64}$ ]] || return 1
    temp_archive=$(mktemp) || return 1
    temp_metadata_archive=$(mktemp) || return 1
    CLEANUP_FILES+=("$temp_archive" "$temp_metadata_archive")
    if ! $SUDO cat "$archive" > "$temp_archive" \
        || ! $SUDO cat "$metadata_archive" > "$temp_metadata_archive" \
        || ! actual=$(sha256_file "$temp_archive") \
        || ! metadata_actual=$(sha256_file "$temp_metadata_archive"); then
        warn "Source deploy snapshot could not be read and checksummed."
        return 1
    fi
    if [[ "$actual" != "$expected" || "$metadata_actual" != "$metadata_expected" ]]; then
        warn "Source deploy snapshot checksum mismatch; refusing partial file recovery."
        return 1
    fi

    temp_dir=$(mktemp -d) || return 1
    metadata_temp_dir=$(mktemp -d) || return 1
    CLEANUP_FILES+=("$temp_dir" "$metadata_temp_dir")
    if ! $SUDO tar -xpf "$temp_archive" -C "$temp_dir" \
        || ! $SUDO tar -xpf "$temp_metadata_archive" -C "$metadata_temp_dir" \
        || ! $SUDO test -d "${temp_dir}/docker" \
        || ! $SUDO test -f "${temp_dir}/compose-command.sh" \
        || $SUDO test -L "${temp_dir}/compose-command.sh" \
        || ! $SUDO test -x "${temp_dir}/compose-command.sh" \
        || ! $SUDO test -f "${metadata_temp_dir}/install.json" \
        || $SUDO test -L "${metadata_temp_dir}/install.json"; then
        warn "Source deploy snapshot extraction failed."
        return 1
    fi

    # Stop through the still-current command before replacing its files. A
    # partially written target deploy may not have a usable command; recovery
    # still proceeds from the archived source copy in that case.
    if $SUDO test -x "${INSTALL_DIR}/compose-command.sh"; then
        $SUDO "${INSTALL_DIR}/compose-command.sh" stop proxy >> "$LOG_FILE" 2>&1 || true
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="true"
    failed_dir="${INSTALL_DIR}/.rollback-failed-deploy-$$"
    if $SUDO test -e "$failed_dir"; then
        warn "Rollback deploy recovery staging path already exists."
        return 1
    fi
    if ! $SUDO install -d -m 0700 "$failed_dir"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "${INSTALL_DIR}/docker" \
        && ! $SUDO mv "${INSTALL_DIR}/docker" "${failed_dir}/docker"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "${INSTALL_DIR}/compose-command.sh" \
        && ! $SUDO mv "${INSTALL_DIR}/compose-command.sh" \
            "${failed_dir}/compose-command.sh"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -f "${INSTALL_DIR}/.version" \
        && ! $SUDO mv "${INSTALL_DIR}/.version" "${failed_dir}/.version"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "$metadata_path" \
        && ! $SUDO mv "$metadata_path" "${failed_dir}/install.json"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if ! $SUDO mv "${temp_dir}/docker" "${INSTALL_DIR}/docker" \
        || ! $SUDO mv "${temp_dir}/compose-command.sh" \
            "${INSTALL_DIR}/compose-command.sh"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -f "${temp_dir}/.version"; then
        if ! $SUDO mv "${temp_dir}/.version" "${INSTALL_DIR}/.version"; then
            database_restore_failed_deploy_staging "$failed_dir" || true
            return 1
        fi
    else
        if ! $SUDO rm -f "${INSTALL_DIR}/.version"; then
            database_restore_failed_deploy_staging "$failed_dir" || true
            return 1
        fi
    fi
    if ! $SUDO mv "${metadata_temp_dir}/install.json" "$metadata_path"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if ! $SUDO rm -rf "$failed_dir"; then
        warn "Exact source files were restored, but rollback staging could not be removed."
        return 1
    fi

    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" up -d >> "$LOG_FILE" 2>&1; then
        warn "Exact source deploy state was restored, but its full stack did not restart."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="false"
    if ! database_wait_for_source_stack_healthy; then
        warn "Exact source deploy stack restarted but did not become healthy; durable recovery state is retained."
        return 1
    fi
    if ! database_discard_source_deploy_snapshot; then
        warn "Exact source recovery completed, but its durable snapshot cleanup did not finish."
        return 1
    fi
    info "Exact source deploy state restored after rollback failure"
}

database_discard_source_deploy_snapshot() {
    [[ -n "${DATABASE_ROLLBACK_DEPLOY_SNAPSHOT:-}" ]] || return 0
    # Persist the no-reversal boundary before deleting the only source
    # snapshot. A process loss after this phase can finish cleanup
    # idempotently; it must never interpret an absent snapshot as a reason to
    # reverse an already healthy target.
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" != "target-healthy" ]] \
        && ! database_write_recovery_journal "target-healthy"; then
        return 1
    fi
    if $SUDO test -e "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT" \
        && ! $SUDO rm -rf "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT"; then
        return 1
    fi
    if ! database_clear_recovery_journal; then
        return 1
    fi
    DATABASE_ROLLBACK_DEPLOY_SNAPSHOT=""
    DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="false"
    DATABASE_ROLLBACK_SOURCE_METADATA_PATH=""
    DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE="false"
}

# Read and validate the database identifier from the installer-managed .env.
# Identifiers are deliberately restricted before they can reach psql variables.
database_install_identifier() {
    local value
    value=$(existing_env_value "POSTGRES_DB")
    value="${value:-llm_proxy}"
    [[ "$value" =~ ^[A-Za-z_][A-Za-z0-9_]{0,62}$ ]] \
        || die "POSTGRES_DB is not a safe PostgreSQL identifier for installer-managed recovery."
    printf '%s\n' "$value"
}

database_query_migration_version() {
    local database="$1"
    local version
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    version=$($SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname="$1" --no-align --tuples-only --set=ON_ERROR_STOP=1 --command="SELECT COALESCE(MAX(version), 0) FROM _sqlx_migrations"' \
        sh "$database" 2>> "$LOG_FILE") || return 1
    version=$(printf '%s' "$version" | tr -d '[:space:]')
    [[ "$version" =~ ^[0-9]+$ ]] || return 1
    printf '%s\n' "$version"
}

database_quiesce_proxy() {
    [[ "$DATABASE_ROLLBACK_PROXY_STOPPED" != "true" ]] || return 0
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" stop proxy >> "$LOG_FILE" 2>&1; then
        fail "Could not stop the proxy before the database recovery snapshot."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="true"
    info "Proxy quiesced for a consistent database recovery point"
}

database_resume_proxy() {
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]]; then
        warn "Refusing to start a target deploy while exact source-state recovery is incomplete."
        return 1
    fi
    [[ "${DATABASE_ROLLBACK_PROXY_STOPPED:-false}" == "true" ]] || return 0
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" start proxy >> "$LOG_FILE" 2>&1; then
        warn "Could not resume the quiesced proxy; rerun the verified installer."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="false"
    info "Prior proxy resumed"
}

database_remove_quiesced_proxy_container() {
    [[ "${DATABASE_ROLLBACK_PROXY_STOPPED:-false}" == "true" ]] || return 1
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" rm -f -s proxy \
        >> "$LOG_FILE" 2>&1; then
        fail "Could not remove the quiesced source proxy before database rollback."
        return 1
    fi
    info "Quiesced source proxy container removed before database swap"
}

database_create_version_backup() {
    local source_version="$1"
    local target_version="$2"
    local purpose="$3"
    local database timestamp backup_id rollback_root final_dir staging_dir
    local temp_dir dump_file manifest_file migration_version checksum

    if ! is_stable_semver "$source_version" \
        || ! is_stable_semver "$target_version" \
        || [[ "$purpose" != "pre-upgrade" && "$purpose" != "pre-rollback" ]]; then
        database_abort_rollback || true
        return 1
    fi

    if ! database=$(database_install_identifier); then
        database_abort_rollback || true
        return 1
    fi
    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    backup_id="${purpose}-${source_version}-to-${target_version}-${timestamp}"
    database_backup_id_is_safe "$backup_id" || return 1

    temp_dir=$(mktemp -d) || {
        database_abort_rollback || true
        return 1
    }
    CLEANUP_FILES+=("$temp_dir")
    dump_file="$temp_dir/database.dump"
    manifest_file="$temp_dir/manifest.json"

    if ! database_quiesce_proxy; then
        database_abort_rollback || true
        return 1
    fi
    if ! migration_version=$(database_query_migration_version "$database"); then
        fail "Could not read the current migration version before database backup."
        database_abort_rollback || true
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec pg_dump --format=custom --no-owner --no-acl --username="$POSTGRES_USER" --dbname="$POSTGRES_DB"' \
        > "$dump_file" 2>> "$LOG_FILE"; then
        fail "PostgreSQL recovery dump failed; the active database was not changed."
        database_abort_rollback || true
        return 1
    fi
    if [[ ! -s "$dump_file" ]]; then
        fail "PostgreSQL recovery dump is empty; the active database was not changed."
        database_abort_rollback || true
        return 1
    fi
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec pg_restore --list' < "$dump_file" >> "$LOG_FILE" 2>&1; then
        fail "PostgreSQL recovery dump failed archive validation."
        database_abort_rollback || true
        return 1
    fi

    checksum=$(sha256_file "$dump_file") || {
        database_abort_rollback || true
        return 1
    }
    jq -n \
        --arg backup_id "$backup_id" \
        --arg source_version "$source_version" \
        --arg target_version "$target_version" \
        --arg database "$database" \
        --arg migration_version "$migration_version" \
        --arg created_at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        --arg sha256 "$checksum" \
        '{format_version: 1, backup_id: $backup_id,
          source_version: $source_version, target_version: $target_version,
          database: $database, migration_version: $migration_version,
          created_at: $created_at, dump_file: "database.dump", sha256: $sha256}' \
        > "$manifest_file" || {
            database_abort_rollback || true
            return 1
        }

    rollback_root="${METADATA_DIR}/database-rollback"
    final_dir="${rollback_root}/${backup_id}"
    staging_dir="${rollback_root}/.partial-${backup_id}-$$"
    if $SUDO test -e "$final_dir" || $SUDO test -e "$staging_dir"; then
        fail "Database recovery backup ID collision: ${backup_id}"
        database_abort_rollback || true
        return 1
    fi
    if ! $SUDO install -d -m 0700 "$rollback_root" "$staging_dir" \
        || ! $SUDO install -m 0600 "$dump_file" "${staging_dir}/database.dump" \
        || ! $SUDO install -m 0600 "$manifest_file" "${staging_dir}/manifest.json" \
        || ! $SUDO mv "$staging_dir" "$final_dir"; then
        fail "Could not publish the private database recovery backup."
        $SUDO rm -rf "$staging_dir" 2>/dev/null || true
        database_abort_rollback || true
        return 1
    fi

    CREATED_DATABASE_BACKUP_ID="$backup_id"
    info "Database recovery backup created: ${backup_id}"
}

database_validate_rollback_backup() {
    local backup_id="$1"
    local requested_version="$2"
    local installed_version="$3"
    local backup_dir manifest dump expected_checksum actual_checksum temp_dump

    if ! database_backup_id_is_safe "$backup_id"; then
        fail "Rollback backup ID is invalid."
        return 1
    fi
    backup_dir="${METADATA_DIR}/database-rollback/${backup_id}"
    manifest="${backup_dir}/manifest.json"
    dump="${backup_dir}/database.dump"
    if ! $SUDO test -d "$backup_dir" || ! $SUDO test -s "$manifest" || ! $SUDO test -s "$dump"; then
        fail "Rollback backup not found or incomplete: ${backup_id}"
        return 1
    fi
    if $SUDO test -L "$backup_dir" || $SUDO test -L "$manifest" || $SUDO test -L "$dump"; then
        fail "Rollback backup contains a symbolic link and is rejected."
        return 1
    fi
    # shellcheck disable=SC2016  # jq variables are intentionally single-quoted.
    if ! $SUDO jq -e \
        --arg backup_id "$backup_id" \
        --arg requested "$requested_version" \
        --arg installed "$installed_version" \
        '.format_version == 1 and .backup_id == $backup_id and
         .source_version == $requested and
         .target_version == $installed and
         (.database | type == "string" and test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
         (.migration_version | type == "string" and test("^[0-9]+$")) and
         .dump_file == "database.dump" and
         (.sha256 | type == "string" and test("^[0-9a-f]{64}$"))' \
        "$manifest" >/dev/null; then
        fail "Rollback backup manifest does not match the requested recovery transition."
        return 1
    fi
    temp_dump=$(mktemp)
    CLEANUP_FILES+=("$temp_dump")
    if ! $SUDO cat "$dump" > "$temp_dump"; then
        fail "Rollback backup could not be read."
        return 1
    fi
    expected_checksum=$($SUDO jq -r '.sha256' "$manifest")
    actual_checksum=$(sha256_file "$temp_dump")
    if [[ "$actual_checksum" != "$expected_checksum" ]]; then
        fail "Rollback backup checksum mismatch; the active database was not changed."
        return 1
    fi
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec pg_restore --list' < "$temp_dump" >> "$LOG_FILE" 2>&1; then
        fail "Rollback backup archive validation failed; the active database was not changed."
        return 1
    fi

    VALIDATED_DATABASE_BACKUP_DUMP="$dump"
    VALIDATED_DATABASE_BACKUP_MIGRATION=$($SUDO jq -r '.migration_version' "$manifest")
    DATABASE_ROLLBACK_ACTIVE_DATABASE=$($SUDO jq -r '.database' "$manifest")
    info "Rollback backup validated: ${backup_id}"
}

database_swap_sql() {
    local active_database="$1"
    local replacement_database="$2"
    local safety_database="$3"
    local sql_file
    sql_file=$(mktemp) || return 1
    CLEANUP_FILES+=("$sql_file")
    if ! cat > "$sql_file" <<'SQL'
\set ON_ERROR_STOP on
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname IN (:'active_database', :'replacement_database')
  AND pid <> pg_backend_pid();
SELECT format('ALTER DATABASE %I RENAME TO %I', :'active_database', :'safety_database') \gexec
SELECT format('ALTER DATABASE %I RENAME TO %I', :'replacement_database', :'active_database') \gexec
SQL
    then
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="active_database=${active_database}" \
        --set="replacement_database=${replacement_database}" \
        --set="safety_database=${safety_database}" \
        < "$sql_file" >> "$LOG_FILE" 2>&1
}

database_drop_replacement_database() {
    local replacement_database="${DATABASE_ROLLBACK_REPLACEMENT_DATABASE:-}"
    [[ -n "$replacement_database" ]] || return 0
    if ! database_recovery_identifier_is_safe "$replacement_database"; then
        warn "Refusing to drop an unsafe rollback replacement database identifier."
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec dropdb --if-exists --force --username="$POSTGRES_USER" "$1"' \
        sh "$replacement_database" >> "$LOG_FILE" 2>&1; then
        warn "Could not remove the installer-managed rollback replacement database."
        return 1
    fi
    info "Rollback replacement database removed"
}

database_run_timescaledb_restore_lifecycle() {
    local database="$1"
    local lifecycle_stage="$2"
    local statement
    database_recovery_identifier_is_safe "$database" || return 1
    case "$lifecycle_stage" in
        create-extension)
            statement='CREATE EXTENSION IF NOT EXISTS timescaledb;'
            ;;
        pre-restore)
            statement='SELECT timescaledb_pre_restore();'
            ;;
        post-restore)
            statement='SELECT timescaledb_post_restore();'
            ;;
        *)
            return 1
            ;;
    esac
    # The database identifier is a validated positional argument, never SQL.
    # POSTGRES_USER expands only inside the configured database container.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname="$1" --set=ON_ERROR_STOP=1 --command="$2"' \
        sh "$database" "$statement" >> "$LOG_FILE" 2>&1
}

database_stage_validated_backup_for_swap() {
    local operation_label="$1"
    local replacement_prefix="$2"
    local safety_prefix="$3"
    local timestamp restored_migration temp_dump

    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE="${replacement_prefix}_${timestamp}_$$"
    DATABASE_ROLLBACK_SAFETY_DATABASE="${safety_prefix}_${timestamp}_$$"
    if ! database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" \
        || ! database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE"; then
        fail "${operation_label} database staging identity is unsafe."
        database_abort_rollback || true
        return 1
    fi
    if ! database_write_recovery_journal "staging"; then
        fail "Could not persist ${operation_label} database staging identity."
        database_abort_rollback || true
        return 1
    fi

    # Restore into an isolated database. The active database remains unchanged
    # until the dump and its migration identity have both been verified.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'dropdb --if-exists --force --username="$POSTGRES_USER" "$1"; createdb --username="$POSTGRES_USER" --owner="$POSTGRES_USER" "$1"' \
        sh "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" >> "$LOG_FILE" 2>&1; then
        fail "Could not create the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "create-extension"; then
        fail "Could not enable TimescaleDB in the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "pre-restore"; then
        fail "Could not enter TimescaleDB pre-restore mode in the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi

    temp_dump=$(mktemp) || {
        database_abort_rollback || true
        return 1
    }
    CLEANUP_FILES+=("$temp_dump")
    if ! $SUDO cat "$VALIDATED_DATABASE_BACKUP_DUMP" > "$temp_dump"; then
        database_abort_rollback || true
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec pg_restore --exit-on-error --single-transaction --no-owner --no-acl --username="$POSTGRES_USER" --dbname="$1"' \
        sh "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" < "$temp_dump" >> "$LOG_FILE" 2>&1; then
        fail "${operation_label} restore failed in the isolated staging database; the active database was not changed."
        database_abort_rollback || true
        return 1
    fi
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "post-restore"; then
        fail "Could not leave TimescaleDB restore mode in the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi
    if ! restored_migration=$(database_query_migration_version "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE") \
        || [[ "$restored_migration" != "$VALIDATED_DATABASE_BACKUP_MIGRATION" ]]; then
        fail "${operation_label} staging database migration history does not match its immutable manifest."
        database_abort_rollback || true
        return 1
    fi

    if ! database_remove_quiesced_proxy_container; then
        database_abort_rollback || true
        return 1
    fi

    if ! database_write_recovery_journal "swap-active"; then
        fail "Could not persist ${operation_label} database swap identity before mutation."
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="true"
    if ! database_swap_sql "$DATABASE_ROLLBACK_ACTIVE_DATABASE" \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "$DATABASE_ROLLBACK_SAFETY_DATABASE"; then
        fail "${operation_label} database-name swap failed; attempting automatic recovery."
        database_recover_interrupted_rollback || true
        return 1
    fi
    info "${operation_label} database restored and verified at migration ${restored_migration}"
}

database_restore_version_backup() {
    local installed_version="$1"
    local requested_version="$2"
    local backup_id="$3"

    if ! database_validate_rollback_backup "$backup_id" "$requested_version" "$installed_version"; then
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SOURCE_VERSION="$installed_version"
    database_create_version_backup "$installed_version" "$requested_version" "pre-rollback" \
        || return 1
    database_stage_validated_backup_for_swap \
        "Rollback" "llap_restore" "llap_pre_rollback"
}

database_prepare_forward_upgrade() {
    local source_version="$1"
    local target_version="$2"
    local backup_id="$3"

    if ! database_validate_rollback_backup "$backup_id" "$source_version" "$target_version"; then
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SOURCE_VERSION="$source_version"
    if ! database_stage_validated_backup_for_swap \
        "Forward upgrade" "llap_upgrade" "llap_pre_upgrade"; then
        return 1
    fi
    DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE="true"
}

database_recover_interrupted_rollback() {
    [[ "${DATABASE_ROLLBACK_SWAP_ACTIVE:-false}" == "true" ]] || return 0
    local failed_database sql_file
    failed_database="${DATABASE_ROLLBACK_REPLACEMENT_DATABASE:-llap_failed_rollback_$$}"
    $SUDO "${INSTALL_DIR}/compose-command.sh" stop proxy >> "$LOG_FILE" 2>&1 || true
    DATABASE_ROLLBACK_PROXY_STOPPED="true"

    sql_file=$(mktemp) || return 1
    CLEANUP_FILES+=("$sql_file")
    if ! cat > "$sql_file" <<'SQL'
\set ON_ERROR_STOP on
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname = :'active_database' AND pid <> pg_backend_pid();
SELECT format('ALTER DATABASE %I RENAME TO %I', :'active_database', :'failed_database')
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'safety_database')
  AND EXISTS (SELECT 1 FROM pg_database WHERE datname = :'active_database')
  AND NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'failed_database') \gexec
SELECT format('ALTER DATABASE %I RENAME TO %I', :'safety_database', :'active_database')
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'safety_database')
  AND NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'active_database') \gexec
SQL
    then
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="active_database=${DATABASE_ROLLBACK_ACTIVE_DATABASE}" \
        --set="failed_database=${failed_database}" \
        --set="safety_database=${DATABASE_ROLLBACK_SAFETY_DATABASE}" \
        < "$sql_file" >> "$LOG_FILE" 2>&1; then
        warn "Automatic interrupted-rollback database recovery failed; preserved backups require operator escalation."
        return 1
    fi
    if ! database_drop_replacement_database; then
        return 1
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
    DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE="false"
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]] \
        && ! database_write_recovery_journal "deploy-mutating"; then
        warn "Database swap was reversed, but durable source-state recovery could not be updated."
        return 1
    fi
    info "Interrupted rollback database swap was reversed"
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]]; then
        database_restore_source_deploy_state
    else
        database_resume_proxy
    fi
}

database_drop_forward_upgrade_safety_database() {
    local safety_database="${DATABASE_ROLLBACK_SAFETY_DATABASE:-}"
    [[ -n "$safety_database" ]] || return 0
    if ! database_recovery_identifier_is_safe "$safety_database"; then
        warn "Refusing to drop an unsafe forward-upgrade safety database identifier."
        return 1
    fi
    # The target has crossed a durable no-reversal boundary before this call.
    # `--if-exists` makes process-loss recovery idempotent when PostgreSQL
    # completed the drop before the installer recorded its local result.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" exec -T timescaledb \
        sh -ceu 'exec dropdb --if-exists --force --username="$POSTGRES_USER" "$1"' \
        sh "$safety_database" >> "$LOG_FILE" 2>&1; then
        warn "Could not remove the forward-upgrade source safety database."
        return 1
    fi
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
    info "Forward-upgrade source safety database removed after target health"
}

database_complete_forward_upgrade_transition() {
    # Persist the no-reversal boundary while both the exact source database and
    # source deploy snapshot still exist. A process loss from this point keeps
    # the proven-healthy target and resumes only idempotent cleanup.
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" != "forward-target-healthy" ]] \
        && ! database_write_recovery_journal "forward-target-healthy"; then
        return 1
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE="false"
    if ! database_drop_forward_upgrade_safety_database; then
        return 1
    fi
    database_discard_source_deploy_snapshot
}

database_abort_rollback() {
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == "forward-target-healthy" ]]; then
        database_complete_forward_upgrade_transition
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == "target-healthy" ]]; then
        database_discard_source_deploy_snapshot
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_SWAP_ACTIVE:-false}" == "true" ]]; then
        database_recover_interrupted_rollback
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]]; then
        if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == "staging" ]] \
            && ! database_drop_replacement_database; then
            return 1
        fi
        database_restore_source_deploy_state
        return $?
    fi
    database_resume_proxy
}

database_reconcile_pending_recovery() {
    if ! database_load_recovery_journal; then
        return 1
    fi
    if [[ "$DATABASE_ROLLBACK_RECOVERY_PHASE" == "target-healthy" ]]; then
        if ! database_discard_source_deploy_snapshot; then
            fail "Pending healthy-target cleanup could not be completed safely."
            return 1
        fi
        info "Pending healthy-target snapshot cleanup completed"
        return 0
    fi
    if ! database_abort_rollback; then
        fail "Pending interrupted database rollback could not be recovered safely."
        return 1
    fi
    info "Pending interrupted database rollback recovered to exact source state"
}

# Pending durable recovery must run before target argument/configuration
# validation. The target install metadata may already have been finalized when
# a process or host stops, and validating the repeated rollback command against
# that transient metadata would otherwise make source recovery unreachable.
database_reconcile_pending_recovery_before_configuration() {
    local recovery_journal
    recovery_journal=$(database_recovery_journal_path)
    if ! $SUDO test -e "$recovery_journal"; then
        return 0
    fi
    if ! database_reconcile_pending_recovery; then
        return 1
    fi
    fail "Reconciled pending durable recovery state. Re-run this verified installer to begin a new deployment."
    return 1
}

database_wait_for_services_healthy() {
    local timeout="${DATABASE_ROLLBACK_HEALTH_TIMEOUT_SECONDS:-120}"
    [[ "$timeout" =~ ^[0-9]+$ ]] && (( timeout > 0 && timeout <= 600 )) || timeout=120
    local started container_id status service all_healthy
    local -a services=("$@")
    [[ ${#services[@]} -gt 0 ]] || return 1
    started=$(date +%s)
    while (( $(date +%s) - started < timeout )); do
        all_healthy="true"
        for service in "${services[@]}"; do
            container_id=$($SUDO "${INSTALL_DIR}/compose-command.sh" ps -q "$service" 2>/dev/null || true)
            status=""
            if [[ -n "$container_id" ]]; then
                status=$($SUDO docker inspect --format='{{if .State.Health}}{{.State.Health.Status}}{{else}}{{.State.Status}}{{end}}' \
                    "$container_id" 2>/dev/null || true)
            fi
            [[ "$status" == "exited" || "$status" == "dead" ]] && return 1
            [[ "$status" == "healthy" ]] || all_healthy="false"
        done
        [[ "$all_healthy" == "true" ]] && return 0
        sleep 2
    done
    return 1
}

database_wait_for_proxy_healthy() {
    database_wait_for_services_healthy proxy
}

database_wait_for_source_stack_healthy() {
    database_wait_for_services_healthy timescaledb consul proxy
}

database_wait_for_target_stack_healthy() {
    database_wait_for_services_healthy timescaledb consul proxy
}

database_source_snapshot_required_for_deploy() {
    [[ "$COMMAND" == "upgrade" ]] || return 1
    local installed_version
    installed_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$installed_version" || return 1
    is_stable_semver "$OPT_VERSION" || return 1
    [[ -n "$OPT_ROLLBACK_BACKUP_ID" ]] \
        || stable_semver_gt "$OPT_VERSION" "$installed_version"
}

deploy_handle_database_transition() {
    [[ "$COMMAND" == "upgrade" ]] || return 0
    local installed_version
    installed_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$installed_version" || return 0
    is_stable_semver "$OPT_VERSION" || return 0

    if [[ -n "$OPT_ROLLBACK_BACKUP_ID" ]]; then
        database_restore_version_backup "$installed_version" "$OPT_VERSION" \
            "$OPT_ROLLBACK_BACKUP_ID"
    elif stable_semver_gt "$OPT_VERSION" "$installed_version"; then
        database_create_version_backup "$installed_version" "$OPT_VERSION" "pre-upgrade" \
            || return 1
        database_prepare_forward_upgrade "$installed_version" "$OPT_VERSION" \
            "$CREATED_DATABASE_BACKUP_ID" || return 1
        info "Retain rollback backup ID: ${CREATED_DATABASE_BACKUP_ID}"
    elif stable_semver_gt "$installed_version" "$OPT_VERSION"; then
        fail "Database rollback backup is required before starting an older binary."
        return 1
    fi
}

deploy_complete_database_transition() {
    if [[ "$DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED" == "true" ]]; then
        # Compose has started the recovered proxy, so it is no longer quiesced.
        # Keep source recovery available until the complete target stack proves
        # healthy after every fallible deploy finalizer.
        DATABASE_ROLLBACK_PROXY_STOPPED="false"
        if ! database_wait_for_target_stack_healthy; then
            fail "Target stack did not become healthy; restoring the exact source deployment."
            database_abort_rollback || true
            return 1
        fi
        info "Target database, Consul, and proxy are healthy"
        if [[ "$DATABASE_FORWARD_UPGRADE_SWAP_ACTIVE" == "true" ]]; then
            if ! database_complete_forward_upgrade_transition; then
                fail "Target stack is healthy, but durable forward-upgrade cleanup could not be completed."
                return 1
            fi
        elif ! database_discard_source_deploy_snapshot; then
            fail "Target stack is healthy, but durable recovery cleanup could not be completed."
            return 1
        fi
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    DATABASE_ROLLBACK_PROXY_STOPPED="false"
}

# Determine the expected filesystem type ("file" or "dir") of a compose
# bind-mount SOURCE path. Pure function — derives the answer from the path's
# final segment: a segment containing a dot (e.g. default.conf, prometheus.yml)
# is a file mount; a segment with no extension (e.g. traefik-dynamic, rules,
# provisioning) is a directory mount. This matches every bind-mount source
# declared across docker-compose.yml and its overlays today.
#
# LIMITATION: the heuristic would misclassify an extensionless config FILE
# (e.g. Caddyfile) or a dotted DIRECTORY (e.g. conf.d). If such a source is ever
# added to a compose overlay, extend this function with an explicit override
# list and update the manifest-coverage test accordingly.
# Echoes "file" or "dir".
bind_mount_expected_type() {
    local src="$1"
    local base="${src##*/}"
    if [[ "$base" == *.* ]]; then
        echo "file"
    else
        echo "dir"
    fi
}

# Extract bind-mount SOURCE paths (the `./...` host paths) from the compose
# overlays that are actually active for this deployment. Echoes one relative
# source path per line (with the leading `./` stripped), de-duplicated.
# Reads the compose files already extracted under ${INSTALL_DIR}/docker.
collect_active_bind_mount_sources() {
    local -a overlays=("docker-compose.yml" "docker-compose.hardened.yml")
    [[ "$OPT_WAF" == "true" ]] && overlays+=("docker-compose.waf.yml")
    [[ "$OPT_TLS" == "true" ]] && overlays+=("docker-compose.tls.yml")
    [[ "$OPT_MONITORING" == "true" ]] && overlays+=("docker-compose.monitoring.yml")
    [[ "$OPT_BACKUP" == "true" ]] && overlays+=("docker-compose.backup.yml")
    $SUDO test -f "${INSTALL_DIR}/docker/docker-compose.dns.yml" \
        && overlays+=("docker-compose.dns.yml")
    if [[ "$IS_MACOS" == "true" ]] && [[ "$MACOS_HOST_NETWORKING" == "true" ]]; then
        :
    elif [[ "$IS_MACOS" == "true" ]] || [[ "$OPT_MDNS" != "true" ]]; then
        overlays+=("docker-compose.no-mdns.yml")
    fi
    [[ "$OPT_DEBUG" == "true" ]] && overlays+=("docker-compose.debug.yml")

    local overlay path
    for overlay in "${overlays[@]}"; do
        path="${INSTALL_DIR}/docker/${overlay}"
        $SUDO test -f "$path" || continue
        # Match `- ./SRC:/container/path[:opts]` bind-mount lines and emit SRC
        # with the leading `./` removed. Named volumes (no leading `./`) and
        # absolute host paths are intentionally skipped.
        #
        # `|| true` is REQUIRED: grep exits 1 when a compose file declares no
        # `./` bind mounts (e.g. docker-compose.hardened.yml, always active).
        # Under the installer's `set -euo pipefail` that non-match would abort
        # the whole run before the preflight could report anything. The bats
        # suite sources with --source-only (no strict mode) so it would not
        # catch this — see bind_mount_preflight.bats strict-mode case.
        { $SUDO grep -oE '^\s*-\s*\./[^:]+' "$path" || true; } \
            | sed -E 's/^\s*-\s*\.\///'
    done | sort -u
}

# Defensive preflight: BEFORE `compose up`, verify every active bind-mount
# SOURCE path exists on the host as the correct type. This is the permanent fix
# for #1390: when a file-type bind-mount source is absent, Docker auto-creates a
# DIRECTORY at the mount path and `compose up` aborts mid-deploy ("not a
# directory"), which took prod ingress DOWN on the v0.0.87 upgrade.
#
# Runs AFTER deploy_extract_files (so every embedded config is on disk) and
# BEFORE any container is started, so a missing/mistyped mount fails the deploy
# cleanly instead of part-way through bringing the stack up.
#
# Behaviour per source:
#   - file expected, file present       -> OK
#   - dir  expected, dir  present       -> OK
#   - dir  expected, missing            -> create it (directory mounts, e.g.
#                                          traefik-dynamic, are allowed to be
#                                          empty; Docker would create them anyway)
#   - dir  expected, file present       -> FAIL (clearly wrong)
#   - file expected, missing            -> FAIL (extract should have created it)
#   - file expected, directory present  -> remove the stray (empty) dir if it is
#                                          empty, else FAIL — never let Docker
#                                          mount a dir onto a file path
deploy_verify_bind_mounts() {
    step "  Verifying bind-mount sources..."
    local docker_dir="${INSTALL_DIR}/docker"
    local -a problems=()
    local src abs expected

    while IFS= read -r src; do
        [[ -z "$src" ]] && continue
        abs="${docker_dir}/${src}"
        expected="$(bind_mount_expected_type "$src")"

        if [[ "$expected" == "dir" ]]; then
            if $SUDO test -f "$abs"; then
                problems+=("expected DIRECTORY but found a file: docker/${src}")
            elif ! $SUDO test -d "$abs"; then
                # Directory mounts may legitimately be empty; create it so
                # Docker mounts a real dir rather than failing.
                $SUDO mkdir -p "$abs"
                info "Created missing bind-mount directory: docker/${src}"
            fi
            continue
        fi

        # expected == "file"
        if $SUDO test -f "$abs"; then
            continue
        fi
        if $SUDO test -d "$abs"; then
            # The exact #1390 failure mode: a (usually empty) directory sitting
            # where a config FILE must be — left behind by a prior failed
            # `compose up`. Remove it only if empty, then report it missing so
            # the operator knows extraction did not produce the file.
            if $SUDO rmdir "$abs" 2>/dev/null; then
                problems+=("config file missing (removed stray empty directory): docker/${src}")
            else
                problems+=("expected FILE but found a non-empty directory: docker/${src}")
            fi
            continue
        fi
        problems+=("config file missing: docker/${src}")
    done < <(collect_active_bind_mount_sources)

    if [[ ${#problems[@]} -gt 0 ]]; then
        local -a box_lines=(
            ""
            "One or more docker-compose bind-mount sources are missing or"
            "have the wrong type. Starting the stack now would let Docker"
            "auto-create a directory at a config-file mount path and abort"
            "\`compose up\` mid-deploy (this took prod ingress down — #1390)."
            ""
            "Problems:"
        )
        for src in "${problems[@]}"; do
            box_lines+=("  - ${src}")
        done
        box_lines+=(
            ""
            "Re-run install.sh to re-extract the embedded config files."
            ""
            "Full log: ${LOG_FILE}"
        )
        draw_box "FAILED: bind-mount preflight" "${box_lines[@]}"
        die "Aborting before touching the running stack — bind-mount sources are invalid (#1390)"
    fi

    info "All bind-mount sources present and correctly typed"
}

deploy_start_stack() {
    step "  Starting services..."
    # docker-compose.backup.yml declares proxy_ca_data as external:true.
    # Docker Compose validates all declared volumes before starting any
    # containers. Create the volume idempotently so compose up never fails
    # with "external volume not found" on the first install or after a purge.
    $SUDO docker volume create proxy_ca_data >> "$LOG_FILE" 2>&1 || true
    info "proxy_ca_data volume ready"

    # Start only the infrastructure services first. consul-init requires a
    # Consul ACL token which doesn't exist until deploy_consul_acl_bootstrap()
    # runs. Starting the full stack here would cause consul-init to exit 1
    # (no token) and abort compose up. The full stack is brought up after
    # ACL bootstrap in deploy_start_remaining_services().
    local -a bootstrap_services=("timescaledb" "consul")
    [[ "$OPT_MONITORING" == "true" ]] && bootstrap_services+=("prometheus" "grafana")
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" up -d "${bootstrap_services[@]}" >> "$LOG_FILE" 2>&1; then
        draw_box "FAILED: Start infrastructure services" \
            "" \
            "Docker Compose failed while starting:" \
            "  ${bootstrap_services[*]}" \
            "" \
            "Retry command:" \
            "  ${INSTALL_DIR}/compose-command.sh up -d ${bootstrap_services[*]}" \
            "" \
            "Check logs:" \
            "  ${INSTALL_DIR}/compose-command.sh logs ${bootstrap_services[0]}" \
            "  tail -n 80 ${LOG_FILE}" \
            "" \
            "Full log: ${LOG_FILE}"
        exit 1
    fi

    local timeout=120
    local start_time
    start_time=$(date +%s)

    for svc in "${bootstrap_services[@]}"; do
        local status="starting"
        while [[ "$status" != "healthy" ]]; do
            status=$($SUDO docker inspect --format='{{.State.Health.Status}}' \
                "$($SUDO "${INSTALL_DIR}/compose-command.sh" ps -q "$svc" 2>/dev/null || true)" \
                2>/dev/null || echo "starting")

            local elapsed=$(( $(date +%s) - start_time ))
            if [[ $elapsed -ge $timeout ]]; then
                draw_box "FAILED: Health check timeout" \
                    "" \
                    "Service '${svc}' did not become healthy in ${timeout}s." \
                    "" \
                    "Check logs:" \
                    "  ${INSTALL_DIR}/compose-command.sh logs ${svc}" \
                    "" \
                    "Full log: ${LOG_FILE}"
                exit 1
            fi
            sleep 2
        done
        info "${svc} healthy"
    done
    info "Infrastructure services running"
}

deploy_start_remaining_services() {
    step "  Starting remaining services..."
    # Bring up the full stack now that Consul ACL tokens are in .env.
    # consul-init will succeed this time because CONSUL_HTTP_TOKEN is set.
    if ! $SUDO "${INSTALL_DIR}/compose-command.sh" up -d >> "$LOG_FILE" 2>&1; then
        draw_box "FAILED: Start remaining services" \
            "" \
            "Docker Compose failed while starting the full stack." \
            "" \
            "Retry command:" \
            "  ${INSTALL_DIR}/compose-command.sh up -d" \
            "" \
            "Check logs:" \
            "  ${INSTALL_DIR}/compose-command.sh logs" \
            "  tail -n 80 ${LOG_FILE}" \
            "" \
            "Full log: ${LOG_FILE}"
        exit 1
    fi
    info "All services running"
}

deploy_consul_acl_bootstrap() {
    step "  Bootstrapping Consul ACLs..."

    local env_file="${INSTALL_DIR}/docker/.env"

    # Skip-gate (#1550/#1552): only short-circuit when ALL THREE Consul token keys
    # carry a NON-EMPTY value. The original gate used `grep -q "^CONSUL_HTTP_TOKEN="`
    # which matches a blank `CONSUL_HTTP_TOKEN=` line — so a token that had been
    # emptied read as "already bootstrapped", the reconcile was skipped, and every
    # cold start served a silent 404. `-qE "^KEY=.+"` requires at least one char
    # after the `=`. If the gate does NOT pass we fall through to the reconciler,
    # which runs its own LIVE traefik/ write probe (presence is never trust — it
    # re-mints only when the probe fails).
    if grep -qE "^CONSUL_HTTP_TOKEN=.+" "$env_file" 2>/dev/null && \
       grep -qE "^BACKUP_CONSUL_HTTP_TOKEN=.+" "$env_file" 2>/dev/null && \
       grep -qE "^PROXY_BACKUP_CONSUL_TOKEN=.+" "$env_file" 2>/dev/null; then
        info "Consul ACL tokens already present — running reconciler to validate + seed"
    fi

    # Delegate to the ONE shared reconciler (docker/consul-acl-ensure.sh) that
    # install/upgrade AND every boot (systemd ExecStartPre / launchd llap-boot.sh)
    # invoke. It: polls consul liveness (non-blocking if transient), validates the
    # existing token via a live traefik/ write probe, reuses/recovers/bootstraps a
    # management token, mints scoped tokens ONLY when the probe fails, atomically
    # key-replaces the .env (never appends → no duplicate keys), seeds via
    # consul-init WITHOUT `|| true` (loud — feeds the #1551 gate), and restarts the
    # token consumers. Raw SecretIDs never touch the log; masked only.
    #
    # Consul was just started healthy by deploy_start_stack(), so the reconciler's
    # liveness poll passes immediately here. A non-zero exit on THIS path means
    # "consul up but ACL unrecoverable" (permutation a') — a hard install failure,
    # exactly like the old inline `exit 1`.
    if ! $SUDO env \
        INSTALL_DIR="${INSTALL_DIR}" \
        METADATA_DIR="${METADATA_DIR}" \
        SERVICE_USER="${SERVICE_USER}" \
        IS_MACOS="${IS_MACOS}" \
        OPT_BACKUP="${OPT_BACKUP}" \
        "${INSTALL_DIR}/docker/consul-acl-ensure.sh" >> "$LOG_FILE" 2>&1; then
        draw_box "FAILED: Consul ACL reconcile" \
            "" \
            "The Consul ACL reconciler could not provision a valid token." \
            "This usually means Consul is up but its ACL state is" \
            "unrecoverable (bootstrapped, but no valid token survives)." \
            "" \
            "Recovery options:" \
            "  1. Re-run with --purge to reset all state (DATA LOSS)" \
            "  2. Recover a management token and save it to:" \
            "       ${METADATA_DIR}/consul-bootstrap-token" \
            "     then re-run: ${INSTALL_DIR}/docker/consul-acl-ensure.sh" \
            "" \
            "Full log: ${LOG_FILE}"
        exit 1
    fi

    info "Consul ACLs reconciled with scoped tokens"
}

# ── Deploy: system service ───────────────────────────────────────────────────

deploy_install_service() {
    step "  Installing system service..."

    if [[ "$IS_MACOS" == "true" ]]; then
        local plist_dir="${HOME}/Library/LaunchAgents"
        mkdir -p "$plist_dir"
        local plist_file="${plist_dir}/com.llm-api-proxy.plist"
        cat > "$plist_file" <<PLISTEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>com.llm-api-proxy</string>
    <key>ProgramArguments</key>
    <array>
        <string>${INSTALL_DIR}/docker/llap-boot.sh</string>
    </array>
    <key>EnvironmentVariables</key>
    <dict>
        <key>INSTALL_DIR</key>
        <string>${INSTALL_DIR}</string>
        <key>METADATA_DIR</key>
        <string>${METADATA_DIR}</string>
        <key>SERVICE_USER</key>
        <string>${SERVICE_USER}</string>
        <key>IS_MACOS</key>
        <string>true</string>
        <key>OPT_BACKUP</key>
        <string>${OPT_BACKUP}</string>
    </dict>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <false/>
    <key>WorkingDirectory</key>
    <string>${INSTALL_DIR}/docker</string>
</dict>
</plist>
PLISTEOF
        launchctl load "$plist_file" 2>/dev/null || true
        info "launchd service installed"
        return 0
    fi

    local unit_file="/etc/systemd/system/llm-api-proxy.service"
    $SUDO tee "$unit_file" > /dev/null <<UNITEOF
[Unit]
Description=LLM API Proxy
Documentation=https://llm-api-proxy.com/docs
After=docker.service
Requires=docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
User=${SERVICE_USER}
Group=${SERVICE_USER}
WorkingDirectory=${INSTALL_DIR}/docker
# Consul ACL self-heal BEFORE the stack comes up (#1552). On a cold start the
# .env token may be empty/stale (the #1550 incident); the reconciler validates,
# recovers, and re-mints so consul-init can seed traefik/* and Traefik can read
# it — no silent 404. It is NON-BLOCKING on a transient/unreachable Consul (exits
# 0 so 'compose up' still brings proxy/DB up) and only fails ExecStartPre when
# Consul is UP but its ACL state is unrecoverable — in which case starting
# Traefik would just reproduce the outage, so we WANT the boot to fail loud.
#
# The '+' prefix runs THIS line with full privileges (root) regardless of the
# User= above: the reconciler must read the 0600 root:root bootstrap-token file
# and write the root:${SERVICE_USER} .env. The reconciler SELF-LOCKS via flock
# (single-flight, so a manual run and this boot hook cannot mint concurrently);
# no external flock wrapper is needed here.
ExecStartPre=+/usr/bin/env INSTALL_DIR=${INSTALL_DIR} METADATA_DIR=${METADATA_DIR} SERVICE_USER=${SERVICE_USER} OPT_BACKUP=${OPT_BACKUP} ${INSTALL_DIR}/docker/consul-acl-ensure.sh
ExecStart=${INSTALL_DIR}/compose-command.sh up -d
ExecStop=${INSTALL_DIR}/compose-command.sh down
ExecReload=${INSTALL_DIR}/compose-command.sh up -d
# Budget covers the reconciler's bounded liveness poll (~60s worst case) + the
# flock wait + 'compose up -d'. Bounded so a wedged boot fails fast instead of
# hanging systemd's start job indefinitely.
TimeoutStartSec=300
TimeoutStopSec=60

[Install]
WantedBy=multi-user.target
UNITEOF

    $SUDO systemctl daemon-reload
    $SUDO systemctl enable llm-api-proxy >> "$LOG_FILE" 2>&1
    info "systemd service installed and enabled"
}

# ── Deploy: install metadata ─────────────────────────────────────────────────

deploy_write_metadata() {
    step "  Writing install metadata..."
    local meta_file="${METADATA_DIR}/install.json"

    local features="["
    [[ "$OPT_WAF" == "true" ]] && features+='"waf",'
    [[ "$OPT_TLS" == "true" ]] && features+='"tls",'
    [[ "$OPT_BACKUP" == "true" ]] && features+='"backup",'
    [[ "$OPT_MONITORING" == "true" ]] && features+='"monitoring",'
    [[ "$OPT_MDNS" == "true" ]] && features+='"mdns",'
    features="${features%,}]"

    $SUDO tee "$meta_file" > /dev/null <<METAEOF
{
  "install_dir": "${INSTALL_DIR}",
  "installed_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "installed_by": "install.sh ${INSTALLER_VERSION}",
  "version": "${OPT_VERSION}",
  "os": "${OS_ID}-${OS_VERSION}",
  "arch": "${ARCH}",
  "features": ${features},
  "tos_accepted_at": "${TOS_ACCEPTED_AT:-}",
  "tos_sha256": "${TOS_SHA256:-}",
  "tos_accepted_by": "$(whoami)"
}
METAEOF

    $SUDO chmod 0644 "$meta_file"
    echo "${OPT_VERSION}" | $SUDO tee "${INSTALL_DIR}/.version" > /dev/null
    info "Metadata written to ${meta_file}"
}

# ── Deploy: open browser ─────────────────────────────────────────────────────

deploy_open_browser() {
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        return 0
    fi

    local url
    if [[ "$OPT_TLS" == "true" ]]; then
        url="https://${OPT_DOMAIN}"
    else
        local ip
        ip=$(ip -6 addr show scope global 2>/dev/null | awk '/inet6 /{split($2,a,"/"); print a[1]; exit}' || true)
        [[ -z "$ip" ]] && ip=$(hostname -I 2>/dev/null | awk '{print $1}' || echo "localhost")
        url="http://${ip}"
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        open "$url" 2>/dev/null || true
    elif [[ -n "${DISPLAY:-}" ]] || [[ -n "${WAYLAND_DISPLAY:-}" ]]; then
        if command -v xdg-open &>/dev/null; then
            xdg-open "$url" 2>/dev/null || true
        fi
    fi
}

# ── Deploy: post-install summary ─────────────────────────────────────────────

deploy_post_install_summary() {
    local url service_cmd log_cmd
    if [[ "$OPT_TLS" == "true" ]]; then
        url="https://${OPT_DOMAIN}"
    else
        local ip
        ip=$(ip -6 addr show scope global 2>/dev/null | awk '/inet6 /{split($2,a,"/"); print a[1]; exit}' || true)
        [[ -z "$ip" ]] && ip=$(hostname -I 2>/dev/null | awk '{print $1}' || echo "localhost")
        url="http://${ip}"
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        service_cmd="launchctl list | grep llm-api-proxy"
        log_cmd="${INSTALL_DIR}/compose-command.sh logs -f"
    else
        service_cmd="systemctl status llm-api-proxy"
        log_cmd="${INSTALL_DIR}/compose-command.sh logs -f"
    fi

    draw_box "Installation complete!" \
        "" \
        "Dashboard:  ${url}" \
        "Status:     ${service_cmd}" \
        "Logs:       ${log_cmd}" \
        "Config:     ${INSTALL_DIR}/docker/.env" \
        "" \
        "Complete the setup wizard in your browser" \
        "to create your first admin account." \
        "" \
        "Useful commands:" \
        "  Restart: systemctl restart llm-api-proxy" \
        "  Stop:    systemctl stop llm-api-proxy" \
        "  Upgrade: re-run install.sh" \
        "" \
        "Docs: https://llm-api-proxy.com/docs"
}

# ── Deploy: orchestrator ─────────────────────────────────────────────────────

run_deploy() {
    step "[5/5] Deploying..."

    # Capture exact source files and durable recovery identity before the first
    # target Compose/.env mutation for both stable forward upgrades and
    # database-backed rollbacks.
    if database_source_snapshot_required_for_deploy; then
        database_snapshot_source_deploy_state
    fi

    if [[ "$COMMAND" == "upgrade" ]]; then
        deploy_backup_compose_files
    fi

    deploy_create_dirs
    deploy_extract_files

    if [[ "$COMMAND" == "upgrade" ]]; then
        deploy_upgrade_env
    else
        deploy_write_env
    fi

    deploy_write_container_dns_overlay
    deploy_write_compose_command
    # Fail BEFORE touching the running stack if any bind-mount source is missing
    # or the wrong type (#1390) — never let `compose up` auto-create a directory
    # at a config-file mount path and take ingress down mid-deploy.
    deploy_verify_bind_mounts
    ghcr_login
    deploy_pull_images
    deploy_handle_database_transition
    deploy_start_stack
    deploy_consul_acl_bootstrap
    deploy_start_remaining_services
    configure_nftables_docker_forward
    deploy_install_service
    deploy_write_metadata
    deploy_complete_database_transition
    deploy_post_install_summary
    deploy_open_browser
}

run_verified_recovery_preflight() {
    INSTALL_PHASE="verification"
    if ! run_installer_verification; then
        return 1
    fi

    # A journaled source deployment must be recovered immediately after the
    # installer and host-access boundary is verified. Target credentials,
    # debug prompts, registry probes, and image/network checks are deliberately
    # later so a broken or unavailable target cannot make recovery unreachable.
    INSTALL_PHASE="recovery"
    if ! database_reconcile_pending_recovery_before_configuration; then
        return 1
    fi

    resolve_github_token
    if [[ -n "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        detect_github_user
    fi
    load_debug_state_from_env
    warn_debug_mode

    INSTALL_PHASE="preflight"
    run_preflight
}

run_post_preflight_phases() {
    INSTALL_PHASE="legal"
    run_tos

    INSTALL_PHASE="prepare"
    run_prepare

    INSTALL_PHASE="configure"
    run_configure

    INSTALL_PHASE="deploy"
    run_deploy
}

# ── Uninstall ────────────────────────────────────────────────────────────────

run_uninstall() {
    step "Uninstalling LLM API Proxy..."

    local meta_file="${METADATA_DIR:-/etc/llm-api-proxy}/install.json"
    if [[ -f "$meta_file" ]]; then
        INSTALL_DIR=$(jq -r '.install_dir' "$meta_file" 2>/dev/null || echo "$INSTALL_DIR")
    fi

    if [[ ! -d "$INSTALL_DIR" ]]; then
        die "No installation found at ${INSTALL_DIR}"
    fi

    if [[ -x "${INSTALL_DIR}/compose-command.sh" ]]; then
        $SUDO "${INSTALL_DIR}/compose-command.sh" down >> "$LOG_FILE" 2>&1 || true
        info "Stack stopped"
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        local plist="${HOME}/Library/LaunchAgents/com.llm-api-proxy.plist"
        launchctl unload "$plist" 2>/dev/null || true
        rm -f "$plist"
    else
        $SUDO systemctl stop llm-api-proxy 2>/dev/null || true
        $SUDO systemctl disable llm-api-proxy 2>/dev/null || true
        $SUDO rm -f /etc/systemd/system/llm-api-proxy.service
        $SUDO systemctl daemon-reload 2>/dev/null || true
    fi
    info "System service removed"

    $SUDO rm -rf "$INSTALL_DIR"
    info "Install directory removed: ${INSTALL_DIR}"

    if [[ "$IS_MACOS" != "true" ]] && id "$SERVICE_USER" &>/dev/null; then
        $SUDO userdel "$SERVICE_USER" 2>/dev/null || true
        info "System user '${SERVICE_USER}' removed"
    fi

    $SUDO rm -rf "$METADATA_DIR"
    info "Metadata removed"

    if [[ "$OPT_PURGE" == "true" ]]; then
        echo ""
        warn "WARNING: --purge will delete ALL data including the database!"
        if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
            local confirm
            read -r -p "  Type YES to confirm volume deletion: " confirm
            if [[ "$confirm" != "YES" ]]; then
                info "Volume purge cancelled"
                return 0
            fi
        fi

        local -a volumes=("docker_timescaledb_data" "docker_consul_data")
        $SUDO docker volume rm "${volumes[@]}" 2>/dev/null || true
        $SUDO docker volume rm "docker_acme_data" "docker_proxy_ca_data" 2>/dev/null || true
        $SUDO docker volume rm "docker_prometheus_data" "docker_grafana_data" 2>/dev/null || true
        info "Docker volumes purged"
    fi

    info "Uninstall complete"
}

# ── Source-only mode for testing ──────────────────────────────────────────────
# When sourced by BATS with --source-only, all functions above are now defined.
# Return here to skip the main execution block below.
# shellcheck disable=SC2317  # Intentional: `return` succeeds when sourced; `exit` is the fallback for `bash file.sh --source-only`
if [[ "${1:-}" == "--source-only" ]]; then
    return 0 2>/dev/null || exit 0
fi

# ── Main entry point ─────────────────────────────────────────────────────────

main() {
    require_file_backed_execution
    log_init "$@"
    parse_args "$@"
    if [[ "$OPT_VERIFY_SELF_CHECKSUM" == "true" ]]; then
        verify_self_checksum
        return 0
    fi
    apply_env_defaults

    # Auto-detect non-TTY automation and force non-interactive mode.
    # Interactive prompts (dialog, read) cannot work with redirected stdin.
    if [[ ! -t 0 ]] && [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        OPT_NON_INTERACTIVE="true"
        OPT_ACCEPT_TOS="true"
        log "Auto-detected non-TTY execution — forcing non-interactive mode"
    fi

    detect_dialog
    detect_os
    detect_arch

    case "${COMMAND:-}" in
        uninstall)
            run_uninstall
            exit 0
            ;;
    esac

    if ! run_verified_recovery_preflight; then
        return 1
    fi
    run_post_preflight_phases

    INSTALL_PHASE=""
    info "Installation complete!"
}

